{
  "name": "Cake Customizer Studio",
  "description": "A delightful interactive application to design your perfect cake, choosing sizes, flavors, fillings, and decoration styles with real-time previews."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Step = 'SIZE' | 'FLAVOR' | 'DECORATION' | 'SUMMARY';

export type HeightType = 'TALL' | 'SHORT';

export interface CakeSize {
  id: string;
  diameter: number;
  heightType: HeightType;
  portions: string;
  price: number;
}

export interface Flavor {
  id: string;
  name: string;
  color: string;
  pattern?: string;
}

export interface Filling {
  id: string;
  name: string;
  color: string;
  pattern?: string;
}

export type DecorationStyle = 'minimalist' | 'floral' | 'sprinkles' | 'ombre';

export interface AppState {
  step: Step;
  selectedSize: CakeSize | null;
  selectedFlavor: Flavor | null;
  selectedFilling: Filling | null;
  selectedDecoration: DecorationStyle;
  totalPrice: number;
}

import React, { useState, useMemo } from 'react';
import { Step, AppState, CakeSize, Flavor, Filling, DecorationStyle } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import SummaryStep from './components/SummaryStep';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: CAKE_SIZES[0],
    selectedFlavor: FLAVORS[0],
    selectedFilling: FILLINGS[1], // Areq as default in reference
    selectedDecoration: 'minimalist',
    totalPrice: 45,
  });

  const nextStep = () => {
    setState(prev => {
      if (prev.step === 'SIZE') return { ...prev, step: 'FLAVOR' };
      if (prev.step === 'FLAVOR') return { ...prev, step: 'DECORATION' };
      if (prev.step === 'DECORATION') return { ...prev, step: 'SUMMARY' };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      if (prev.step === 'FLAVOR') return { ...prev, step: 'SIZE' };
      if (prev.step === 'DECORATION') return { ...prev, step: 'FLAVOR' };
      if (prev.step === 'SUMMARY') return { ...prev, step: 'DECORATION' };
      return prev;
    });
  };

  const updateSize = (size: CakeSize) => {
    setState(prev => ({ ...prev, selectedSize: size, totalPrice: size.price }));
  };

  const updateFlavor = (flavor: Flavor) => {
    setState(prev => ({ ...prev, selectedFlavor: flavor }));
  };

  const updateFilling = (filling: Filling) => {
    setState(prev => ({ ...prev, selectedFilling: filling }));
  };

  const updateDecoration = (decor: DecorationStyle) => {
    setState(prev => ({ ...prev, selectedDecoration: decor }));
  };

  return (
    <div className="min-h-screen max-w-md mx-auto relative flex flex-col bg-background-light shadow-2xl overflow-hidden">
      {state.step === 'SIZE' && (
        <SizeStep 
          selectedSize={state.selectedSize} 
          onSelectSize={updateSize} 
          onNext={nextStep} 
        />
      )}
      {state.step === 'FLAVOR' && (
        <FlavorStep 
          selectedFlavor={state.selectedFlavor}
          selectedFilling={state.selectedFilling}
          onSelectFlavor={updateFlavor}
          onSelectFilling={updateFilling}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
        />
      )}
      {state.step === 'DECORATION' && (
        <DecorationStep 
          selectedDecoration={state.selectedDecoration}
          onSelectDecoration={updateDecoration}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
        />
      )}
      {state.step === 'SUMMARY' && (
        <SummaryStep 
          appState={state}
          onBack={prevStep}
          onReset={() => setState({
             step: 'SIZE',
             selectedSize: CAKE_SIZES[0],
             selectedFlavor: FLAVORS[0],
             selectedFilling: FILLINGS[1],
             selectedDecoration: 'minimalist',
             totalPrice: 45,
          })}
        />
      )}
    </div>
  );
};

export default App;

import { CakeSize, Flavor, Filling } from './types';

