export default SizeStep;

import React, { useRef, useEffect } from 'react';
import { CakeSize, HeightType } from '../types';
import { CAKE_SIZES } from '../constants';

interface SizeStepProps {
  selectedSize: CakeSize | null;
  onSelectSize: (size: CakeSize) => void;
  onNext: () => void;
}

const SizeStep: React.FC<SizeStepProps> = ({ selectedSize, onSelectSize, onNext }) => {
  const diameters = [14, 16, 18, 20, 22, 24];
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentDiameter = selectedSize?.diameter || 18;
  const currentHeight = selectedSize?.heightType || 'TALL';

  // Toggle height for the current selected diameter
  const handleHeightToggle = (h: HeightType) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === h);
    if (newSize) onSelectSize(newSize);
  };

  // Select a specific cake from the lineup
  const handleSelect = (d: number) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);
    if (newSize) onSelectSize(newSize);
  };

  // Center the selected item on mount or change
  useEffect(() => {
    if (scrollRef.current) {
      const selectedEl = scrollRef.current.querySelector(`[data-diameter="${currentDiameter}"]`);
      if (selectedEl) {
        selectedEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }
  }, [currentDiameter]);

  return (
    <div className="flex flex-col h-full animate-fadeIn bg-background-light overflow-hidden">
      <header className="pt-8 pb-2 px-6 flex justify-between items-center relative z-20 bg-background-light/80 backdrop-blur-md">
        <button className="p-2 rounded-full bg-white shadow-sm text-primary">
          <span className="material-icons-round">arrow_back</span>
        </button>
        <div className="text-center">
          <h1 className="font-display text-xl text-primary uppercase tracking-tight">Elige el Tamaño</h1>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Desliza para comparar</p>
        </div>
        <button className="p-2 rounded-full bg-white shadow-sm text-primary">
          <span className="material-icons-round">straighten</span>
        </button>
      </header>

      {/* Global Height Toggle */}
      <div className="px-6 py-4 z-20">
        <div className="flex p-1 bg-gray-200/50 rounded-2xl">
          <button 
            onClick={() => handleHeightToggle('SHORT')}
            className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-bold transition-all ${currentHeight === 'SHORT' ? 'bg-white text-primary shadow-sm' : 'text-gray-500'}`}
          >
            <span className="material-icons-round text-sm">reorder</span>
            BAJO (10cm)
          </button>
          <button 
            onClick={() => handleHeightToggle('TALL')}
            className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-bold transition-all ${currentHeight === 'TALL' ? 'bg-white text-primary shadow-sm' : 'text-gray-500'}`}
          >
            <span className="material-icons-round text-sm">height</span>
            ALTO (17cm)
          </button>
        </div>
      </div>

      {/* Visual Lineup Comparison */}
      <main className="flex-1 flex flex-col relative">
        {/* Comparison Background Grid */}
        <div className="absolute inset-0 flex flex-col justify-end pb-32 pointer-events-none opacity-20">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="w-full border-t border-gray-400 h-10 flex items-start px-2">
              <span className="text-[8px] font-mono text-gray-500">{i * 5}cm</span>
            </div>
          ))}
        </div>

        <div 
          ref={scrollRef}
          className="flex-1 flex items-end gap-8 overflow-x-auto no-scrollbar px-12 pb-32 pt-10 snap-x snap-mandatory"
        >
          {diameters.map((d) => {
            const isSelected = currentDiameter === d;
            // Scale logic: base size for 14cm is 120px, up to 24cm which is ~220px
            const width = 100 + (d - 14) * 12;
            const height = currentHeight === 'TALL' ? 150 : 85;

            return (
              <div 
                key={d} 
                data-diameter={d}
                onClick={() => handleSelect(d)}
                className={`snap-center flex flex-col items-center transition-all duration-500 cursor-pointer ${isSelected ? 'scale-110' : 'scale-90 opacity-40 grayscale-[0.5]'}`}
              >
                {/* Cake Container */}
                <div className="relative" style={{ width: `${width}px` }}>
                  {/* The Cake SVG */}
                  <svg 
                    viewBox={`0 0 ${width} ${height + 30}`} 
                    width={width} 
                    height={height + 30}
                    className="drop-shadow-2xl transition-all duration-500"
                  >
                    {/* Shadow on floor */}
                    <ellipse cx={width/2} cy={height + 15} rx={width/2} ry="8" fill="rgba(0,0,0,0.05)" />

                    {/* Cake Body */}
                    <path 
                      d={`M0 20 L0 ${height} Q${width/2} ${height + 20} ${width} ${height} L${width} 20`} 
                      fill={currentHeight === 'TALL' ? '#F43F5E' : '#FDE047'} 
                    />

                    {/* Cake Top */}
                    <ellipse cx={width/2} cy="20" rx={width/2} ry="12" fill={currentHeight === 'TALL' ? '#FFF1F2' : '#FEF9C3'} />

                    {/* Diameter Text */}
                    <text 
                      x="50%" 
                      y={height/2 + 15} 
                      textAnchor="middle" 
                      className="font-display fill-white/80 text-xl"
                    >
                      {d}
                    </text>
                  </svg>

                  {/* Portions Badge */}
                  {isSelected && (
                    <div className="absolute -top-12 left-1/2 -translate-x-1/2 whitespace-nowrap bg-primary text-white text-[10px] font-bold px-3 py-1 rounded-full shadow-lg animate-bounce">
                      {CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight)?.portions}
                    </div>
                  )}
                </div>

                <div className={`mt-4 font-display text-lg ${isSelected ? 'text-primary' : 'text-gray-400'}`}>
                  {d}cm
                </div>
              </div>
            );
          })}
        </div>
      </main>

      {/* Footer Info */}
      <footer className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white rounded-t-[2.5rem] shadow-[0_-15px_40px_rgba(0,0,0,0.08)] p-6 z-50">
        <div className="flex items-center justify-between mb-6 px-2">
          <div className="flex flex-col">
            <div className="flex items-center gap-1.5 mb-1">
               <span className="w-2 h-2 rounded-full bg-primary animate-pulse"></span>
               <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Resumen de Tamaño</span>
            </div>
            <div className="flex items-baseline gap-2">
              <span className="text-3xl font-display text-gray-800">{currentDiameter}cm</span>
              <span className="text-sm font-bold text-primary uppercase">{currentHeight === 'TALL' ? 'Alto' : 'Bajo'}</span>
            </div>
          </div>
          <div className="text-right">
            <span className="text-3xl font-display text-primary">${selectedSize?.price.toFixed(2)}</span>
            <span className="block text-[10px] font-bold text-gray-400 uppercase">Precio Estimado</span>
          </div>
        </div>

        <button 
          onClick={onNext}
          className="w-full bg-primary hover:bg-rose-600 text-white font-bold py-4 rounded-2xl shadow-xl shadow-primary/20 transform transition active:scale-[0.98] flex items-center justify-center gap-3"
        >
          <span className="text-lg">Personalizar Sabores</span>
          <span className="material-icons-round">chevron_right</span>
        </button>
      </footer>
    </div>
  );
};

