import React, { useRef, useEffect } from 'react';
import { CakeSize, HeightType } from '../types';
import { CAKE_SIZES } from '../constants';

interface SizeStepProps {
  selectedSize: CakeSize | null;
  onSelectSize: (size: CakeSize) => void;
  onNext: () => void;
}

const SizeStep: React.FC<SizeStepProps> = ({ selectedSize, onSelectSize, onNext }) => {
  const diameters = [14, 16, 18, 20, 22, 24];
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentDiameter = selectedSize?.diameter || 18;
  const currentHeight = selectedSize?.heightType || 'TALL';

  // Find the current cake data to get portions
  const currentCakeData = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === currentHeight);

  // Toggle height for the current selected diameter
  const handleHeightToggle = (h: HeightType) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === h);
    if (newSize) onSelectSize(newSize);
  };

  // Select a specific cake from the lineup
  const handleSelect = (d: number) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);
    if (newSize) onSelectSize(newSize);
  };

  // Center the selected item on mount or change
  useEffect(() => {
    if (scrollRef.current) {
      const selectedEl = scrollRef.current.querySelector(`[data-diameter="${currentDiameter}"]`);
      if (selectedEl) {
        selectedEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }
  }, [currentDiameter]);

  return (
    <div className="flex flex-col h-full animate-fadeIn bg-background-light overflow-hidden">
      <header className="pt-8 pb-2 px-6 flex justify-between items-center relative z-20 bg-background-light/80 backdrop-blur-md">
        <button className="p-2 rounded-full bg-white shadow-sm text-primary">
          <span className="material-icons-round">arrow_back</span>
        </button>
        <div className="text-center">
          <h1 className="font-display text-xl text-primary uppercase tracking-tight">Elige el Tamaño</h1>
