import React, { useState, useCallback, useMemo } from 'react';
import { Step, AppState, CakeSize, Flavor, Filling, DecorationStyle, TopperType } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: CAKE_SIZES[0],
    selectedFlavor: FLAVORS[0],
    selectedFilling: FILLINGS[1],
    selectedDecoration: 'minimalist',
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFlavor: '',
    customFilling: '',
  });

  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    const size = partial.selectedSize || state.selectedSize;
    const flavor = partial.selectedFlavor || state.selectedFlavor;
    const filling = partial.selectedFilling || state.selectedFilling;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;

    const base = size?.basePrice || 0;
    const fMod = flavor?.priceModifier || 0;
    const fillMod = filling?.priceModifier || 0;
    const decorMod = DECORATIONS[decorId]?.priceModifier || 0;

    const topperMod = TOPPER_PRICES[topper] || 0;
    const spheresMod = spheres ? SPHERES_PRICE : 0;

    const coverageMod = coverage === 'chocolate' ? 5 : coverage === 'arequipe' ? 4 : 0;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod;
  }, [state]);

  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  const updateSize = (size: CakeSize) => {
    const newPrice = calculateTotal({ selectedSize: size });
    setState(prev => ({ ...prev, selectedSize: size, totalPrice: newPrice }));
  };

  const updateFlavor = (flavor: Flavor) => {
    const newPrice = calculateTotal({ selectedFlavor: flavor });
    setState(prev => ({ ...prev, selectedFlavor: flavor, totalPrice: newPrice }));
  };

  const updateFilling = (filling: Filling) => {
    const newPrice = calculateTotal({ selectedFilling: filling });
    setState(prev => ({ ...prev, selectedFilling: filling, totalPrice: newPrice }));
  };

  const updateDecoration = (data: Partial<AppState>) => {
    const newPrice = calculateTotal(data);
    setState(prev => ({ ...prev, ...data, totalPrice: newPrice }));
  };

  const updatePersonalization = (data: Partial<AppState>) => {
    const newPrice = data.coverageType ? calculateTotal({ coverageType: data.coverageType }) : state.totalPrice;
    setState(prev => ({ ...prev, ...data, totalPrice: newPrice }));
  };

  const handleFinalizeOrder = () => {
    const deposit = state.totalPrice / 2;
    const flavorDisplay = state.selectedFlavor?.name;
    const isCustomFilling = state.selectedFilling?.id === 'others';
    const fillingDisplay = isCustomFilling 
      ? `Otros: ${state.customFilling}` 
      : state.selectedFilling?.name;

    const topperDisplay = {
        none: 'Sin Topper',
        generic: 'Topper Genérico',
        personalized: 'Topper Personalizado',
        plus_pieces: 'Topper + Piezas Decorativas'
    }[state.topperType];

    const priceNote = isCustomFilling ? "\n⚠️ *NOTA:* Seleccioné un sabor personalizado, espero confirmación del costo final." : "";

