📍 *TAMAÑO Y COBERTURA*
- Diámetro: ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType === 'TALL' ? 'Alto' : 'Bajo'})
- Cobertura: ${state.coverageType.toUpperCase()}
- Capacidad: ${state.selectedSize?.portions}

🍰 *SABORES*
- Bizcocho: ${flavorDisplay}
- Relleno: ${fillingDisplay}
- Estilo: ${DECORATIONS[state.selectedDecoration].label}
${priceNote}

✨ *DECORACIÓN EXTRA*
- Topper: ${topperDisplay}
- Esferas Decorativas: ${state.hasSpheres ? 'Sí' : 'No'}

🎉 *DATOS DEL EVENTO*
- Temática: ${state.theme}
- Para: ${state.birthdayName} (${state.birthdayAge} años)
- Requerimientos: ${state.specialRequirements || 'Ninguno'}

🚚 *ENTREGA*
- Método: ${state.deliveryMethod === 'DELIVERY' ? 'Domicilio' : 'Retiro en tienda (Pickup)'}
- Fecha: ${state.deliveryDate}
- Hora: ${state.deliveryTime}

💰 *DETALLES DEL PAGO (Tasa Euro)*
- Total Estimado: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Ref. Transferencia: ${state.paymentReference}
- Monto en Bs: ${state.amountBs}

📸 _Envío fotos de referencia y captura del comprobante a continuación._`;

    const encodedMessage = encodeURIComponent(message);
    const whatsappNumber = "584241546473"; 
    window.open(`https://wa.me/${whatsappNumber}?text=${encodedMessage}`, '_blank');
  };

  return (
    <div className="min-h-screen max-w-md mx-auto relative flex flex-col bg-background-light shadow-2xl overflow-hidden font-quicksand">
      {state.step === 'SIZE' && (
        <SizeStep 
          selectedSize={state.selectedSize} 
          onSelectSize={updateSize} 
          onNext={nextStep} 
        />
      )}
      {state.step === 'FLAVOR' && (
        <FlavorStep 
          selectedFlavor={state.selectedFlavor}
          selectedFilling={state.selectedFilling}
          onSelectFlavor={updateFlavor}
          onSelectFilling={updateFilling}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
          customFlavor={state.customFlavor}
          onCustomFlavorChange={(val) => setState(prev => ({...prev, customFlavor: val}))}
          customFilling={state.customFilling}
          onCustomFillingChange={(val) => setState(prev => ({...prev, customFilling: val}))}
        />
      )}
      {state.step === 'DECORATION' && (
        <DecorationStep 
          selectedDecoration={state.selectedDecoration}
          topperType={state.topperType}
          hasSpheres={state.hasSpheres}
          onUpdateDecoration={updateDecoration}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
        />
      )}
      {state.step === 'PERSONALIZATION' && (
        <PersonalizationStep 
          appState={state}
          onUpdate={updatePersonalization}
          onNext={nextStep}
          onBack={prevStep}
        />
      )}
      {state.step === 'SUMMARY' && (
        <SummaryStep 
          appState={state}
          onBack={prevStep}
          onConfirm={nextStep}
        />
      )}
      {state.step === 'PAYMENT' && (
        <PaymentStep 
          totalPrice={state.totalPrice}
          paymentReference={state.paymentReference}
          amountBs={state.amountBs}
          onUpdatePayment={(data) => setState(p => ({...p, ...data}))}
          onBack={prevStep}
          onComplete={handleFinalizeOrder}
        />
      )}
    </div>
  );
};

export default App;

