import React, { useState, useCallback, useMemo } from 'react';
import { Step, AppState, CakeSize, Flavor, Filling, DecorationStyle, TopperType } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';

const App: React.FC = () => {
  // ESTADO INICIAL DE LA APLICACIÓN
  // Aquí se guardan todas las selecciones del usuario
  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: CAKE_SIZES[0],
    selectedFlavor: FLAVORS[0],
    selectedFilling: FILLINGS[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFlavor: '',
    customFilling: '',
  });

  /**
   * LÓGICA DE CÁLCULO DE PRECIOS
   * Esta función suma todos los modificadores (tamaño + sabor + relleno + decoración + extras)
   */
  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    const size = partial.selectedSize || state.selectedSize;
    const flavor = partial.selectedFlavor || state.selectedFlavor;
    const filling = partial.selectedFilling || state.selectedFilling;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;
    const currentColors = partial.cakeColors || state.cakeColors;

    const base = size?.basePrice || 0;
    const fMod = flavor?.priceModifier || 0;
    const fillMod = filling?.priceModifier || 0;
    const decorMod = DECORATIONS[decorId]?.priceModifier || 0;

    const topperMod = TOPPER_PRICES[topper] || 0;
    const spheresMod = spheres ? SPHERES_PRICE : 0;

    // Si algún color es "saturado", aplicamos el recargo una sola vez
    let colorSurcharge = 0;
    const hasSaturated = currentColors.some(hex => 
        CAKE_COLORS.find(c => c.hex === hex)?.isSaturated
    );
    if (hasSaturated) colorSurcharge = SATURATED_COLOR_SURCHARGE;

    // Recargo por cobertura especial (Chocolate o Arequipe)
    const coverageMod = coverage === 'chocolate' ? 5 : coverage === 'arequipe' ? 4 : 0;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod + colorSurcharge;
  }, [state]);

  // Funciones para navegar entre pasos
  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  // Funciones para actualizar selecciones individuales y recalcular precio
  const updateSize = (size: CakeSize) => {
    const newPrice = calculateTotal({ selectedSize: size });
    setState(prev => ({ ...prev, selectedSize: size, totalPrice: newPrice }));
  };

  const updateFlavor = (flavor: Flavor) => {
    const newPrice = calculateTotal({ selectedFlavor: flavor });
    setState(prev => ({ ...prev, selectedFlavor: flavor, totalPrice: newPrice }));
  };

  const updateFilling = (filling: Filling) => {
    const newPrice = calculateTotal({ selectedFilling: filling });
    setState(prev => ({ ...prev, selectedFilling: filling, totalPrice: newPrice }));
  };

  const updateDecoration = (data: Partial<AppState>) => {
    const newPrice = calculateTotal(data);
    setState(prev => ({ ...prev, ...data, totalPrice: newPrice }));
  };

  const updatePersonalization = (data: Partial<AppState>) => {
    const newPrice = data.coverageType ? calculateTotal({ coverageType: data.coverageType }) : state.totalPrice;
    setState(prev => ({ ...prev, ...data, totalPrice: newPrice }));
  };

  /**
   * ENVÍO DEL PEDIDO A WHATSAPP
   * Aquí se genera el texto final que recibe el vendedor.
   */
  const handleFinalizeOrder = () => {
    const deposit = state.totalPrice / 2;
    const flavorDisplay = state.selectedFlavor?.name;
    const isCustomFilling = state.selectedFilling?.id === 'others';
    const fillingDisplay = isCustomFilling 
      ? `Otros: ${state.customFilling}` 
      : state.selectedFilling?.name;

    const topperDisplay = {
        none: 'Sin Topper',
        generic: 'Topper Genérico',
        personalized: 'Topper Personalizado',
        plus_pieces: 'Topper + Piezas Decorativas'
    }[state.topperType];

    const colorNames = state.cakeColors.map(hex => 
        CAKE_COLORS.find(c => c.hex === hex)?.name || 'Personalizado'
    ).join(', ');

    const priceNote = isCustomFilling ? "\n⚠️ *NOTA:* Seleccioné un sabor personalizado, espero confirmación del costo final." : "";

    // PLANTILLA DEL MENSAJE
    const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂

Hola, confirmo mi pedido con los siguientes detalles:

📍 *TAMAÑO Y COBERTURA*
- Diámetro: ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType === 'TALL' ? 'Alto' : 'Bajo'})
- Cobertura: ${state.coverageType.toUpperCase()}
- Capacidad: ${state.selectedSize?.portions}

🍰 *SABORES*
- Bizcocho: ${flavorDisplay}
- Relleno: ${fillingDisplay}
- Estilo: ${DECORATIONS[state.selectedDecoration].label}
- Colores: ${colorNames}
${priceNote}

✨ *DECORACIÓN EXTRA*
- Topper: ${topperDisplay}
- Esferas Decorativas: ${state.hasSpheres ? 'Sí' : 'No'}

🎉 *DATOS DEL EVENTO*
- Temática: ${state.theme}
- Para: ${state.birthdayName} (${state.birthdayAge} años)
- Requerimientos: ${state.specialRequirements || 'Ninguno'}

🚚 *ENTREGA*
- Método: ${state.deliveryMethod === 'DELIVERY' ? 'Domicilio' : 'Retiro en tienda (Pickup)'}
- Fecha: ${state.deliveryDate}
- Hora: ${state.deliveryTime}

💰 *DETALLES DEL PAGO (Tasa Euro)*
- Total Estimado: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Ref. Transferencia: ${state.paymentReference}
- Monto en Bs: ${state.amountBs}

📸 _Envío fotos de referencia y captura del comprobante a continuación._`;

    const encodedMessage = encodeURIComponent(message);
    const whatsappNumber = "584241546473"; // CAMBIA ESTE NÚMERO POR EL TUYO
    window.open(`https://wa.me/${whatsappNumber}?text=${encodedMessage}`, '_blank');
  };

  return (
    <div className="min-h-screen max-w-md mx-auto relative flex flex-col bg-background-light shadow-2xl overflow-hidden font-quicksand">
      {/* RENDERIZADO DE LOS COMPONENTES SEGÚN EL PASO ACTUAL */}
      {state.step === 'SIZE' && (
        <SizeStep 
          selectedSize={state.selectedSize} 
          onSelectSize={updateSize} 
          onNext={nextStep} 
        />
      )}
      {state.step === 'FLAVOR' && (
        <FlavorStep 
          selectedFlavor={state.selectedFlavor}
          selectedFilling={state.selectedFilling}
          onSelectFlavor={updateFlavor}
          onSelectFilling={updateFilling}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
          customFlavor={state.customFlavor}
          onCustomFlavorChange={(val) => setState(prev => ({...prev, customFlavor: val}))}
          customFilling={state.customFilling}
          onCustomFillingChange={(val) => setState(prev => ({...prev, customFilling: val}))}
        />
      )}
      {state.step === 'DECORATION' && (
        <DecorationStep 
          selectedDecoration={state.selectedDecoration}
          cakeColors={state.cakeColors}
          topperType={state.topperType}
          hasSpheres={state.hasSpheres}
          onUpdateDecoration={updateDecoration}
          onNext={nextStep}
          onBack={prevStep}
          totalPrice={state.totalPrice}
        />
      )}
      {state.step === 'PERSONALIZATION' && (
        <PersonalizationStep 
          appState={state}
          onUpdate={updatePersonalization}
          onNext={nextStep}
          onBack={prevStep}
        />
      )}
      {state.step === 'SUMMARY' && (
        <SummaryStep 
          appState={state}
          onBack={prevStep}
          onConfirm={nextStep}
        />
      )}
      {state.step === 'PAYMENT' && (
        <PaymentStep 
          totalPrice={state.totalPrice}
          paymentReference={state.paymentReference}
          amountBs={state.amountBs}
          onUpdatePayment={(data) => setState(p => ({...p, ...data}))}
          onBack={prevStep}
          onComplete={handleFinalizeOrder}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { DecorationStyle, TopperType, AppState } from '../types';
import { CAKE_COLORS } from '../constants';

interface DecorationStepProps {
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  onUpdateDecoration: (data: Partial<AppState>) => void;
  onNext: () => void;
  onBack: () => void;
  totalPrice: number;
}

const DecorationStep: React.FC<DecorationStepProps> = ({ 
  selectedDecoration, 
  cakeColors,
  topperType,
  hasSpheres,
  onUpdateDecoration, 
  onNext, 
  onBack,
  totalPrice 
}) => {
  // CONFIGURACIÓN DE ICONOS Y TEXTOS PARA LOS ACABADOS
  const styles = {
    liso: { label: "Liso", desc: "Acabado liso y limpio.", icon: "crop_square" },
    vintage: { label: "Vintage", desc: "Volantes y rosetones.", icon: "auto_awesome" },
    textura: { label: "Textura", desc: "Rayado horizontal.", icon: "reorder" },
    degradado: { label: "Degradado", desc: "Efecto Ombré.", icon: "opacity" }
  };

  // TIPOS DE TOPPER DISPONIBLES
  const toppers: { id: TopperType; label: string; icon: string }[] = [
    { id: 'none', label: 'Sin Topper', icon: 'do_not_disturb_on' },
    { id: 'generic', label: 'Genérico', icon: 'star' },
    { id: 'personalized', label: 'Personalizado', icon: 'edit' },
    { id: 'plus_pieces', label: 'Topper + Piezas', icon: 'auto_fix_high' },
  ];

  /**
   * MANEJO DE SELECCIÓN DE COLORES
   * - Si es degradado, permite seleccionar hasta 3.
   * - Si es liso/textura, solo permite 1.
   */
  const handleColorClick = (hex: string) => {
    if (selectedDecoration !== 'degradado') {
      onUpdateDecoration({ cakeColors: [hex] });
    } else {
      if (cakeColors.includes(hex)) {
        if (cakeColors.length > 1) {
          onUpdateDecoration({ cakeColors: cakeColors.filter(c => c !== hex) });
        }
      } else {
        if (cakeColors.length < 3) {
          onUpdateDecoration({ cakeColors: [...cakeColors, hex] });
        }
      }
    }
  };

  /**
   * DIBUJO DEL PASTEL (SVG)
   * Renderiza el degradado o el color sólido según la selección.
   */
  const renderCakeBody = () => {
    if (selectedDecoration === 'degradado') {
      const stops = cakeColors.length === 1 
        ? [{ offset: '0%', color: '#FFFFFF' }, { offset: '100%', color: cakeColors[0] }]
        : cakeColors.map((color, i) => ({ offset: `${(i / (cakeColors.length - 1)) * 100}%`, color }));

      return (
        <g>
          <defs>
            <linearGradient id="cakeGrad" x1="0%" y1="0%" x2="0%" y2="100%">
              {stops.map((stop, i) => <stop key={i} offset={stop.offset} stopColor={stop.color} />)}
            </linearGradient>
          </defs>
          <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill="url(#cakeGrad)" stroke="#D1D5DB" strokeWidth="1"></path>
        </g>
      );
    }

    const primaryColor = cakeColors[0] || '#FFFFFF';
    return (
      <g>
        <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill={primaryColor} stroke="#D1D5DB" strokeWidth="1"></path>
        {/* Capas decorativas según el estilo */}
        {selectedDecoration === 'textura' && (
          <g opacity="0.4">
            <line x1="45" y1="130" x2="155" y2="130" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="160" x2="155" y2="160" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="190" x2="155" y2="190" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="220" x2="155" y2="220" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="250" x2="155" y2="250" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
          </g>
        )}
        {selectedDecoration === 'vintage' && (
          <g>
            <path d="M45 100 Q60 85 75 100 Q90 85 105 100 Q120 85 135 100 Q150 85 155 100" fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth="5" />
            <path d="M45 130 Q60 115 75 130 Q90 115 105 130 Q120 115 135 130 Q150 115 155 130" fill="none" stroke="rgba(255,255,255,0.4)" strokeWidth="3" />
            <path d="M45 200 Q60 185 75 200 Q90 185 105 200 Q120 185 135 200 Q150 185 155 200" fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth="5" />
          </g>
        )}
      </g>
    );
  };

  return (
    <div className="flex flex-col h-full bg-background-light relative animate-fadeIn">
      {/* DISEÑO DE CABECERA AMARILLA */}
      <div className="absolute top-0 left-0 w-full overflow-hidden leading-[0] z-0">
        <svg preserveAspectRatio="none" viewBox="0 0 1200 120" className="relative block w-[150%] h-[120px] shadow-sm">
          <path d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z" fill="#FDD835"></path>
        </svg>
      </div>

      <header className="pt-8 pb-2 px-6 flex items-center justify-between z-10 relative">
        <button onClick={onBack} className="w-10 h-10 rounded-full bg-white shadow-md flex items-center justify-center text-gray-900 transition-all active:scale-90 border border-gray-100">
          <span className="material-icons-round font-bold">arrow_back</span>
        </button>
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-black text-gray-800 uppercase tracking-widest bg-white/60 backdrop-blur-sm px-3 py-1 rounded-full mb-1">Paso 3 de 3</span>
          <h1 className="text-xl font-display font-bold text-primary drop-shadow-sm animate-pop uppercase">Decoración</h1>
        </div>
        <div className="w-10"></div>
      </header>

      <main className="flex-1 flex flex-col w-full z-10 overflow-y-auto no-scrollbar pb-44">
        {/* SECCIÓN DE PREVISUALIZACIÓN DEL PASTEL */}
        <div className="flex flex-col items-center justify-center min-h-[300px] relative py-4">
          <div className="w-48 h-64 relative filter drop-shadow-2xl scale-110">
            <svg className="w-full h-full" viewBox="0 0 200 300">
              <ellipse cx="100" cy="285" fill="#E5E7EB" rx="80" ry="12"></ellipse>
              {renderCakeBody()}
              <ellipse cx="100" cy="100" fill="#FFFFFF" rx="55" ry="15" stroke="#D1D5DB" strokeWidth="1"></ellipse>

              {/* VISTA PREVIA DEL TOPPER */}
              {topperType !== 'none' && (
                <g className="animate-pop">
                   <line x1="100" y1="50" x2="100" y2="90" stroke="#888" strokeWidth="2" />
                   <rect x="65" y="20" width="70" height="45" rx="8" fill="#E31C58" opacity="0.95" />
                   <circle cx="100" cy="42" r="14" fill="white" opacity="0.2" />
                   <text x="100" y="47" textAnchor="middle" fill="white" fontSize="9" fontWeight="900" style={{fontFamily: 'Fredoka One'}}>COKE</text>
                </g>
              )}

              {/* VISTA PREVIA DE LAS ESFERAS */}
              {hasSpheres && (
                <g className="animate-pop">
                  <circle cx="155" cy="130" r="14" fill="#E31C58" stroke="#fff" strokeWidth="2" />
                  <circle cx="168" cy="165" r="10" fill="#FFEB3B" stroke="#fff" strokeWidth="2" />
                  <circle cx="40" cy="230" r="16" fill="#E31C58" stroke="#fff" strokeWidth="2" />
                </g>
              )}
            </svg>
          </div>
        </div>

        <div className="px-6 w-full pt-4 space-y-8">
          {/* SELECCIÓN DE ESTILO */}
          <section>
            <h3 className="text-[11px] font-black text-gray-900 uppercase tracking-widest mb-4 flex items-center gap-2">
               <span className="material-icons-round text-primary text-base">brush</span>
               1. Estilo de Acabado
            </h3>
            <div className="grid grid-cols-4 gap-2">
              {(Object.keys(styles) as DecorationStyle[]).map(key => (
                <button 
                  key={key}
                  onClick={() => {
                    if (key !== 'degradado' && selectedDecoration === 'degradado') {
                        onUpdateDecoration({ selectedDecoration: key, cakeColors: [cakeColors[0]] });
                    } else {
                        onUpdateDecoration({ selectedDecoration: key });
                    }
                  }}
                  className="flex flex-col items-center gap-1.5 group"
                >
                  <div className={`w-14 h-14 rounded-2xl bg-white shadow-soft border-2 flex items-center justify-center transition-all ${selectedDecoration === key ? 'border-primary scale-110 shadow-md ring-4 ring-primary/10' : 'border-gray-50 opacity-60'}`}>
                    <span className={`material-icons-round text-xl ${selectedDecoration === key ? 'text-primary' : 'text-gray-400'}`}>
                      {styles[key].icon}
                    </span>
                  </div>
                  <span className={`text-[9px] font-black uppercase text-center leading-none ${selectedDecoration === key ? 'text-primary' : 'text-gray-500'}`}>{styles[key].label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* SELECCIÓN DE COLORES */}
          <section>
            <div className="flex items-center justify-between mb-4">
                <h3 className="text-[11px] font-black text-gray-900 uppercase tracking-widest flex items-center gap-2">
                  <span className="material-icons-round text-primary text-base">palette</span>
                  2. Selección de Colores
                </h3>
                {selectedDecoration === 'degradado' && (
                    <span className="text-[8px] text-white font-black uppercase tracking-widest bg-primary px-2 py-1 rounded-full animate-pulse">Hasta 3 colores</span>
                )}
            </div>

            <div className="grid grid-cols-6 gap-3 mb-6">
              {CAKE_COLORS.map((color) => {
                const isSelected = cakeColors.includes(color.hex);
                const orderIndex = cakeColors.indexOf(color.hex);
                return (
                  <button
                    key={color.name}
                    onClick={() => handleColorClick(color.hex)}
                    className={`aspect-square rounded-full border-4 shadow-sm transition-all transform active:scale-90 relative flex items-center justify-center ${isSelected ? 'border-primary scale-110 ring-4 ring-primary/5' : 'border-white hover:border-gray-100'}`}
                    style={{ backgroundColor: color.hex }}
                    title={color.name}
                  >
                    {isSelected && selectedDecoration === 'degradado' && (
                      <div className="absolute -top-2 -right-2 bg-primary text-white text-[9px] font-black w-5 h-5 rounded-full flex items-center justify-center shadow-md border border-white">
                          {orderIndex + 1}
                      </div>
                    )}
                    {isSelected && selectedDecoration !== 'degradado' && (
                      <span className={`material-icons-round ${color.name === 'Blanco' ? 'text-primary' : 'text-white'} text-lg drop-shadow-md`}>check</span>
                    )}
                  </button>
                );
              })}
            </div>

            {/* ADVERTENCIA DE COLORES FUERTES */}
            <div className="bg-amber-50 border-2 border-amber-200 p-5 rounded-[2rem] flex items-start gap-4 shadow-sm">
                <div className="bg-amber-500 text-white rounded-full p-1.5 shadow-md shrink-0">
                    <span className="material-icons-round text-lg">priority_high</span>
                </div>
                <p className="text-[10px] text-amber-900 font-bold leading-tight uppercase tracking-tight opacity-90">
                  <span className="block mb-1 text-[11px] font-black">Nota sobre colorantes</span>
                  Los colores más saturados (negro, rojo, azul rey) pueden cambiar levemente el sabor y tienen un incremento por el mayor uso de colorantes.
                </p>
            </div>
          </section>

          {/* SELECCIÓN DE TOPPER */}
          <section>
            <h3 className="text-[11px] font-black text-gray-900 uppercase tracking-widest mb-4 flex items-center gap-2">
               <span className="material-icons-round text-primary text-base">star_outline</span>
               3. Selección de Topper
            </h3>
            <div className="grid grid-cols-2 gap-3">
              {toppers.map(t => (
                <button 
                  key={t.id}
                  onClick={() => onUpdateDecoration({ topperType: t.id })}
                  className={`flex items-center gap-4 p-4 rounded-3xl border-2 transition-all ${topperType === t.id ? 'border-primary bg-primary/5 text-primary shadow-md' : 'border-gray-100 bg-white text-gray-500'}`}
                >
                  <span className="material-icons-round text-xl">{t.icon}</span>
                  <span className="text-[10px] font-black uppercase text-left leading-tight tracking-tight">{t.label}</span>
                </button>
              ))}
            </div>
          </section>

          {/* EXTRAS (ESFERAS) */}
          <section className="bg-white p-6 rounded-[2.5rem] shadow-soft border border-gray-100">
             <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className={`w-14 h-14 rounded-full flex items-center justify-center shadow-inner transition-colors ${hasSpheres ? 'bg-primary text-white ring-4 ring-primary/10' : 'bg-gray-100 text-gray-400'}`}>
                    <span className="material-icons-round text-2xl">lens</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-sm font-black text-gray-900 uppercase tracking-tighter">Esferas Decorativas</span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">+ $8.00 USD</span>
                  </div>
                </div>
                <button 
                  onClick={() => onUpdateDecoration({ hasSpheres: !hasSpheres })}
                  className={`w-16 h-9 rounded-full transition-all relative flex items-center px-1 shadow-inner ${hasSpheres ? 'bg-primary' : 'bg-gray-300'}`}
                >
                  <div className={`w-7 h-7 rounded-full bg-white shadow-md transform transition-transform duration-300 ${hasSpheres ? 'translate-x-7' : 'translate-x-0'}`}></div>
                </button>
             </div>
          </section>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white rounded-t-[2.5rem] shadow-[0_-15px_40px_rgba(0,0,0,0.12)] p-6 z-50 border-t border-gray-50">
        <div className="flex items-end justify-between mb-5 px-1">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Precio Estimado</span>
            <div className="text-4xl font-display font-bold text-gray-900 leading-none animate-pop">${totalPrice.toFixed(2)}</div>
          </div>
          <div className="text-right">
             <span className="text-[10px] font-black text-primary uppercase block tracking-[0.1em] mb-0.5">Diseño Exclusivo</span>
          </div>
        </div>
        <button 
          onClick={onNext}
          className="w-full bg-primary hover:bg-rose-600 text-white font-black text-base py-5 rounded-3xl shadow-xl shadow-primary/30 active:scale-[0.98] transition-all flex items-center justify-center gap-4 group"
        >
          <span className="uppercase tracking-[0.15em]">DEFINIR TEMÁTICA</span>
          <span className="material-icons-round text-2xl group-hover:translate-x-1 transition-transform">arrow_forward</span>
        </button>
      </footer>
    </div>
  );
};

