import React, { useRef, useEffect } from 'react';
import { CakeSize, HeightType } from '../types';
import { CAKE_SIZES } from '../constants';

interface SizeStepProps {
  selectedSize: CakeSize | null;
  onSelectSize: (size: CakeSize) => void;
  onNext: () => void;
}

const SizeStep: React.FC<SizeStepProps> = ({ selectedSize, onSelectSize, onNext }) => {
  // Diametros disponibles para mostrar
  const diameters = [14, 16, 18, 20, 22, 24];
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentDiameter = selectedSize?.diameter || 18;
  const currentHeight = selectedSize?.heightType || 'TALL';

  // Obtener datos del tamaño seleccionado actualmente
  const currentCakeData = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === currentHeight);

  /**
   * Cambia entre Pastel Alto o Pastel Bajo
   */
  const handleHeightToggle = (h: HeightType) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === h);
    if (newSize) onSelectSize(newSize);
  };

  /**
   * Selecciona un diámetro específico
   */
  const handleSelect = (d: number) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);
    if (newSize) onSelectSize(newSize);
  };

  // Efecto para centrar el pastel seleccionado al hacer scroll
  useEffect(() => {
    if (scrollRef.current) {
      const selectedEl = scrollRef.current.querySelector(`[data-diameter="${currentDiameter}"]`);
      if (selectedEl) {
        selectedEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }
  }, [currentDiameter]);

  return (
    <div className="flex flex-col h-full animate-fadeIn bg-background-light overflow-hidden">
      {/* CABECERA CON CONTRASTE MEJORADO */}
      <header className="pt-10 pb-4 px-6 flex justify-between items-center relative z-20 bg-white shadow-sm border-b border-gray-100">
        <div className="w-10"></div> {/* Espaciador */}
        <div className="text-center">
          <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mb-1 block">Paso 1 de 5</span>
          <h1 className="font-display text-2xl text-gray-900 uppercase tracking-tight">Elige el Tamaño</h1>
          <p className="text-[11px] font-bold text-gray-500 uppercase tracking-widest mt-1">Desliza para ver porciones</p>
        </div>
        <div className="w-10 flex justify-end">
            <span className="material-icons-round text-primary">straighten</span>
        </div>
      </header>

      {/* SELECTOR DE ALTURA (ALTO/BAJO) */}
      <div className="px-6 py-5 z-20 bg-background-light">
        <div className="flex p-1.5 bg-gray-200/60 rounded-2xl shadow-inner">
          <button 
            onClick={() => handleHeightToggle('SHORT')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] font-black transition-all duration-300 ${currentHeight === 'SHORT' ? 'bg-white text-primary shadow-md scale-100' : 'text-gray-600 scale-95 opacity-80'}`}
          >
            <span className="material-icons-round text-base">reorder</span>
            BAJO (10cm)
          </button>
          <button 
            onClick={() => handleHeightToggle('TALL')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] font-black transition-all duration-300 ${currentHeight === 'TALL' ? 'bg-white text-primary shadow-md scale-100' : 'text-gray-600 scale-95 opacity-80'}`}
          >
            <span className="material-icons-round text-base">height</span>
            ALTO (17cm)
          </button>
        </div>
      </div>

      {/* ÁREA DE VISUALIZACIÓN DE LOS PASTELES */}
      <main className="flex-1 flex flex-col relative">
        {/* Regla de fondo para referencia visual */}
        <div className="absolute inset-0 flex flex-col justify-end pb-32 pointer-events-none opacity-20">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="w-full border-t border-gray-500 h-10 flex items-start px-4">
              <span className="text-[9px] font-black text-gray-600">{i * 5}cm</span>
            </div>
          ))}
        </div>

        <div 
          ref={scrollRef}
          className="flex-1 flex items-end gap-10 overflow-x-auto no-scrollbar px-16 pb-32 pt-10 snap-x snap-mandatory"
        >
          {diameters.map((d) => {
            const isSelected = currentDiameter === d;
            const cakeForThisDiameter = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);

            // Lógica de escalado visual del SVG
            const width = 110 + (d - 14) * 14;
            const height = currentHeight === 'TALL' ? 160 : 90;

            return (
              <div 
                key={d} 
                data-diameter={d}
                onClick={() => handleSelect(d)}
                className={`snap-center flex flex-col items-center transition-all duration-500 cursor-pointer ${isSelected ? 'scale-110' : 'scale-90 opacity-30 hover:opacity-60'}`}
              >
                <div className="relative" style={{ width: `${width}px` }}>
                  <svg 
                    viewBox={`0 0 ${width} ${height + 40}`} 
                    width={width} 
                    height={height + 40}
                    className={`drop-shadow-[0_20px_30px_rgba(0,0,0,0.15)] transition-all duration-500 ${isSelected ? 'brightness-105' : 'brightness-90'}`}
                  >
                    <ellipse cx={width/2} cy={height + 20} rx={width/2} ry="10" fill="rgba(0,0,0,0.1)" />
                    <path 
                      d={`M0 20 L0 ${height} Q${width/2} ${height + 25} ${width} ${height} L${width} 20`} 
                      fill={currentHeight === 'TALL' ? '#E31C58' : '#FDD835'} 
                      className="transition-colors duration-500"
                    />
                    <ellipse cx={width/2} cy="20" rx={width/2} ry="15" fill={currentHeight === 'TALL' ? '#FFF' : '#FFF'} stroke="rgba(0,0,0,0.05)" strokeWidth="1" />
                    <text 
                      x="50%" 
                      y={height/2 + 20} 
                      textAnchor="middle" 
                      className={`font-display transition-colors duration-500 text-2xl ${isSelected ? (currentHeight === 'TALL' ? 'fill-white' : 'fill-gray-800') : 'fill-transparent'}`}
                    >
                      {d}
                    </text>
                  </svg>

                  {isSelected && (
                    <div className="absolute -top-12 left-1/2 -translate-x-1/2 whitespace-nowrap bg-gray-900 text-white text-[10px] font-black px-4 py-1.5 rounded-full shadow-xl animate-bounce uppercase tracking-widest border-2 border-white">
                      ¡Seleccionado!
                    </div>
                  )}
                </div>

                {/* Etiquetas de info bajo el pastel */}
                <div className={`mt-6 flex flex-col items-center gap-1 transition-all duration-300 ${isSelected ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                  <div className={`font-display text-2xl text-gray-900`}>
                    {d}cm
                  </div>
                  <div className={`text-[11px] font-black px-3 py-1 rounded-full whitespace-nowrap bg-primary text-white shadow-md uppercase tracking-wider`}>
                    {cakeForThisDiameter?.portions}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </main>

      {/* PIE DE PÁGINA CON RESUMEN Y BOTÓN */}
      <footer className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white rounded-t-[3rem] shadow-[0_-20px_50px_rgba(0,0,0,0.15)] p-8 z-50 border-t border-gray-50">
        <div className="flex items-center justify-between mb-8 px-2">
          <div className="flex flex-col">
            <div className="flex items-center gap-2 mb-1">
               <span className="material-icons-round text-primary text-lg">groups</span>
               <span className="text-[11px] text-gray-500 font-black uppercase tracking-widest">Capacidad estimada</span>
            </div>
            <div className="flex items-baseline gap-3">
              <span className="text-4xl font-display text-gray-900">{currentDiameter}cm</span>
              <span className="text-xs font-black text-primary uppercase bg-primary/10 px-2 py-0.5 rounded-md">{currentHeight === 'TALL' ? 'Alto' : 'Bajo'}</span>
            </div>
          </div>
          <div className="text-right">
            <span className="text-4xl font-display text-primary tracking-tighter animate-pop">${(selectedSize?.basePrice || 0).toFixed(2)}</span>
            <span className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Precio Base</span>
          </div>
        </div>

        <button 
          onClick={onNext}
          className="w-full bg-primary hover:bg-rose-600 text-white font-black py-5 rounded-[2rem] shadow-2xl shadow-primary/30 transform transition active:scale-[0.98] flex items-center justify-center gap-4 overflow-hidden group"
        >
          <span className="text-base uppercase tracking-[0.2em] group-hover:translate-x-1 transition-transform">Siguiente: Sabores</span>
          <span className="material-icons-round text-2xl group-hover:translate-x-2 transition-transform">arrow_forward</span>
        </button>
      </footer>
    </div>
  );
};

export default SizeStep;

import React from 'react';
import { Flavor, Filling } from '../types';
import { FLAVORS, FILLINGS } from '../constants';

interface FlavorStepProps {
  selectedFlavor: Flavor | null;
  selectedFilling: Filling | null;
  onSelectFlavor: (flavor: Flavor) => void;
  onSelectFilling: (filling: Filling) => void;
  onNext: () => void;
  onBack: () => void;
  totalPrice: number;
  customFlavor: string;
  onCustomFlavorChange: (val: string) => void;
  customFilling: string;
  onCustomFillingChange: (val: string) => void;
}

const FlavorStep: React.FC<FlavorStepProps> = ({ 
  selectedFlavor, 
  selectedFilling, 
  onSelectFlavor, 
  onSelectFilling, 
  onNext, 
  onBack,
  totalPrice,
  customFlavor,
  onCustomFlavorChange,
  customFilling,
  onCustomFillingChange
}) => {
  // Comprobación si se seleccionó "Otros" en relleno y si el usuario escribió algo
  const isFillingOthersSelected = selectedFilling?.id === 'others';
  const canContinue = !isFillingOthersSelected || customFilling.trim().length > 0;

  return (
    <div className="flex flex-col h-full bg-background-light relative animate-fadeIn">
      {/* Fondo decorativo amarillo */}
      <div className="absolute top-0 left-0 w-full h-64 bg-secondary rounded-b-[4rem] -z-0 transform scale-x-110 origin-top shadow-inner"></div>

      <header className="relative z-10 pt-12 px-6 pb-6 text-center">
        <button onClick={onBack} className="absolute top-10 left-6 bg-white text-gray-900 p-2 rounded-full shadow-md transition-transform active:scale-90 border border-gray-100">
