          <p className="text-gray-500 font-bold text-sm uppercase tracking-widest mt-2">Personaliza la dimensión de tu celebración</p>
        </div>

        {/* SELECTOR DE ALTURA: DISEÑO TIPO APP PREMIUM */}
        <div className="bg-gray-100 p-2 rounded-[2.5rem] flex gap-2 border-2 border-white shadow-inner min-w-[300px]">
          <button 
            onClick={() => handleHeightToggle('SHORT')}
            className={`flex-1 flex items-center justify-center gap-3 py-4 rounded-[2rem] text-[11px] font-black transition-all duration-500 ${currentHeight === 'SHORT' ? 'bg-white text-primary shadow-xl scale-100' : 'text-gray-400 grayscale'}`}
          >
            <span className="material-icons-round">reorder</span>
            BAJO (10cm)
          </button>
          <button 
            onClick={() => handleHeightToggle('TALL')}
            className={`flex-1 flex items-center justify-center gap-3 py-4 rounded-[2rem] text-[11px] font-black transition-all duration-500 ${currentHeight === 'TALL' ? 'bg-white text-primary shadow-xl scale-100' : 'text-gray-400 grayscale'}`}
          >
            <span className="material-icons-round">height</span>
            ALTO (17cm)
