      <main className="flex-1 flex flex-col relative overflow-hidden bg-gradient-to-b from-white to-background-light">
        {/* REGLA DE FONDO PARA REFERENCIA DE CM */}
        <div className="absolute left-10 top-0 bottom-40 w-px bg-gray-200 hidden md:block">
           {[...Array(7)].map((_, i) => (
             <div key={i} className="absolute w-6 h-px bg-gray-300 left-0" style={{bottom: `${(i/6)*100}%`}}>
                <span className="ml-10 text-[10px] font-black text-gray-400 uppercase tracking-widest">{i*5}cm</span>
             </div>
           ))}
        </div>

        {/* CONTENEDOR DE DESLIZAMIENTO */}
        <div 
          ref={scrollRef}
          className="flex-1 flex items-end gap-24 overflow-x-auto no-scrollbar px-[20vw] pb-40 pt-20 snap-x snap-mandatory"
        >
          {diameters.map((d) => {
            const isSelected = currentDiameter === d;
            const cakeForThisDiameter = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);

            // ESCALADO VISUAL DINÁMICO (Más grande en pantalla completa)
            const baseScale = 1.4; // Aumentamos el tamaño base
            const width = (130 + (d - 14) * 22) * baseScale;
            const height = (currentHeight === 'TALL' ? 180 : 100) * baseScale;

            return (
              <div 
                key={d} 
                data-diameter={d}
                onClick={() => handleSelect(d)}
                className={`snap-center flex flex-col items-center transition-all duration-700 cursor-pointer ${isSelected ? 'scale-110' : 'scale-90 opacity-20 grayscale'}`}
              >
                <div className="relative" style={{ width: `${width}px` }}>

                  {/* INDICADOR DE PORCIONES GIGANTE (SOLO AL SELECCIONAR) */}
                  {isSelected && (
