                    <ellipse cx={width/2} cy={height + 30} rx={width/2} ry="15" fill="rgba(0,0,0,0.12)" />
                    <path 
                      d={`M0 30 L0 ${height + 10} Q${width/2} ${height + 40} ${width} ${height + 10} L${width} 30`} 
                      fill={currentHeight === 'TALL' ? '#E31C58' : '#FDD835'} 
