                    />
                    <ellipse cx={width/2} cy="30" rx={width/2} ry="22" fill="#FFF" stroke="rgba(0,0,0,0.06)" strokeWidth="1" />

                    {/* TEXTO DEL DIÁMETRO DENTRO DEL PASTEL */}
                    <text 
                      x="50%" 
