                      className={`font-display text-4xl md:text-5xl transition-all ${isSelected ? (currentHeight === 'TALL' ? 'fill-white' : 'fill-gray-900') : 'fill-transparent'}`}
                    >
                      {d}
                    </text>
                  </svg>
                </div>

                {/* ETIQUETA INFERIOR */}
                <div className={`mt-10 flex flex-col items-center gap-2 transition-all duration-500 ${isSelected ? 'translate-y-0 opacity-100' : 'translate-y-8 opacity-0'}`}>
                  <div className="font-display text-6xl text-gray-900 tracking-tighter">{d}cm</div>
