                </div>
              </div>
            );
          })}
        </div>
      </main>

      {/* FOOTER DE PANTALLA COMPLETA CON RESUMEN DINÁMICO */}
      <footer className="bg-white p-10 md:p-14 z-50 shadow-[0_-30px_60px_rgba(0,0,0,0.08)] rounded-t-[5rem] border-t-2 border-gray-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-10">

          <div className="flex flex-wrap justify-center md:justify-start items-center gap-12">
