import React, { useRef, useEffect } from 'react';
import { CakeSize, HeightType } from '../types';
import { CAKE_SIZES } from '../constants';

interface SizeStepProps {
  selectedSize: CakeSize | null;
  onSelectSize: (size: CakeSize) => void;
  onNext: () => void;
}

const SizeStep: React.FC<SizeStepProps> = ({ selectedSize, onSelectSize, onNext }) => {
  const diameters = [14, 16, 18, 20, 22, 24];
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentDiameter = selectedSize?.diameter || 18;
  const currentHeight = selectedSize?.heightType || 'TALL';
  const currentCakeData = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === currentHeight);

  const handleHeightToggle = (h: HeightType) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === currentDiameter && s.heightType === h);
    if (newSize) onSelectSize(newSize);
  };

  const handleSelect = (d: number) => {
    const newSize = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);
    if (newSize) onSelectSize(newSize);
  };

  useEffect(() => {
    if (scrollRef.current) {
      const selectedEl = scrollRef.current.querySelector(`[data-diameter="${currentDiameter}"]`);
      if (selectedEl) {
        selectedEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }
  }, [currentDiameter]);

  return (
    <div className="flex flex-col h-full bg-background-light animate-fadeIn overflow-hidden relative">
      {/* CABECERA: Optimizada para no robar espacio en móvil */}
      <header className="pt-4 pb-2 md:pt-8 md:pb-4 px-4 md:px-8 flex flex-col md:flex-row justify-between items-center z-20 bg-white/95 backdrop-blur-md border-b border-gray-100 shrink-0">
        <div className="text-center md:text-left mb-3 md:mb-0">
          <span className="bg-primary/10 text-primary text-[9px] md:text-[10px] font-black px-3 py-0.5 md:py-1 rounded-full uppercase tracking-widest mb-1 inline-block">Paso 1: Dimensión</span>
          <h1 className="font-display text-2xl md:text-4xl text-gray-900 leading-tight">ELIGE EL TAMAÑO</h1>
        </div>

        {/* SELECTOR DE ALTURA: Más compacto en móvil */}
        <div className="bg-gray-100 p-1 rounded-xl md:rounded-2xl flex gap-1 border border-gray-200 min-w-[240px] md:min-w-[260px]">
          <button 
            onClick={() => handleHeightToggle('SHORT')}
            className={`flex-1 flex items-center justify-center gap-1 md:gap-2 py-2 md:py-2.5 rounded-lg md:rounded-xl text-[9px] md:text-[10px] font-black transition-all duration-300 ${currentHeight === 'SHORT' ? 'bg-white text-primary shadow-sm' : 'text-gray-400'}`}
          >
            <span className="material-icons-round text-sm md:text-base">reorder</span>
            BAJO (10cm)
          </button>
          <button 
            onClick={() => handleHeightToggle('TALL')}
            className={`flex-1 flex items-center justify-center gap-1 md:gap-2 py-2 md:py-2.5 rounded-lg md:rounded-xl text-[9px] md:text-[10px] font-black transition-all duration-300 ${currentHeight === 'TALL' ? 'bg-white text-primary shadow-sm' : 'text-gray-400'}`}
          >
            <span className="material-icons-round text-sm md:text-base">height</span>
            ALTO (17cm)
          </button>
        </div>
      </header>

      {/* ÁREA CENTRAL DE VISUALIZACIÓN: flex-1 asegura que tome el resto del espacio */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-gradient-to-b from-white to-background-light min-h-0">
        {/* REFERENCIA VISUAL: LATA DE REFRESCO - Ajustada para móvil */}
        <div className="absolute inset-x-0 bottom-36 md:bottom-44 flex justify-center pointer-events-none opacity-20 transition-opacity z-0">
            <div className="flex flex-col items-center">
                <div className="w-10 h-16 md:w-14 md:h-24 bg-gray-400 rounded-lg relative border-2 border-gray-300 shadow-sm">
                    <div className="absolute top-1 left-2 right-2 h-1 bg-gray-300 rounded-full opacity-50"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                       <span className="text-[6px] md:text-[7px] font-black text-gray-100 uppercase rotate-90">12 cm</span>
                    </div>
                </div>
                <span className="text-[8px] md:text-[9px] font-black mt-1 md:mt-2 text-gray-400 uppercase tracking-widest">Soda Ref.</span>
            </div>
        </div>

        {/* CONTENEDOR DE PASTELES: Ajustado padding y gaps para móvil */}
        <div 
          ref={scrollRef}
          className="flex-1 flex items-end gap-8 md:gap-20 overflow-x-auto no-scrollbar px-[15vw] md:px-[30vw] pb-24 md:pb-36 pt-4 md:pt-10 snap-x snap-mandatory relative z-10"
        >
          {diameters.map((d) => {
            const isSelected = currentDiameter === d;
            const cakeForThisDiameter = CAKE_SIZES.find(s => s.diameter === d && s.heightType === currentHeight);

            // ESCALADO VISUAL DINÁMICO (Diferente para móvil y escritorio)
            // En móvil d=14 -> ~110px, d=24 -> ~190px (ajustando scaleFactor)
            const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;
            const scaleFactor = isMobile ? 0.8 : 1.35;

            const cakeWidth = (d * 10) * scaleFactor;
            const cakeHeight = (currentHeight === 'TALL' ? 150 : 80) * scaleFactor;

            return (
              <div 
                key={d} 
                data-diameter={d}
                onClick={() => handleSelect(d)}
                className={`snap-center flex flex-col items-center transition-all duration-500 cursor-pointer shrink-0 ${isSelected ? 'scale-110' : 'scale-90 opacity-50 grayscale-[40%]'}`}
              >
                <div className="relative flex flex-col items-center" style={{ width: `${cakeWidth}px` }}>

                  {/* BADGE DE PORCIONES */}
                  {isSelected && (
                    <div className="absolute -top-16 md:-top-24 left-1/2 -translate-x-1/2 z-30 animate-pop">
                      <div className="bg-primary text-white text-[9px] md:text-[11px] font-black px-4 md:px-6 py-1.5 md:py-2.5 rounded-full shadow-xl-primary border-2 border-white whitespace-nowrap uppercase tracking-widest flex flex-col items-center">
                        <span className="text-[7px] md:text-[8px] opacity-80 mb-0.5">Capacidad</span>
                        {cakeForThisDiameter?.portions}
                      </div>
                      <div className="w-3 h-3 md:w-4 md:h-4 bg-white rotate-45 mx-auto -mt-1.5 md:-mt-2"></div>
                    </div>
                  )}

                  {/* VECTOR DEL PASTEL */}
                  <svg 
                    viewBox={`0 0 ${cakeWidth} ${cakeHeight + 40}`} 
                    width={cakeWidth} 
                    height={cakeHeight + 40}
                    className={`transition-all duration-500 ${isSelected ? 'drop-shadow-[0_15px_15px_rgba(227,28,88,0.25)]' : 'drop-shadow-lg'}`}
                  >
                    <ellipse cx={cakeWidth/2} cy={cakeHeight + 20} rx={cakeWidth/2} ry="10" fill="rgba(0,0,0,0.08)" />
                    <path 
                      d={`M0 20 L0 ${cakeHeight} Q${cakeWidth/2} ${cakeHeight + 20} ${cakeWidth} ${cakeHeight} L${cakeWidth} 20`} 
                      fill={currentHeight === 'TALL' ? (isSelected ? '#E31C58' : '#F472B6') : (isSelected ? '#FDD835' : '#FEF08A')} 
                      className="transition-colors duration-500"
                    />
                    <ellipse cx={cakeWidth/2} cy="20" rx={cakeWidth/2} ry="15" fill={isSelected ? "#FFF" : "#FAFAFA"} stroke="rgba(0,0,0,0.1)" strokeWidth="1" />
                    <text 
                      x="50%" 
                      y={cakeHeight/2 + 25} 
                      textAnchor="middle" 
                      className={`font-display text-2xl md:text-4xl transition-all duration-500 pointer-events-none ${isSelected ? (currentHeight === 'TALL' ? 'fill-white' : 'fill-gray-800') : 'fill-gray-400 opacity-60'}`}
                    >
                      {d}
                    </text>
                  </svg>
                </div>

                {/* ETIQUETA INFERIOR */}
                <div className={`mt-4 md:mt-6 flex flex-col items-center gap-0.5 md:gap-1 transition-all duration-500 ${isSelected ? 'opacity-100 translate-y-0 scale-100' : 'opacity-60 translate-y-2 scale-90'}`}>
                  <div className={`font-display text-3xl md:text-5xl tracking-tighter ${isSelected ? 'text-gray-900' : 'text-gray-400'}`}>{d}cm</div>
                  <div className={`text-[8px] md:text-[10px] font-black uppercase tracking-[0.2em] md:tracking-[0.3em] px-3 md:px-4 py-0.5 rounded-full ${isSelected ? 'bg-primary/5 text-primary border border-primary/10' : 'bg-gray-100 text-gray-400 border border-transparent'}`}>
                    Diámetro
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </main>

      {/* FOOTER REDUCIDO Y COMPACTO */}
      <footer className="bg-white p-4 md:p-8 z-50 shadow-[0_-15px_30px_rgba(0,0,0,0.05)] rounded-t-[2.5rem] md:rounded-t-[3rem] border-t border-gray-100 shrink-0">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4 md:gap-6">

          <div className="flex flex-wrap justify-center md:justify-start items-center gap-6 md:gap-8">
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[8px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mb-0.5">Seleccionado</span>
              <div className="flex items-baseline justify-center md:justify-start gap-2">
                <span className="text-2xl md:text-3xl font-display text-gray-900">{currentDiameter}cm</span>
                <span className="text-[9px] md:text-[10px] font-black text-primary uppercase bg-primary/5 px-2.5 md:px-3 py-0.5 rounded-lg border border-primary/10">
                  {currentCakeData?.portions}
                </span>
              </div>
            </div>

            <div className="w-px h-8 bg-gray-100 hidden md:block"></div>

            <div className="flex flex-col text-center md:text-left">
              <span className="text-[8px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mb-0.5">Precio Sugerido</span>
              <span className="text-2xl md:text-3xl font-display text-primary tracking-tighter">${(selectedSize?.basePrice || 0).toFixed(2)}</span>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="w-full md:w-auto bg-primary hover:bg-rose-600 text-white font-black py-3.5 md:py-4 px-10 md:px-12 rounded-[1.5rem] md:rounded-[2rem] shadow-xl-primary transition-all active:scale-[0.98] flex items-center justify-center gap-3 md:gap-4 group text-xs md:text-sm"
          >
            <span className="uppercase tracking-[0.15em] md:tracking-[0.2em]">Siguiente: Sabores</span>
            <span className="material-icons-round text-lg md:text-xl group-hover:translate-x-2 transition-transform">arrow_forward</span>
          </button>
        </div>
      </footer>
    </div>
  );
};

export default SizeStep;

export type Step = 'SIZE' | 'FLAVOR' | 'DECORATION' | 'PERSONALIZATION' | 'SUMMARY' | 'PAYMENT' | 'ADMIN_LOGIN' | 'ADMIN_PANEL';

export type HeightType = 'TALL' | 'SHORT';
export type DeliveryMethod = 'DELIVERY' | 'PICKUP';
export type CoverageType = 'chantilly' | 'chocolate' | 'arequipe';

export interface CakeColor {
  name: string;
  hex: string;
  isSaturated?: boolean;
}

export interface CakeSize {
  id: string;
  diameter: number;
  heightType: HeightType;
  portions: string;
  basePrice: number;
}

export interface Flavor {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
}

export interface Filling {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
}

export type DecorationStyle = 'liso' | 'vintage' | 'textura' | 'degradado';
export type TopperType = 'none' | 'generic' | 'personalized' | 'plus_pieces';

export interface DecorationInfo {
  id: DecorationStyle;
  label: string;
  priceModifier: number;
}

export interface AppConfig {
  sizes: CakeSize[];
  flavors: Flavor[];
  fillings: Filling[];
  colors: CakeColor[];
  decorations: Record<string, DecorationInfo>;
}

export interface Order {
  id: string;
  date: string;
  customerName: string;
  details: string;
  total: number;
  status: 'PENDING' | 'COMPLETED';
}

export interface AppState {
  step: Step;
  selectedSize: CakeSize | null;
  selectedFlavor: Flavor | null;
  selectedFilling: Filling | null;
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  theme: string;
  birthdayName: string;
  birthdayAge: string;
  specialRequirements: string;
  referenceImage: string | null;
  paymentReference: string;
  amountBs: string;
  paymentProof: string | null;
  deliveryMethod: DeliveryMethod;
  deliveryDate: string;
  deliveryTime: string;
  coverageType: CoverageType;
  totalPrice: number;
  customFlavor: string;
  customFilling: string;
}

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, CakeSize, Flavor, Filling, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  // Configuración dinámica cargada de LocalStorage o constantes por defecto
  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('cake_app_config');
    return saved ? JSON.parse(saved) : {
      sizes: CAKE_SIZES,
      flavors: FLAVORS,
      fillings: FILLINGS,
      colors: CAKE_COLORS,
      decorations: DECORATIONS
    };
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('cake_app_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[0],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFlavor: '',
    customFilling: '',
  });

  // Guardar configuración cuando cambie
  useEffect(() => {
    localStorage.setItem('cake_app_config', JSON.stringify(config));
  }, [config]);

  // Guardar pedidos cuando cambien
  useEffect(() => {
    localStorage.setItem('cake_app_orders', JSON.stringify(orders));
  }, [orders]);

  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    const size = partial.selectedSize || state.selectedSize;
    const flavor = partial.selectedFlavor || state.selectedFlavor;
    const filling = partial.selectedFilling || state.selectedFilling;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;
    const currentColors = partial.cakeColors || state.cakeColors;

    const base = size?.basePrice || 0;
    const fMod = flavor?.priceModifier || 0;
    const fillMod = filling?.priceModifier || 0;
    const decorMod = config.decorations[decorId]?.priceModifier || 0;
    const topperMod = TOPPER_PRICES[topper] || 0;
    const spheresMod = spheres ? SPHERES_PRICE : 0;

    let colorSurcharge = 0;
    const hasSaturated = currentColors.some(hex => 
        config.colors.find(c => c.hex === hex)?.isSaturated
    );
    if (hasSaturated) colorSurcharge = SATURATED_COLOR_SURCHARGE;
    const coverageMod = coverage === 'chocolate' ? 5 : coverage === 'arequipe' ? 4 : 0;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod + colorSurcharge;
  }, [state, config]);

  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  const handleFinalizeOrder = () => {
    const deposit = state.totalPrice / 2;
    const colorNames = state.cakeColors.map(hex => 
        config.colors.find(c => c.hex === hex)?.name || 'Especial'
    ).join(', ');

    const orderText = `Pastel ${state.selectedSize?.diameter}cm, ${state.selectedFlavor?.name}, Relleno: ${state.selectedFilling?.name}, Temática: ${state.theme}`;

    // Guardar pedido localmente para el Admin
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      date: new Date().toLocaleString(),
      customerName: state.birthdayName || 'Cliente Web',
      details: orderText,
      total: state.totalPrice,
      status: 'PENDING'
    };
    setOrders(prev => [newOrder, ...prev]);

    const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂 (Ref: ${newOrder.id})

📍 *TAMAÑO Y COBERTURA*
- Diámetro: ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType === 'TALL' ? 'Alto' : 'Bajo'})
- Cobertura: ${state.coverageType.toUpperCase()}
- Capacidad: ${state.selectedSize?.portions}

🍰 *SABORES*
- Bizcocho: ${state.selectedFlavor?.name}
- Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}
- Estilo: ${config.decorations[state.selectedDecoration].label}
- Colores: ${colorNames}

✨ *DECORACIÓN EXTRA*
- Topper: ${state.topperType}
- Esferas: ${state.hasSpheres ? 'Sí' : 'No'}

🎉 *DATOS DEL EVENTO*
- Temática: ${state.theme}
- Para: ${state.birthdayName} (${state.birthdayAge} años)
- Método: ${state.deliveryMethod}
- Fecha: ${state.deliveryDate} @ ${state.deliveryTime}

💰 *PAGO*
- Total: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Referencia: ${state.paymentReference}
- Monto en Bs: ${state.amountBs}`;

    const whatsappNumber = "584241546473";
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const goToAdminLogin = () => setState(prev => ({ ...prev, step: 'ADMIN_LOGIN' }));
  const exitAdmin = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  return (
    <div className="w-full h-full flex flex-col font-quicksand bg-background-light overflow-hidden">
        {state.step === 'SIZE' && (
          <SizeStep 
            selectedSize={state.selectedSize} 
            onSelectSize={(s) => setState(prev => ({ ...prev, selectedSize: s, totalPrice: calculateTotal({ selectedSize: s }) }))} 
            onNext={nextStep} 
            onAdminClick={goToAdminLogin}
            config={config}
          />
        )}
        {state.step === 'FLAVOR' && (
          <FlavorStep 
            {...state} 
            onSelectFlavor={(f) => setState(prev => ({ ...prev, selectedFlavor: f, totalPrice: calculateTotal({ selectedFlavor: f }) }))} 
            onSelectFilling={(fill) => setState(prev => ({ ...prev, selectedFilling: fill, totalPrice: calculateTotal({ selectedFilling: fill }) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            onCustomFlavorChange={(v) => setState(s => ({...s, customFlavor: v}))} 
            onCustomFillingChange={(v) => setState(s => ({...s, customFilling: v}))} 
            config={config}
          />
        )}
        {state.step === 'DECORATION' && (
          <DecorationStep 
            {...state} 
            onUpdateDecoration={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            config={config}
          />
        )}
        {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} onNext={nextStep} onBack={prevStep} />}
        {state.step === 'SUMMARY' && <SummaryStep appState={state} onBack={prevStep} onConfirm={nextStep} config={config} />}
        {state.step === 'PAYMENT' && <PaymentStep {...state} onUpdatePayment={(d) => setState(s => ({...s, ...d}))} onBack={prevStep} onComplete={handleFinalizeOrder} />}

        {state.step === 'ADMIN_LOGIN' && (
          <AdminLogin 
            onLoginSuccess={() => setState(prev => ({ ...prev, step: 'ADMIN_PANEL' }))} 
            onCancel={exitAdmin} 
          />
        )}

        {state.step === 'ADMIN_PANEL' && (
          <AdminPanel 
            config={config} 
            onUpdateConfig={setConfig} 
            orders={orders}
            onClearOrders={() => setOrders([])}
            onExit={exitAdmin} 
          />
        )}
    </div>
  );
};

export default App;

