        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-primary/10 rounded-3xl flex items-center justify-center mx-auto mb-6">
            <span className="material-icons-round text-primary text-4xl">lock</span>
          </div>
          <h2 className="text-2xl font-display text-gray-900 uppercase">Panel de Control</h2>
          <p className="text-gray-400 text-xs font-bold uppercase tracking-widest mt-2">Acceso Reservado</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div>
            <label className="block text-[10px] font-black text-gray-500 uppercase mb-2 ml-1 tracking-widest">ID Usuario</label>
            <input 
              type="text" 
              className="w-full bg-gray-50 border-none rounded-2xl p-4 text-sm font-bold text-gray-800 focus:ring-4 focus:ring-primary/10 transition-all outline-none"
              value={user}
              onChange={(e) => setUser(e.target.value)}
              placeholder="Ingrese ID"
            />
          </div>
          <div>
            <label className="block text-[10px] font-black text-gray-500 uppercase mb-2 ml-1 tracking-widest">Contraseña</label>
            <input 
              type="password" 
              className="w-full bg-gray-50 border-none rounded-2xl p-4 text-sm font-bold text-gray-800 focus:ring-4 focus:ring-primary/10 transition-all outline-none"
              value={pass}
              onChange={(e) => setPass(e.target.value)}
              placeholder="••••••••"
            />
          </div>

          <div className="pt-4 flex flex-col gap-3">
            <button 
              type="submit"
              className="w-full bg-primary text-white font-black py-5 rounded-2xl shadow-xl shadow-primary/20 hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-widest text-sm"
            >
              Iniciar Sesión
            </button>
            <button 
              type="button"
              onClick={onCancel}
              className="w-full bg-gray-100 text-gray-500 font-black py-4 rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs"
            >
              Volver al Sitio
            </button>
          </div>
        </form>
      </div>
      <style>{`
        .shake { animation: shake 0.5s linear; }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-10px); }
          75% { transform: translateX(10px); }
        }
      `}</style>
    </div>
  );
};

export default AdminLogin;

import React, { useState } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, CakeColor } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'COLORS'>('ORDERS');

  // Funciones de gestión de Tamaños
  const updateSize = (id: string, field: keyof CakeSize, value: any) => {
    const newSizes = config.sizes.map(s => s.id === id ? { ...s, [field]: value } : s);
    onUpdateConfig({ ...config, sizes: newSizes });
  };

  const addSize = () => {
    const newSize: CakeSize = {
      id: `new_${Date.now()}`,
      diameter: 14,
      heightType: 'SHORT',
      portions: 'Nuevas porciones',
      basePrice: 10
    };
    onUpdateConfig({ ...config, sizes: [...config.sizes, newSize] });
  };

  // Funciones de gestión de Colores
  const updateColor = (index: number, field: keyof CakeColor, value: any) => {
    const newColors = [...config.colors];
    newColors[index] = { ...newColors[index], [field]: value };
    onUpdateConfig({ ...config, colors: newColors });
  };

  const addColor = () => {
    const newColor: CakeColor = { name: 'Nuevo Color', hex: '#000000' };
    onUpdateConfig({ ...config, colors: [...config.colors, newColor] });
  };

  const removeColor = (index: number) => {
    onUpdateConfig({ ...config, colors: config.colors.filter((_, i) => i !== index) });
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 overflow-hidden font-quicksand">
      {/* Sidebar / Header */}
      <header className="bg-white border-b border-gray-200 px-8 py-6 flex items-center justify-between z-10 shrink-0">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-primary rounded-2xl flex items-center justify-center text-white shadow-lg">
            <span className="material-icons-round">settings</span>
          </div>
          <div>
            <h1 className="text-xl font-display text-gray-900 uppercase leading-none">Configuración de Tienda</h1>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Panel Administrativo v2.0</p>
          </div>
        </div>
        <button 
          onClick={onExit}
          className="bg-gray-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-primary transition-all flex items-center gap-2"
        >
          <span className="material-icons-round text-sm">logout</span>
          Salir del Panel
        </button>
      </header>

      {/* Tabs */}
      <nav className="bg-white border-b border-gray-200 px-8 flex gap-8 shrink-0">
        {[
          { id: 'ORDERS', label: 'Pedidos', icon: 'shopping_basket' },
          { id: 'SIZES', label: 'Tamaños', icon: 'straighten' },
          { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant' },
          { id: 'COLORS', label: 'Colores', icon: 'palette' },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`py-6 flex items-center gap-2 border-b-4 transition-all ${activeTab === tab.id ? 'border-primary text-primary font-black' : 'border-transparent text-gray-400 font-bold hover:text-gray-600'}`}
          >
            <span className="material-icons-round text-lg">{tab.icon}</span>
            <span className="text-[10px] uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>

      {/* Content Area */}
      <main className="flex-1 p-8 overflow-y-auto no-scrollbar">
        <div className="max-w-6xl mx-auto">

          {/* TAB: PEDIDOS */}
          {activeTab === 'ORDERS' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-sm font-black text-gray-900 uppercase tracking-widest">Historial de Pedidos Web</h2>
                <button 
                  onClick={onClearOrders}
                  className="text-[10px] font-black text-red-500 uppercase tracking-widest hover:bg-red-50 px-4 py-2 rounded-lg"
                >
                  Limpiar Todo
                </button>
              </div>

              {orders.length === 0 ? (
                <div className="bg-white rounded-3xl p-20 text-center border-2 border-dashed border-gray-200">
                  <span className="material-icons-round text-gray-300 text-6xl mb-4">inbox</span>
                  <p className="text-gray-400 font-bold">No hay pedidos registrados aún.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-4">
                  {orders.map(order => (
                    <div key={order.id} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-center justify-between">
                      <div className="flex items-center gap-6">
                        <div className="w-14 h-14 bg-green-100 text-green-600 rounded-2xl flex flex-col items-center justify-center font-black">
                          <span className="text-[10px] uppercase">ID</span>
                          <span className="text-xs">{order.id.slice(-4)}</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-sm font-black text-gray-900">{order.customerName}</span>
                          <p className="text-[11px] text-gray-500 w-96 truncate">{order.details}</p>
                          <span className="text-[9px] font-bold text-gray-300 uppercase mt-1">{order.date}</span>
                        </div>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-xl font-display text-primary">${order.total.toFixed(2)}</span>
                        <div className="mt-1 flex items-center gap-2">
                           <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                           <span className="text-[9px] font-black text-amber-500 uppercase tracking-widest">Pendiente</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* TAB: TAMAÑOS */}
          {activeTab === 'SIZES' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-sm font-black text-gray-900 uppercase tracking-widest">Editor de Tamaños y Porciones</h2>
                <button onClick={addSize} className="bg-primary text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase">Añadir Tamaño</button>
              </div>
              <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-200">
                <table className="w-full text-left">
                  <thead className="bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Diámetro (cm)</th>
                      <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Tipo</th>
                      <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Texto Porciones</th>
                      <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Precio Base ($)</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {config.sizes.map(size => (
                      <tr key={size.id}>
                        <td className="px-6 py-4">
                          <input 
                            type="number" 
                            className="w-16 bg-gray-50 border-none rounded-lg p-2 text-xs font-bold"
                            value={size.diameter}
                            onChange={(e) => updateSize(size.id, 'diameter', parseInt(e.target.value))}
                          />
                        </td>
                        <td className="px-6 py-4">
                          <select 
                            className="bg-gray-50 border-none rounded-lg p-2 text-[10px] font-black uppercase"
                            value={size.heightType}
                            onChange={(e) => updateSize(size.id, 'heightType', e.target.value)}
                          >
                            <option value="SHORT">Bajo (10cm)</option>
                            <option value="TALL">Alto (17cm)</option>
