                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* TAB: COLORES */}
          {activeTab === 'COLORS' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-sm font-black text-gray-900 uppercase tracking-widest">Paleta de Colores de Crema</h2>
                <button onClick={addColor} className="bg-primary text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase">Añadir Color</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {config.colors.map((color, index) => (
                  <div key={index} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100 flex items-center gap-4 group">
                    <div 
                      className="w-14 h-14 rounded-2xl shadow-inner border-2 border-white relative cursor-pointer overflow-hidden"
                      style={{ backgroundColor: color.hex }}
                    >
                      <input 
                        type="color" 
                        className="absolute inset-0 opacity-0 cursor-pointer"
                        value={color.hex}
                        onChange={(e) => updateColor(index, 'hex', e.target.value)}
                      />
                    </div>
                    <div className="flex-1 space-y-2">
                      <input 
                        type="text" 
                        className="w-full bg-gray-50 border-none rounded-xl p-2 text-xs font-black uppercase tracking-widest"
                        value={color.name}
                        onChange={(e) => updateColor(index, 'name', e.target.value)}
                      />
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={color.isSaturated}
                          onChange={(e) => updateColor(index, 'isSaturated', e.target.checked)}
