                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Saturado (+$5)</span>
                      </label>
                    </div>
                    <button onClick={() => removeColor(index)} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                      <span className="material-icons-round">delete</span>
                    </button>
