                ))}
              </div>
            </div>
          )}

          {/* TAB: FLAVORS */}
          {activeTab === 'FLAVORS' && (
            <div className="bg-white rounded-3xl p-10 text-center border-2 border-gray-100">
               <span className="material-icons-round text-gray-200 text-4xl mb-4">construction</span>
               <p className="text-gray-400 font-bold uppercase tracking-widest text-xs">Módulo en Desarrollo</p>
