import React from 'react';
import { DecorationStyle, TopperType, AppState, AppConfig } from '../types';

interface DecorationStepProps {
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  onUpdateDecoration: (data: Partial<AppState>) => void;
  onNext: () => void;
  onBack: () => void;
  totalPrice: number;
  // Added config to the props to allow access to dynamic color palette
  config: AppConfig;
}

const DecorationStep: React.FC<DecorationStepProps> = ({ 
  selectedDecoration, 
  cakeColors,
  topperType,
  hasSpheres,
  onUpdateDecoration, 
  onNext, 
  onBack,
  totalPrice,
  config
}) => {
  const styles = {
    liso: { label: "Liso", desc: "Clásico y elegante", icon: "crop_square" },
    vintage: { label: "Vintage", desc: "Volantes de crema", icon: "auto_awesome" },
    textura: { label: "Textura", desc: "Rayado artístico", icon: "reorder" },
    degradado: { label: "Degradado", desc: "Efecto Ombré", icon: "opacity" }
  };

  const toppers: { id: TopperType; label: string; icon: string }[] = [
    { id: 'none', label: 'Sin Topper', icon: 'do_not_disturb_on' },
    { id: 'generic', label: 'Genérico', icon: 'star' },
    { id: 'personalized', label: 'Personalizado', icon: 'edit' },
    { id: 'plus_pieces', label: 'Topper + Piezas', icon: 'auto_fix_high' },
  ];

  const handleColorClick = (hex: string) => {
    if (selectedDecoration !== 'degradado') {
      onUpdateDecoration({ cakeColors: [hex] });
    } else {
      if (cakeColors.includes(hex)) {
        if (cakeColors.length > 1) {
          onUpdateDecoration({ cakeColors: cakeColors.filter(c => c !== hex) });
        }
      } else {
        if (cakeColors.length < 3) {
          onUpdateDecoration({ cakeColors: [...cakeColors, hex] });
        }
      }
    }
  };

  const renderCakeBody = () => {
    if (selectedDecoration === 'degradado') {
      const stops = cakeColors.length === 1 
        ? [{ offset: '0%', color: '#FFFFFF' }, { offset: '100%', color: cakeColors[0] }]
        : cakeColors.map((color, i) => ({ offset: `${(i / (cakeColors.length - 1)) * 100}%`, color }));

      return (
        <g>
          <defs>
            <linearGradient id="cakeGrad" x1="0%" y1="0%" x2="0%" y2="100%">
              {stops.map((stop, i) => <stop key={i} offset={stop.offset} stopColor={stop.color} />)}
            </linearGradient>
          </defs>
          <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill="url(#cakeGrad)" stroke="#D1D5DB" strokeWidth="1"></path>
        </g>
      );
    }

    const primaryColor = cakeColors[0] || '#FFFFFF';
    return (
      <g>
        <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill={primaryColor} stroke="#D1D5DB" strokeWidth="1"></path>
        {selectedDecoration === 'textura' && (
          <g opacity="0.4">
            <line x1="45" y1="130" x2="155" y2="130" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="160" x2="155" y2="160" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="190" x2="155" y2="190" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
            <line x1="45" y1="220" x2="155" y2="220" stroke="#000" strokeWidth="1" strokeDasharray="1 2" />
          </g>
        )}
        {selectedDecoration === 'vintage' && (
          <g>
            <path d="M45 100 Q60 85 75 100 Q90 85 105 100 Q120 85 135 100 Q150 85 155 100" fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth="5" />
            <path d="M45 200 Q60 185 75 200 Q90 185 105 200 Q120 185 135 200 Q150 185 155 200" fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth="5" />
          </g>
        )}
      </g>
    );
  };

  return (
    <div className="flex flex-col h-full bg-background-light relative animate-fadeIn">
      {/* Cabecera optimizada para escritorio */}
      <header className="pt-8 pb-4 px-8 flex items-center justify-between z-20 bg-white shadow-sm border-b">
        <div className="flex items-center gap-6">
          <button onClick={onBack} className="w-12 h-12 rounded-full bg-gray-50 flex items-center justify-center text-gray-900 transition-all active:scale-90 hover:bg-white hover:shadow-md border border-gray-100">
            <span className="material-icons-round">arrow_back</span>
          </button>
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-primary uppercase tracking-widest">Paso 3 de 5</span>
            <h1 className="text-2xl font-display text-gray-900 uppercase">Diseño Exterior</h1>
          </div>
        </div>
        <div className="hidden md:flex bg-primary/10 px-6 py-2 rounded-2xl items-center gap-3 border border-primary/20">
           <span className="material-icons-round text-primary">auto_fix_high</span>
           <span className="text-xs font-black text-primary uppercase tracking-widest">Editor en tiempo real</span>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row w-full z-10 overflow-hidden">

        {/* PANEL IZQUIERDO: PREVISUALIZACIÓN (FIJO EN DESKTOP) */}
        <div className="w-full md:w-[45%] bg-gray-50/50 flex flex-col items-center justify-center p-8 border-r border-gray-100">
          <div className="relative w-full max-w-[320px] aspect-[3/4] filter drop-shadow-[0_45px_45px_rgba(0,0,0,0.12)] transform scale-125 md:scale-100 lg:scale-125">
            <svg className="w-full h-full" viewBox="0 0 200 300">
              <ellipse cx="100" cy="285" fill="rgba(0,0,0,0.05)" rx="80" ry="12"></ellipse>
              {renderCakeBody()}
              <ellipse cx="100" cy="100" fill="#FFFFFF" rx="55" ry="15" stroke="rgba(0,0,0,0.05)" strokeWidth="1"></ellipse>
              {topperType !== 'none' && (
                <g className="animate-pop">
                   <line x1="100" y1="50" x2="100" y2="90" stroke="#999" strokeWidth="2" />
                   <rect x="65" y="20" width="70" height="45" rx="10" fill="#E31C58" />
                   <text x="100" y="47" textAnchor="middle" fill="white" fontSize="9" fontWeight="900">CAKE</text>
                </g>
              )}
              {hasSpheres && (
                <g className="animate-pop">
                  <circle cx="155" cy="130" r="14" fill="#E31C58" stroke="#fff" strokeWidth="3" />
                  <circle cx="170" cy="165" r="10" fill="#FFEB3B" stroke="#fff" strokeWidth="3" />
                </g>
              )}
            </svg>
          </div>
          <div className="mt-12 bg-white px-8 py-3 rounded-full shadow-soft border border-gray-100 hidden md:block">
             <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Vista Previa de Producción</span>
          </div>
        </div>

        {/* PANEL DERECHO: OPCIONES (SCROLLABLE) */}
        <div className="flex-1 overflow-y-auto no-scrollbar p-8 space-y-12 pb-44">
          <section>
            <h3 className="text-[12px] font-black text-gray-900 uppercase tracking-widest mb-6 flex items-center gap-3">
               <span className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
                 <span className="material-icons-round text-sm">brush</span>
               </span>
               1. ESTILO DE ACABADO
            </h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
              {(Object.keys(styles) as DecorationStyle[]).map(key => (
                <button 
                  key={key}
                  onClick={() => onUpdateDecoration({ selectedDecoration: key })}
                  className={`flex flex-col items-center gap-3 p-5 rounded-3xl border-2 transition-all ${selectedDecoration === key ? 'border-primary bg-primary/5 shadow-lg' : 'border-gray-100 bg-white text-gray-400 hover:border-gray-200'}`}
                >
                  <span className="material-icons-round text-2xl">{styles[key].icon}</span>
                  <span className="text-[10px] font-black uppercase tracking-widest text-center">{styles[key].label}</span>
                </button>
              ))}
            </div>
          </section>

          <section>
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-[12px] font-black text-gray-900 uppercase tracking-widest flex items-center gap-3">
                  <span className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
                    <span className="material-icons-round text-sm">palette</span>
                  </span>
                  2. COLORES DE LA CREMA
                </h3>
            </div>
            <div className="grid grid-cols-6 lg:grid-cols-12 gap-4 mb-8">
              {/* Use config.colors from the app state instead of constants */}
              {config.colors.map((color) => {
                const isSelected = cakeColors.includes(color.hex);
                return (
                  <button
                    key={color.name}
                    onClick={() => handleColorClick(color.hex)}
                    className={`aspect-square rounded-full border-4 shadow-sm transition-all transform hover:scale-110 active:scale-90 relative flex items-center justify-center ${isSelected ? 'border-primary scale-110 ring-4 ring-primary/10' : 'border-white'}`}
                    style={{ backgroundColor: color.hex }}
                    title={color.name}
                  >
                    {isSelected && <span className={`material-icons-round ${color.hex === '#FFFFFF' ? 'text-primary' : 'text-white'} text-lg`}>check</span>}
                  </button>
                );
              })}
            </div>
            <div className="bg-white p-6 rounded-[2rem] border-2 border-gray-100 flex items-start gap-4">
                <span className="material-icons-round text-amber-500">priority_high</span>
                <p className="text-[10px] font-bold text-gray-500 uppercase leading-relaxed tracking-wider">
                  Colores oscuros (Negro, Rojo) requieren mayor cantidad de colorante y pueden teñir levemente la boca.
                </p>
            </div>
          </section>

          <section>
            <h3 className="text-[12px] font-black text-gray-900 uppercase tracking-widest mb-6 flex items-center gap-3">
               <span className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
                 <span className="material-icons-round text-sm">star</span>
               </span>
               3. ACCESORIOS Y TOPPERS
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {toppers.map(t => (
                <button 
                  key={t.id}
                  onClick={() => onUpdateDecoration({ topperType: t.id })}
                  className={`flex items-center gap-5 p-6 rounded-3xl border-2 transition-all ${topperType === t.id ? 'border-primary bg-primary/5 text-primary shadow-lg' : 'border-gray-100 bg-white text-gray-400'}`}
                >
                  <span className="material-icons-round text-2xl">{t.icon}</span>
                  <div className="flex flex-col text-left">
                    <span className="text-[11px] font-black uppercase tracking-widest">{t.label}</span>
                  </div>
                </button>
              ))}
            </div>
          </section>

          <section className="bg-white p-8 rounded-[3rem] shadow-soft border border-gray-100 flex items-center justify-between">
             <div className="flex items-center gap-6">
                <div className={`w-16 h-16 rounded-3xl flex items-center justify-center transition-all ${hasSpheres ? 'bg-primary text-white' : 'bg-gray-100 text-gray-300'}`}>
                   <span className="material-icons-round text-3xl">lens</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-sm font-black text-gray-900 uppercase tracking-widest">Esferas Decorativas</span>
                  <span className="text-[11px] text-primary font-bold uppercase">Añade +$8.00 al total</span>
                </div>
             </div>
             <button 
                onClick={() => onUpdateDecoration({ hasSpheres: !hasSpheres })}
                className={`w-16 h-9 rounded-full relative flex items-center px-1 transition-all ${hasSpheres ? 'bg-primary' : 'bg-gray-300'}`}
             >
                <div className={`w-7 h-7 rounded-full bg-white shadow-md transform transition-transform duration-300 ${hasSpheres ? 'translate-x-7' : 'translate-x-0'}`}></div>
             </button>
          </section>
        </div>
      </main>

      {/* FOOTER: Resumen inferior para web */}
      <footer className="fixed md:absolute bottom-0 left-0 right-0 bg-white p-8 z-50 shadow-[0_-15px_50px_rgba(0,0,0,0.1)] border-t rounded-t-[3rem] md:rounded-none">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex flex-col">
            <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-1">Inversión Estimada</span>
            <div className="text-4xl font-display text-gray-900 animate-pop">${totalPrice.toFixed(2)}</div>
          </div>
          <button 
            onClick={onNext}
            className="bg-primary hover:bg-rose-600 text-white font-black py-5 px-20 rounded-full shadow-2xl shadow-primary/30 active:scale-95 transition-all text-sm uppercase tracking-[0.2em] flex items-center gap-4"
          >
            Siguiente Paso
            <span className="material-icons-round">arrow_forward</span>
          </button>
        </div>
      </footer>
    </div>
  );
