  return (
    <div className="flex flex-col h-full bg-slate-50 overflow-hidden font-quicksand">
      {/* Sidebar / Header con Contraste Mejorado */}
      <header className="bg-white border-b-2 border-slate-200 px-8 py-6 flex items-center justify-between z-10 shrink-0 shadow-sm">
