          <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center text-white shadow-xl">
            <span className="material-icons-round">settings</span>
          </div>
          <div>
            <h1 className="text-xl font-display text-slate-900 uppercase leading-none">Configuración de Tienda</h1>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">Panel Administrativo v3.0</p>
          </div>
        </div>
        <button 
          onClick={onExit}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-primary transition-all flex items-center gap-2 shadow-lg"
        >
          <span className="material-icons-round text-sm">logout</span>
          Cerrar Panel
        </button>
      </header>

      {/* Tabs con Mejor Visibilidad */}
      <nav className="bg-white border-b border-slate-200 px-8 flex gap-6 shrink-0 overflow-x-auto no-scrollbar">
