                            <option value="SHORT">Bajo (10cm)</option>
                            <option value="TALL">Alto (17cm)</option>
                          </select>
                        </td>
                        <td className="px-6 py-4">
                          <input type="text" className="w-full bg-white border border-slate-200 rounded-lg p-2 text-sm font-medium text-slate-700" value={size.portions} onChange={(e) => updateSize(size.id, 'portions', e.target.value)} />
                        </td>
                        <td className="px-6 py-4">
                          <input type="number" className="w-24 bg-white border border-slate-200 rounded-lg p-2 text-sm font-black text-primary" value={size.basePrice} onChange={(e) => updateSize(size.id, 'basePrice', parseFloat(e.target.value))} />
                        </td>
                        <td className="px-6 py-4 text-right">
                          <button onClick={() => removeSize(size.id)} className="text-slate-300 hover:text-rose-500"><span className="material-icons-round">delete</span></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* TAB: SABORES Y RELLENOS */}
          {activeTab === 'FLAVORS' && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <section className="space-y-6">
                <div className="flex justify-between items-center">
                  <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest">Sabores de Bizcocho</h2>
                  <button onClick={addFlavor} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest">Nuevo Sabor</button>
                </div>
                <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden shadow-sm">
                   {config.flavors.map(f => (
                     <div key={f.id} className="p-4 flex items-center gap-4 border-b border-slate-100 last:border-0 hover:bg-slate-50">
                        <div className="w-10 h-10 rounded-xl border-2 border-white shadow-sm shrink-0" style={{ backgroundColor: f.color }}></div>
                        <div className="flex-1 grid grid-cols-3 gap-3">
                           <input type="text" className="bg-slate-50 border-none rounded-lg p-2 text-xs font-bold" value={f.name} onChange={(e) => updateFlavor(f.id, 'name', e.target.value)} />
                           <input type="text" className="bg-slate-50 border-none rounded-lg p-2 text-[10px] font-mono" value={f.color} onChange={(e) => updateFlavor(f.id, 'color', e.target.value)} />
                           <div className="flex items-center gap-2 bg-slate-50 rounded-lg px-2">
                              <span className="text-[9px] font-black text-slate-400">+$</span>
                              <input type="number" className="w-full bg-transparent border-none p-2 text-xs font-black text-slate-900" value={f.priceModifier} onChange={(e) => updateFlavor(f.id, 'priceModifier', parseFloat(e.target.value))} />
                           </div>
                        </div>
                     </div>
                   ))}
                </div>
              </section>

              <section className="space-y-6">
                <div className="flex justify-between items-center">
                  <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest">Rellenos Disponibles</h2>
                  <button onClick={addFilling} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest">Nuevo Relleno</button>
                </div>
                <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden shadow-sm">
                   {config.fillings.map(f => (
                     <div key={f.id} className="p-4 flex items-center gap-4 border-b border-slate-100 last:border-0 hover:bg-slate-50">
                        <div className="w-10 h-10 rounded-xl border-2 border-white shadow-sm shrink-0" style={{ backgroundColor: f.color }}></div>
                        <div className="flex-1 grid grid-cols-3 gap-3">
                           <input type="text" className="bg-slate-50 border-none rounded-lg p-2 text-xs font-bold" value={f.name} onChange={(e) => updateFilling(f.id, 'name', e.target.value)} />
                           <input type="text" className="bg-slate-50 border-none rounded-lg p-2 text-[10px] font-mono" value={f.color} onChange={(e) => updateFilling(f.id, 'color', e.target.value)} />
                           <div className="flex items-center gap-2 bg-slate-50 rounded-lg px-2">
                              <span className="text-[9px] font-black text-slate-400">+$</span>
                              <input type="number" className="w-full bg-transparent border-none p-2 text-xs font-black text-slate-900" value={f.priceModifier} onChange={(e) => updateFilling(f.id, 'priceModifier', parseFloat(e.target.value))} />
                           </div>
                        </div>
                     </div>
                   ))}
                </div>
              </section>
            </div>
          )}

          {/* TAB: ESTILOS DE DECORACIÓN */}
          {activeTab === 'DECORATIONS' && (
            <div className="space-y-6">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest">Precios por Estilo de Acabado</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                 {(Object.keys(config.decorations) as DecorationStyle[]).map(key => (
                   <div key={key} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-200 flex flex-col items-center text-center">
                      <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center mb-4">
                         <span className="material-icons-round text-slate-900 text-3xl">
                            {key === 'liso' ? 'crop_square' : key === 'vintage' ? 'auto_awesome' : key === 'textura' ? 'reorder' : 'opacity'}
                         </span>
                      </div>
                      <input type="text" className="w-full text-center bg-transparent border-none font-black text-slate-900 uppercase tracking-widest text-xs mb-1" value={config.decorations[key].label} onChange={(e) => updateDecoration(key, 'label', e.target.value)} />
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-4 tracking-tighter">ID: {key}</p>
                      <div className="flex items-center gap-2 bg-slate-100 px-6 py-2 rounded-2xl w-full justify-center">
                        <span className="text-xs font-black text-slate-500">$</span>
                        <input type="number" className="w-12 bg-transparent border-none text-center font-black text-slate-900" value={config.decorations[key].priceModifier} onChange={(e) => updateDecoration(key, 'priceModifier', parseFloat(e.target.value))} />
                      </div>
                   </div>
                 ))}
              </div>
            </div>
          )}

          {/* TAB: PALETA DE COLORES */}
          {activeTab === 'COLORS' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest">Editor de Colores de Crema</h2>
                <button onClick={addColor} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-md">Nuevo Color</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6">
                {config.colors.map((color, index) => (
                  <div key={index} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-200 flex items-center gap-4 group hover:border-slate-300 transition-all">
                    <div className="w-14 h-14 rounded-2xl shadow-inner border-2 border-slate-100 relative cursor-pointer overflow-hidden shrink-0" style={{ backgroundColor: color.hex }}>
                      <input type="color" className="absolute inset-0 opacity-0 cursor-pointer" value={color.hex} onChange={(e) => updateColor(index, 'hex', e.target.value)} />
                    </div>
                    <div className="flex-1 space-y-2">
                      <input type="text" className="w-full bg-slate-50 border-none rounded-xl p-2 text-[10px] font-black text-slate-900 uppercase tracking-widest" value={color.name} onChange={(e) => updateColor(index, 'name', e.target.value)} />
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input type="checkbox" checked={color.isSaturated} onChange={(e) => updateColor(index, 'isSaturated', e.target.checked)} className="rounded text-slate-900 focus:ring-slate-900" />
                        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Saturado (Recargo)</span>
                      </label>
                    </div>
                    <button onClick={() => removeColor(index)} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"><span className="material-icons-round">delete</span></button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* TAB: PRECIOS GLOBALES */}
          {activeTab === 'PRICES' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {/* Topper Prices */}
              <section className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm space-y-6">
                 <h2 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                    <span className="material-icons-round text-slate-900">auto_fix_high</span>
                    Precios Toppers
                 </h2>
                 {(Object.keys(config.topperPrices) as TopperType[]).map(type => (
                   <div key={type} className="flex items-center justify-between group">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{type.replace('_', ' ')}</span>
                      <div className="flex items-center gap-2 bg-slate-50 px-4 py-1.5 rounded-xl border border-slate-100 group-focus-within:border-slate-300">
                         <span className="text-[10px] font-black text-slate-400">$</span>
                         <input type="number" className="w-12 bg-transparent border-none text-right font-black text-slate-900 text-xs" value={config.topperPrices[type]} onChange={(e) => updateNestedPrice('topperPrices', type, parseFloat(e.target.value))} />
                      </div>
                   </div>
                 ))}
              </section>

              {/* Coverage Surcharges */}
              <section className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm space-y-6">
                 <h2 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                    <span className="material-icons-round text-slate-900">palette</span>
                    Recargos Cobertura
                 </h2>
                 {(Object.keys(config.coverageSurcharges) as CoverageType[]).map(type => (
                   <div key={type} className="flex items-center justify-between group">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{type}</span>
                      <div className="flex items-center gap-2 bg-slate-50 px-4 py-1.5 rounded-xl border border-slate-100 group-focus-within:border-slate-300">
                         <span className="text-[10px] font-black text-slate-400">$</span>
                         <input type="number" className="w-12 bg-transparent border-none text-right font-black text-slate-900 text-xs" value={config.coverageSurcharges[type]} onChange={(e) => updateNestedPrice('coverageSurcharges', type, parseFloat(e.target.value))} />
                      </div>
                   </div>
                 ))}
              </section>

              {/* Misc Extras */}
              <section className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm space-y-8">
                 <h2 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                    <span className="material-icons-round text-slate-900">add_circle</span>
                    Otros Extras
                 </h2>
                 <div className="space-y-6">
                    <div className="flex flex-col gap-2">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Esferas Decorativas ($)</label>
                       <input type="number" className="w-full bg-slate-50 border border-slate-100 rounded-xl p-3 font-black text-slate-900 text-sm" value={config.spheresPrice} onChange={(e) => updateGlobalPrice('spheresPrice', parseFloat(e.target.value))} />
                    </div>
                    <div className="flex flex-col gap-2">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Surcharge Color Saturado ($)</label>
                       <input type="number" className="w-full bg-slate-50 border border-slate-100 rounded-xl p-3 font-black text-slate-900 text-sm" value={config.saturatedColorSurcharge} onChange={(e) => updateGlobalPrice('saturatedColorSurcharge', parseFloat(e.target.value))} />
                    </div>
                 </div>
              </section>
            </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

export type Step = 'SIZE' | 'FLAVOR' | 'DECORATION' | 'PERSONALIZATION' | 'SUMMARY' | 'PAYMENT' | 'ADMIN_LOGIN' | 'ADMIN_PANEL';

export type HeightType = 'TALL' | 'SHORT';
export type DeliveryMethod = 'DELIVERY' | 'PICKUP';
export type CoverageType = 'chantilly' | 'chocolate' | 'arequipe';

export interface CakeColor {
  name: string;
  hex: string;
  isSaturated?: boolean;
}

export interface CakeSize {
  id: string;
  diameter: number;
  heightType: HeightType;
  portions: string;
  basePrice: number;
}

export interface Flavor {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
  textureUrl?: string; // Para imágenes subidas por el admin
}

export interface Filling {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
  textureUrl?: string; // Para imágenes subidas por el admin
}

export type DecorationStyle = 'liso' | 'vintage' | 'textura' | 'degradado';
export type TopperType = 'none' | 'generic' | 'personalized' | 'plus_pieces';

export interface DecorationInfo {
  id: DecorationStyle;
  label: string;
  priceModifier: number;
}

export interface AppConfig {
  sizes: CakeSize[];
  flavors: Flavor[];
  fillings: Filling[];
  colors: CakeColor[];
  decorations: Record<string, DecorationInfo>;
  topperPrices: Record<string, number>;
  spheresPrice: number;
  saturatedColorSurcharge: number;
  coverageSurcharges: Record<string, number>;
}

export interface Order {
  id: string;
  date: string;
  customerName: string;
  details: string;
  total: number;
  status: 'PENDING' | 'COMPLETED';
}

export interface AppState {
  step: Step;
  selectedSize: CakeSize | null;
  selectedFlavor: Flavor | null;
  selectedFilling: Filling | null;
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  theme: string;
  birthdayName: string;
  birthdayAge: string;
  specialRequirements: string;
  referenceImage: string | null;
  paymentReference: string;
  amountBs: string;
  paymentProof: string | null;
  deliveryMethod: DeliveryMethod;
  deliveryDate: string;
  deliveryTime: string;
  coverageType: CoverageType;
  totalPrice: number;
  customFlavor: string;
  customFilling: string;
}

import React, { useState } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, CakeColor, DecorationStyle, TopperType, CoverageType } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES'>('ORDERS');

  const handleTextureUpload = (id: string, type: 'flavor' | 'filling', file: File | null) => {
    if (!file) {
      if (type === 'flavor') updateFlavor(id, 'textureUrl', undefined);
      else updateFilling(id, 'textureUrl', undefined);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      if (type === 'flavor') updateFlavor(id, 'textureUrl', reader.result as string);
      else updateFilling(id, 'textureUrl', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const updateSize = (id: string, field: keyof CakeSize, value: any) => {
    const newSizes = config.sizes.map(s => s.id === id ? { ...s, [field]: value } : s);
    onUpdateConfig({ ...config, sizes: newSizes });
  };

  const addSize = () => {
    const newSize: CakeSize = { id: `new_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porciones', basePrice: 20 };
    onUpdateConfig({ ...config, sizes: [...config.sizes, newSize] });
  };

  const removeSize = (id: string) => {
    onUpdateConfig({ ...config, sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, field: keyof Flavor, value: any) => {
    const newFlavors = config.flavors.map(f => f.id === id ? { ...f, [field]: value } : f);
    onUpdateConfig({ ...config, flavors: newFlavors });
  };

  const addFlavor = () => {
    const newFlavor: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo Sabor', color: '#FFFFFF', priceModifier: 0 };
    onUpdateConfig({ ...config, flavors: [...config.flavors, newFlavor] });
  };

  const removeFlavor = (id: string) => {
    onUpdateConfig({ ...config, flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, field: keyof Filling, value: any) => {
    const newFillings = config.fillings.map(f => f.id === id ? { ...f, [field]: value } : f);
    onUpdateConfig({ ...config, fillings: newFillings });
  };

  const addFilling = () => {
    const newFilling: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo Relleno', color: '#FFFFFF', priceModifier: 0 };
    onUpdateConfig({ ...config, fillings: [...config.fillings, newFilling] });
  };

  const removeFilling = (id: string) => {
    onUpdateConfig({ ...config, fillings: config.fillings.filter(f => f.id !== id) });
  };

  const updateColor = (index: number, field: keyof CakeColor, value: any) => {
    const newColors = [...config.colors];
    newColors[index] = { ...newColors[index], [field]: value };
    onUpdateConfig({ ...config, colors: newColors });
  };

  const addColor = () => {
    onUpdateConfig({ ...config, colors: [...config.colors, { name: 'Nuevo', hex: '#000000' }] });
  };

  const updateDecoration = (styleId: DecorationStyle, field: keyof any, value: any) => {
    const newDecors = { ...config.decorations };
    newDecors[styleId] = { ...newDecors[styleId], [field]: value };
    onUpdateConfig({ ...config, decorations: newDecors });
  };

  const updateNestedPrice = (parent: 'topperPrices' | 'coverageSurcharges', key: string, value: number) => {
    onUpdateConfig({ ...config, [parent]: { ...config[parent], [key]: value } });
  };

  return (
    <div className="flex flex-col h-full bg-slate-100 overflow-hidden font-quicksand">
      <header className="bg-slate-900 px-8 py-5 flex items-center justify-between z-10 shrink-0 shadow-2xl">
        <div className="flex items-center gap-5">
          <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center text-white shadow-lg">
            <span className="material-icons-round">dashboard</span>
          </div>
          <div>
            <h1 className="text-lg font-display text-white uppercase tracking-tight">Admin Cake Studio</h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Gestión de Catálogo y Precios</p>
          </div>
        </div>
        <button onClick={onExit} className="bg-white/10 text-white px-5 py-2.5 rounded-lg font-black text-[10px] uppercase tracking-widest hover:bg-primary transition-all flex items-center gap-2">
          <span className="material-icons-round text-sm">exit_to_app</span> Finalizar Cambios
        </button>
      </header>

      <nav className="bg-white border-b border-slate-300 px-8 flex gap-4 shrink-0 overflow-x-auto no-scrollbar">
        {[
          { id: 'ORDERS', label: 'Ventas', icon: 'receipt_long' },
          { id: 'SIZES', label: 'Moldes', icon: 'square_foot' },
          { id: 'FLAVORS', label: 'Sabores', icon: 'cake' },
          { id: 'DECORATIONS', label: 'Estilos', icon: 'brush' },
          { id: 'COLORS', label: 'Colores', icon: 'palette' },
          { id: 'PRICES', label: 'Extras', icon: 'sell' },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`py-4 flex items-center gap-2 border-b-4 transition-all shrink-0 ${activeTab === tab.id ? 'border-primary text-primary font-black' : 'border-transparent text-slate-400 font-bold hover:text-slate-600'}`}
          >
            <span className="material-icons-round text-lg">{tab.icon}</span>
            <span className="text-[10px] uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 md:p-10 overflow-y-auto no-scrollbar">
        <div className="max-w-7xl mx-auto space-y-8">

          {activeTab === 'FLAVORS' && (
            <div className="space-y-12">
              <section>
                <div className="flex justify-between items-center mb-6">
                  <h2 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em] border-l-4 border-primary pl-4">Bizcochos (Ponqués)</h2>
                  <button onClick={addFlavor} className="bg-primary text-white px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-lg shadow-primary/20 hover:scale-105 transition-transform">Nuevo Ponqué</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {config.flavors.map(f => (
                    <div key={f.id} className="bg-white p-5 rounded-3xl shadow-md border-2 border-slate-200 flex flex-col gap-4 group hover:border-primary/30 transition-all">
                      <div className="flex items-center gap-4">
                        <div className="relative w-16 h-16 rounded-2xl border-4 border-slate-50 shadow-inner overflow-hidden shrink-0" style={{ backgroundColor: f.color }}>
                          {f.textureUrl && <img src={f.textureUrl} className="w-full h-full object-cover" />}
                          <input type="color" className="absolute inset-0 opacity-0 cursor-pointer" value={f.color} onChange={(e) => updateFlavor(f.id, 'color', e.target.value)} />
                        </div>
                        <div className="flex-1 space-y-2">
                           <input type="text" className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl px-3 py-2 text-xs font-black uppercase text-slate-900 focus:border-primary outline-none" value={f.name} onChange={(e) => updateFlavor(f.id, 'name', e.target.value)} />
                           <div className="flex items-center gap-2">
                              <span className="text-[9px] font-black text-slate-400 uppercase">Costo Extra: $</span>
                              <input type="number" className="w-16 bg-slate-50 border-2 border-slate-100 rounded-lg px-2 py-1 text-xs font-black text-primary" value={f.priceModifier} onChange={(e) => updateFlavor(f.id, 'priceModifier', parseFloat(e.target.value))} />
                           </div>
                        </div>
                        <button onClick={() => removeFlavor(f.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><span className="material-icons-round">delete</span></button>
                      </div>
                      <div className="flex gap-2">
                        <label className="flex-1 bg-slate-900 text-white text-[9px] font-black uppercase tracking-widest py-2 rounded-xl text-center cursor-pointer hover:bg-primary transition-all">
                           {f.textureUrl ? 'Cambiar Textura' : 'Subir Textura'}
                           <input type="file" className="hidden" accept="image/*" onChange={(e) => handleTextureUpload(f.id, 'flavor', e.target.files?.[0] || null)} />
                        </label>
                        {f.textureUrl && (
                          <button onClick={() => updateFlavor(f.id, 'textureUrl', undefined)} className="bg-slate-100 text-slate-500 text-[9px] font-black uppercase tracking-widest py-2 px-4 rounded-xl hover:bg-slate-200">Quitar</button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              <section>
                <div className="flex justify-between items-center mb-6">
