                      </div>
                   </div>
                   <div className="text-right shrink-0">
                      <div className="text-2xl font-display text-primary">${order.total.toFixed(2)}</div>
                      <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">{order.date}</div>
