        <div className="flex items-center gap-5">
          <div className="w-12 h-12 bg-primary rounded-xl flex items-center justify-center text-white shadow-lg border border-white/10">
            <span className="material-icons-round text-3xl">dashboard</span>
          </div>
          <div>
            <h1 className="text-xl font-display text-white uppercase tracking-tight">Admin Cake Studio</h1>
            <p className="text-xs font-black text-slate-300 uppercase tracking-widest">Gestión de Catálogo y Precios</p>
          </div>
        </div>
        <button onClick={onExit} className="bg-white text-slate-900 px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-primary hover:text-white transition-all flex items-center gap-2 shadow-xl border border-white/20">
          <span className="material-icons-round text-sm">exit_to_app</span> Finalizar Cambios
        </button>
      </header>

