                      <span className="text-xs font-black text-slate-900 uppercase tracking-tighter">{type}</span>
                      <div className="flex items-center gap-2 bg-slate-100 px-4 py-2 rounded-xl border-2 border-slate-300 group-focus-within:border-primary transition-colors">
