                        <input type="number" className="w-16 bg-transparent border-none text-right font-black text-slate-900 text-sm focus:ring-0" value={config.coverageSurcharges[type]} onChange={(e) => updateNestedPrice('coverageSurcharges', type, parseFloat(e.target.value))} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-white p-8 rounded-[3.5rem] shadow-2xl border-2 border-slate-300 space-y-8">
                <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-3 border-b-2 border-slate-100 pb-5">
                   <span className="material-icons-round text-primary text-2xl">star</span> Otros Recargos
                </h3>
                <div className="space-y-6">
                  <div className="flex flex-col gap-3">
                    <label className="text-xs font-black text-slate-900 uppercase tracking-widest">Esferas Decorativas ($)</label>
                    <input type="number" className="w-full bg-slate-100 border-2 border-slate-400 rounded-2xl p-4 font-black text-slate-900 text-base focus:border-primary focus:bg-white transition-all outline-none" value={config.spheresPrice} onChange={(e) => onUpdateConfig({...config, spheresPrice: parseFloat(e.target.value)})} />
                  </div>
                  <div className="flex flex-col gap-3">
                    <label className="text-xs font-black text-slate-900 uppercase tracking-widest">Surcharge Colores Saturados ($)</label>
                    <input type="number" className="w-full bg-slate-100 border-2 border-slate-400 rounded-2xl p-4 font-black text-slate-900 text-base focus:border-primary focus:bg-white transition-all outline-none" value={config.saturatedColorSurcharge} onChange={(e) => onUpdateConfig({...config, saturatedColorSurcharge: parseFloat(e.target.value)})} />
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB: VENTAS - CON CONTRASTE MÁXIMO */}
          {activeTab === 'ORDERS' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                 <h2 className="text-sm font-black text-slate-900 uppercase tracking-widest border-l-8 border-primary pl-4">Cola de Pedidos Recibidos</h2>
                 <button onClick={onClearOrders} className="text-xs font-black text-red-600 uppercase tracking-widest border-2 border-red-600 px-5 py-2.5 rounded-xl hover:bg-red-600 hover:text-white transition-all shadow-lg">Borrar Historial</button>
              </div>
              <div className="grid grid-cols-1 gap-6">
                {orders.length === 0 ? (
                  <div className="bg-white rounded-[3rem] p-24 text-center border-4 border-dashed border-slate-300">
                    <span className="material-icons-round text-8xl text-slate-300 mb-6">receipt_long</span>
                    <p className="text-xl font-bold text-slate-900 uppercase tracking-widest">No hay ventas registradas aún</p>
                  </div>
                ) : (
                  orders.map(order => (
                    <div key={order.id} className="bg-white p-8 rounded-[3rem] shadow-2xl border-2 border-slate-300 flex flex-col md:flex-row items-center justify-between gap-8 hover:border-primary transition-all group">
                       <div className="flex items-center gap-8">
                          <div className="w-20 h-20 bg-slate-900 text-white rounded-[2rem] flex flex-col items-center justify-center font-black group-hover:bg-primary transition-colors shadow-xl">
                             <span className="text-xs opacity-60 uppercase mb-1">ID</span>
                             <span className="text-lg">{order.id.slice(-4)}</span>
                          </div>
                          <div>
                             <h4 className="font-black text-slate-900 uppercase text-xl mb-1">{order.customerName}</h4>
                             <p className="text-sm text-slate-900 leading-relaxed max-w-2xl font-black">{order.details}</p>
                             <div className="flex items-center gap-2 mt-2">
                                <span className="material-icons-round text-sm text-slate-600">calendar_today</span>
                                <span className="text-xs font-black text-slate-700 uppercase tracking-widest">{order.date}</span>
                             </div>
                          </div>
                       </div>
                       <div className="text-center md:text-right shrink-0 bg-slate-50 md:bg-transparent p-6 md:p-0 rounded-[2rem] w-full md:w-auto border-2 border-slate-200 md:border-none">
                          <div className="text-4xl font-display text-primary tracking-tighter mb-1">${order.total.toFixed(2)}</div>
                          <div className="inline-flex items-center gap-2 bg-green-100 text-green-900 px-4 py-1.5 rounded-full border-2 border-green-300">
                             <span className="w-2 h-2 rounded-full bg-green-700 animate-pulse"></span>
                             <span className="text-xs font-black uppercase tracking-widest">Pedido Confirmado</span>
                          </div>
                       </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}

        </div>
      </main>
    </div>
  );
};

