                >
                  <span className={`material-icons-round text-4xl ${selectedDecoration === key ? 'text-primary' : 'text-black'}`}>{styles[key].icon}</span>
                  <span className="text-[12px] font-black uppercase tracking-widest text-center text-black">{styles[key].label}</span>
                </button>
              ))}
            </div>
          </section>

          <section>
