                  <h2 className="text-lg font-black text-black uppercase tracking-[0.2em] border-l-8 border-primary pl-6">Sabores de Bizcocho</h2>
                  <button onClick={addFlavor} className="bg-black text-white px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest shadow-2xl hover:bg-primary transition-colors border-2 border-white/20">Añadir Nuevo</button>
                </div>
