                  {config.flavors.map(f => (
                    <div key={f.id} className="bg-white p-8 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.15)] border-4 border-slate-300 flex flex-col gap-6 group hover:border-primary transition-all">
                      <div className="flex items-center gap-6">
                        <div className="relative w-24 h-24 rounded-3xl border-4 border-slate-400 shadow-inner overflow-hidden shrink-0 bg-slate-200">
