                        {f.textureUrl && (
                          <button onClick={() => updateFilling(f.id, 'textureUrl', undefined)} className="bg-red-600 text-white text-xs font-black uppercase py-5 px-10 rounded-2xl shadow-xl hover:bg-red-700">Eliminar</button>
