                )}
              </div>
            </div>
          )}

          {/* ... resto de los apartados con estilo similar ... */}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React from 'react';
import { DecorationStyle, TopperType, AppState, AppConfig } from '../types';

interface DecorationStepProps {
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  onUpdateDecoration: (data: Partial<AppState>) => void;
  onNext: () => void;
  onBack: () => void;
  totalPrice: number;
  config: AppConfig;
}

const DecorationStep: React.FC<DecorationStepProps> = ({ 
  selectedDecoration, 
  cakeColors,
  topperType,
  hasSpheres,
  onUpdateDecoration, 
  onNext, 
  onBack,
  totalPrice,
  config
}) => {
  const styles = {
    liso: { label: "Acabado Liso", icon: "crop_square" },
    vintage: { label: "Estilo Vintage", icon: "auto_awesome" },
    textura: { label: "Rayado Artístico", icon: "reorder" },
    degradado: { label: "Efecto Degradado", icon: "opacity" }
  };

  const toppers: { id: TopperType; label: string; icon: string }[] = [
    { id: 'none', label: 'Sin Topper', icon: 'do_not_disturb_on' },
    { id: 'generic', label: 'Topper Genérico', icon: 'star' },
    { id: 'personalized', label: 'Personalizado', icon: 'edit' },
    { id: 'plus_pieces', label: 'Topper + Piezas', icon: 'auto_fix_high' },
  ];

  const handleColorClick = (hex: string) => {
    if (selectedDecoration !== 'degradado') {
      onUpdateDecoration({ cakeColors: [hex] });
    } else {
      if (cakeColors.includes(hex)) {
        if (cakeColors.length > 1) {
          onUpdateDecoration({ cakeColors: cakeColors.filter(c => c !== hex) });
        }
      } else {
        if (cakeColors.length < 3) {
          onUpdateDecoration({ cakeColors: [...cakeColors, hex] });
        }
      }
    }
  };

  const renderCakeBody = () => {
    if (selectedDecoration === 'degradado') {
      const stops = cakeColors.length === 1 
        ? [{ offset: '0%', color: '#FFFFFF' }, { offset: '100%', color: cakeColors[0] }]
        : cakeColors.map((color, i) => ({ offset: `${(i / (cakeColors.length - 1)) * 100}%`, color }));

      return (
        <g>
          <defs>
            <linearGradient id="cakeGrad" x1="0%" y1="0%" x2="0%" y2="100%">
              {stops.map((stop, i) => <stop key={i} offset={stop.offset} stopColor={stop.color} />)}
            </linearGradient>
          </defs>
          <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill="url(#cakeGrad)" stroke="#000" strokeWidth="2.5"></path>
        </g>
      );
    }

    const primaryColor = cakeColors[0] || '#FFFFFF';
    return (
      <g>
        <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill={primaryColor} stroke="#000" strokeWidth="2.5"></path>
        {selectedDecoration === 'textura' && (
          <g opacity="0.9">
            <line x1="45" y1="130" x2="155" y2="130" stroke="#000" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="160" x2="155" y2="160" stroke="#000" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="190" x2="155" y2="190" stroke="#000" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="220" x2="155" y2="220" stroke="#000" strokeWidth="2" strokeDasharray="1 3" />
          </g>
        )}
        {selectedDecoration === 'vintage' && (
          <g>
            <path d="M45 100 Q60 80 75 100 Q90 80 105 100 Q120 80 135 100 Q150 80 155 100" fill="none" stroke="rgba(0,0,0,0.4)" strokeWidth="6" />
            <path d="M45 190 Q60 170 75 190 Q90 170 105 190 Q120 170 135 190 Q150 170 155 190" fill="none" stroke="rgba(0,0,0,0.4)" strokeWidth="6" />
          </g>
        )}
      </g>
    );
  };

  return (
    <div className="flex flex-col h-full bg-background-light relative animate-fadeIn">
      <header className="pt-8 pb-4 px-8 flex items-center justify-between z-20 bg-white shadow-xl border-b-4 border-black">
        <div className="flex items-center gap-6">
          <button onClick={onBack} className="w-14 h-14 rounded-full bg-white flex items-center justify-center text-black transition-all active:scale-90 hover:bg-black hover:text-white border-4 border-black shadow-lg">
            <span className="material-icons-round text-2xl font-bold">arrow_back</span>
          </button>
          <div className="flex flex-col">
            <span className="text-[12px] font-black text-primary uppercase tracking-[0.3em] mb-1">PROCESO DE DISEÑO</span>
            <h1 className="text-3xl font-display text-black uppercase leading-none">Decoración Exterior</h1>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row w-full z-10 overflow-hidden">

        {/* VISTA PREVIA DEL PASTEL */}
        <div className="w-full md:w-[45%] bg-slate-100 flex flex-col items-center justify-center p-10 border-r-8 border-black relative">
          <div className="absolute top-6 left-6 flex flex-col gap-2">
             <span className="bg-black text-white text-[10px] font-black px-4 py-1 rounded-full uppercase tracking-widest">Vista Previa</span>
          </div>
          <div className="relative w-full max-w-[340px] aspect-[3/4] filter drop-shadow-[0_50px_60px_rgba(0,0,0,0.3)] transform scale-105">
            <svg className="w-full h-full" viewBox="0 0 200 300">
              <ellipse cx="100" cy="285" fill="rgba(0,0,0,0.25)" rx="85" ry="15"></ellipse>
              {renderCakeBody()}
              <ellipse cx="100" cy="100" fill="#FFFFFF" rx="55" ry="15" stroke="#000" strokeWidth="2.5"></ellipse>
              {topperType !== 'none' && (
                <g className="animate-pop">
                   <line x1="100" y1="50" x2="100" y2="90" stroke="#000" strokeWidth="3" />
                   <rect x="65" y="15" width="70" height="50" rx="12" fill="#E31C58" stroke="#000" strokeWidth="2" />
                   <text x="100" y="45" textAnchor="middle" fill="white" fontSize="12" fontWeight="900">PARTY</text>
                </g>
              )}
              {hasSpheres && (
                <g className="animate-pop">
                  <circle cx="155" cy="130" r="16" fill="#E31C58" stroke="#000" strokeWidth="2.5" />
                  <circle cx="172" cy="165" r="12" fill="#FFEB3B" stroke="#000" strokeWidth="2.5" />
                  <circle cx="145" cy="190" r="10" fill="#60A5FA" stroke="#000" strokeWidth="2.5" />
                </g>
              )}
            </svg>
          </div>
        </div>

        {/* PANEL DE MODIFICACIÓN */}
        <div className="flex-1 overflow-y-auto no-scrollbar p-10 space-y-16 pb-48 bg-white">
          <section>
            <h3 className="text-[16px] font-black text-black uppercase tracking-[0.2em] mb-8 flex items-center gap-4 border-l-8 border-black pl-5">
               1. ELIGE EL ESTILO DE COBERTURA
            </h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
              {(Object.keys(styles) as DecorationStyle[]).map(key => (
                <button 
                  key={key}
                  onClick={() => onUpdateDecoration({ selectedDecoration: key })}
                  className={`flex flex-col items-center gap-4 p-8 rounded-[3rem] border-4 transition-all shadow-lg ${selectedDecoration === key ? 'border-primary bg-primary/5 scale-110 shadow-primary/20' : 'border-black bg-white text-black hover:bg-slate-50'}`}
                >
                  <span className={`material-icons-round text-5xl ${selectedDecoration === key ? 'text-primary' : 'text-black'}`}>{styles[key].icon}</span>
                  <span className="text-[13px] font-black uppercase tracking-widest text-center text-black leading-tight">{styles[key].label}</span>
                </button>
              ))}
            </div>
          </section>

          <section>
            <h3 className="text-[16px] font-black text-black uppercase tracking-[0.2em] mb-8 flex items-center gap-4 border-l-8 border-black pl-5">
               2. PALETA DE COLORES (CREMA)
            </h3>
            <div className="grid grid-cols-6 lg:grid-cols-12 gap-6 mb-10">
              {config.colors.map((color) => {
                const isSelected = cakeColors.includes(color.hex);
                return (
                  <button
                    key={color.name}
                    onClick={() => handleColorClick(color.hex)}
                    className={`aspect-square rounded-full border-4 shadow-2xl transition-all transform hover:scale-125 active:scale-90 relative flex items-center justify-center ${isSelected ? 'border-primary scale-125 ring-8 ring-primary/20' : 'border-black'}`}
                    style={{ backgroundColor: color.hex }}
                    title={color.name}
                  >
                    {isSelected && <span className={`material-icons-round ${color.hex === '#FFFFFF' ? 'text-primary' : 'text-white'} text-3xl font-black drop-shadow-xl`}>check</span>}
                  </button>
                );
              })}
            </div>
            <div className="bg-red-50 p-8 rounded-[3rem] border-4 border-black flex items-start gap-6 shadow-xl">
                <div className="bg-black text-white p-2 rounded-full flex items-center justify-center">
                   <span className="material-icons-round text-2xl">priority_high</span>
                </div>
                <p className="text-[13px] font-black text-black uppercase leading-relaxed tracking-wider">
                  ATENCIÓN: Colores oscuros como Negro o Azul Rey pueden teñir la boca temporalmente.
                </p>
            </div>
          </section>

          <section>
            <h3 className="text-[16px] font-black text-black uppercase tracking-[0.2em] mb-8 flex items-center gap-4 border-l-8 border-black pl-5">
               3. TOPPERS Y ESFERAS
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
              {toppers.map(t => (
                <button 
                  key={t.id}
                  onClick={() => onUpdateDecoration({ topperType: t.id })}
                  className={`flex items-center gap-8 p-8 rounded-[3.5rem] border-4 transition-all ${topperType === t.id ? 'border-primary bg-primary/5 shadow-2xl scale-[1.03]' : 'border-black bg-white hover:bg-slate-50 shadow-lg'}`}
                >
                  <span className={`material-icons-round text-4xl ${topperType === t.id ? 'text-primary' : 'text-black'}`}>{t.icon}</span>
                  <div className="flex flex-col text-left">
                    <span className="text-[15px] font-black uppercase tracking-widest text-black">{t.label}</span>
                    <span className="text-[11px] font-bold text-slate-500 uppercase">Extra: ${config.topperPrices[t.id] || 0}</span>
                  </div>
                </button>
              ))}
            </div>

            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-black flex items-center justify-between group hover:border-primary transition-all">
               <div className="flex items-center gap-10">
                  <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center transition-all shadow-2xl border-4 ${hasSpheres ? 'bg-primary text-white border-black scale-110' : 'bg-slate-100 text-black border-slate-300'}`}>
                     <span className="material-icons-round text-5xl">lens</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xl font-black text-black uppercase tracking-widest leading-none mb-2">Esferas Decorativas</span>
                    <span className="text-sm font-black text-primary uppercase bg-primary/10 px-4 py-1 rounded-full border border-primary/20 w-fit">Recargo: +$8.00</span>
                  </div>
               </div>
               <button 
                  onClick={() => onUpdateDecoration({ hasSpheres: !hasSpheres })}
                  className={`w-24 h-12 rounded-full relative flex items-center px-2 transition-all shadow-inner border-4 border-black ${hasSpheres ? 'bg-primary' : 'bg-slate-400'}`}
               >
                  <div className={`w-8 h-8 rounded-full bg-white shadow-2xl transform transition-transform duration-500 ${hasSpheres ? 'translate-x-10' : 'translate-x-0'}`}></div>
               </button>
            </div>
          </section>
        </div>
      </main>

      <footer className="fixed md:absolute bottom-0 left-0 right-0 bg-white p-10 z-50 shadow-[0_-20px_60px_rgba(0,0,0,0.4)] border-t-[6px] border-black rounded-t-[4rem] md:rounded-none">
        <div className="max-w-5xl mx-auto flex items-center justify-between gap-10">
          <div className="flex flex-col">
            <span className="text-[14px] font-black text-slate-600 uppercase tracking-widest mb-1">Presupuesto Actual</span>
            <div className="text-6xl font-display text-black tracking-tighter animate-pop">${totalPrice.toFixed(2)}</div>
