                ) : (
                  orders.map(order => (
                    <div key={order.id} className="bg-white p-12 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.3)] border-4 border-black flex flex-col md:flex-row items-center justify-between gap-12 hover:border-primary transition-all group">
