                          <div className="w-28 h-28 bg-black text-white rounded-[3rem] flex flex-col items-center justify-center font-black shadow-2xl border-4 border-white group-hover:bg-primary transition-colors">
                             <span className="text-[10px] opacity-60 uppercase mb-1">REF</span>
                             <span className="text-2xl">{order.id.slice(-4)}</span>
                          </div>
                          <div>
                             <h4 className="font-black text-black uppercase text-3xl mb-3 tracking-tighter">{order.customerName}</h4>
                             <p className="text-lg text-black leading-relaxed max-w-2xl font-black opacity-90">{order.details}</p>
                             <div className="flex items-center gap-4 mt-6">
                                <span className="material-icons-round text-black text-2xl">event_available</span>
                                <span className="text-sm font-black text-black uppercase tracking-[0.2em]">{order.date}</span>
                             </div>
                          </div>
                       </div>
                       <div className="text-center md:text-right shrink-0 bg-slate-50 p-10 rounded-[3.5rem] w-full md:w-auto border-[6px] border-black shadow-inner">
                          <div className="text-6xl font-display text-primary tracking-tighter mb-3 animate-pop">${order.total.toFixed(2)}</div>
                          <div className="inline-flex items-center gap-4 bg-green-200 text-green-950 px-8 py-3 rounded-full border-4 border-green-500">
                             <span className="w-4 h-4 rounded-full bg-green-700 animate-pulse"></span>
                             <span className="text-sm font-black uppercase tracking-widest">Confirmado</span>
                          </div>
                       </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

