                      <div className="w-3 h-3 md:w-4 md:h-4 bg-white rotate-45 mx-auto -mt-1.5 md:-mt-2"></div>
                    </div>
                  )}

                  <svg 
                    viewBox={`0 0 ${cakeWidth} ${cakeHeight + 40}`} 
                    width={cakeWidth} 
                    height={cakeHeight + 40}
                    className={`transition-all duration-500 ${isSelected ? 'drop-shadow-[0_15px_15px_rgba(var(--primary-color-rgb),0.25)]' : 'drop-shadow-lg'}`}
                  >
                    <ellipse cx={cakeWidth/2} cy={cakeHeight + 20} rx={cakeWidth/2} ry="10" fill="rgba(0,0,0,0.08)" />
                    <path 
                      d={`M0 20 L0 ${cakeHeight} Q${cakeWidth/2} ${cakeHeight + 20} ${cakeWidth} ${cakeHeight} L${cakeWidth} 20`} 
                      fill={currentHeight === 'TALL' ? (isSelected ? 'var(--primary-color)' : '#F472B6') : (isSelected ? 'var(--secondary-color)' : '#FEF08A')} 
                    />
                    <ellipse cx={cakeWidth/2} cy="20" rx={cakeWidth/2} ry="15" fill={isSelected ? "#FFF" : "#FAFAFA"} stroke="rgba(0,0,0,0.1)" strokeWidth="1" />
                    <text 
                      x="50%" 
                      y={cakeHeight/2 + 25} 
                      textAnchor="middle" 
                      className={`font-display text-2xl md:text-4xl transition-all duration-500 pointer-events-none ${isSelected ? (currentHeight === 'TALL' ? 'fill-white' : 'fill-black') : 'fill-gray-400 opacity-60'}`}
                    >
                      {d}
                    </text>
                  </svg>
                </div>

                <div className={`mt-4 md:mt-6 flex flex-col items-center gap-0.5 md:gap-1 transition-all duration-500 ${isSelected ? 'opacity-100 translate-y-0 scale-100' : 'opacity-60 translate-y-2 scale-90'}`}>
                  <div className={`font-display text-3xl md:text-5xl tracking-tighter ${isSelected ? 'text-black' : 'text-gray-400'}`}>{d}cm</div>
                  <div className={`text-[8px] md:text-[10px] font-black uppercase tracking-[0.2em] md:tracking-[0.3em] px-3 md:px-4 py-0.5 rounded-full ${isSelected ? 'bg-primary/5 text-primary border border-primary/10' : 'bg-gray-100 text-gray-400 border border-transparent'}`}>
                    Diámetro
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </main>

      {/* FOOTER */}
      <footer className="bg-surface-light p-4 md:p-8 z-50 shadow-[0_-15px_30px_rgba(0,0,0,0.05)] rounded-t-[2.5rem] md:rounded-t-[3rem] border-t border-gray-100 shrink-0">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4 md:gap-6">
          <div className="flex flex-wrap justify-center md:justify-start items-center gap-6 md:gap-8">
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[8px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mb-0.5">Seleccionado</span>
              <div className="flex items-baseline justify-center md:justify-start gap-2">
                <span className="text-2xl md:text-3xl font-display text-black">{currentDiameter}cm</span>
                <span className="text-[9px] md:text-[10px] font-black text-primary uppercase bg-primary/5 px-2.5 md:px-3 py-0.5 rounded-lg border border-primary/10">
                  {currentCakeData?.portions || 'N/A'}
                </span>
              </div>
            </div>
            <div className="w-px h-8 bg-gray-100 hidden md:block"></div>
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[8px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mb-0.5">Precio Sugerido</span>
              <span className="text-2xl md:text-3xl font-display text-primary tracking-tighter">${(selectedSize?.basePrice || 0).toFixed(2)}</span>
            </div>
          </div>
          <button 
            onClick={onNext}
            className="w-full md:w-auto bg-primary hover:opacity-90 text-white font-black py-3.5 md:py-4 px-10 md:px-12 rounded-[1.5rem] md:rounded-[2rem] shadow-xl-primary transition-all active:scale-[0.98] flex items-center justify-center gap-3 md:gap-4 group text-xs md:text-sm"
          >
            <span className="uppercase tracking-[0.15em] md:tracking-[0.2em]">Personalizar Pastel</span>
            <span className="material-icons-round text-lg md:text-xl group-hover:translate-x-2 transition-transform">arrow_forward</span>
          </button>
        </div>
      </footer>
    </div>
  );
};

export default SizeStep;

export type Step = 'SIZE' | 'FLAVOR' | 'DECORATION' | 'PERSONALIZATION' | 'SUMMARY' | 'PAYMENT' | 'ADMIN_LOGIN' | 'ADMIN_PANEL';

export type HeightType = 'TALL' | 'SHORT';
export type DeliveryMethod = 'DELIVERY' | 'PICKUP';
export type CoverageType = 'chantilly' | 'chocolate' | 'arequipe';

export interface CakeColor {
  name: string;
  hex: string;
  isSaturated?: boolean;
}

export interface CakeSize {
  id: string;
  diameter: number;
  heightType: HeightType;
  portions: string;
  basePrice: number;
  costMultiplier: number; // Factor para multiplicar los costos de extras (sabores, rellenos, etc)
}

export interface Flavor {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
  textureUrl?: string;
}

export interface Filling {
  id: string;
  name: string;
  color: string;
  priceModifier: number;
  pattern?: string;
  textureUrl?: string;
}

export type DecorationStyle = 'liso' | 'vintage' | 'textura' | 'degradado';
export type TopperType = 'none' | 'generic' | 'personalized' | 'plus_pieces';

export interface DecorationInfo {
  id: DecorationStyle;
  label: string;
  priceModifier: number;
}

export interface PaymentDetails {
  bankName: string;
  accountHolder: string;
  zelleEmail: string;
  taxId: string;
  exchangeRateNote: string;
}

export interface AppTheme {
  brandName: string;
  whatsappNumber: string;
  primaryColor: string;
  secondaryColor: string;
  backgroundColor: string;
  textColor: string;
  surfaceColor: string;
}

export interface AppConfig {
  sizes: CakeSize[];
  flavors: Flavor[];
  fillings: Filling[];
  colors: CakeColor[];
  decorations: Record<string, DecorationInfo>;
  topperPrices: Record<string, number>;
  spheresPrice: number;
  saturatedColorSurcharge: number;
  coverageSurcharges: Record<string, number>;
  paymentDetails: PaymentDetails;
  appTheme: AppTheme;
}

export interface Order {
  id: string;
  date: string;
  customerName: string;
  details: string;
  total: number;
  status: 'PENDING' | 'COMPLETED';
}

export interface AppState {
  step: Step;
  selectedSize: CakeSize | null;
  selectedFlavor: Flavor | null;
  selectedFilling: Filling | null;
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  theme: string;
  birthdayName: string;
  birthdayAge: string;
  specialRequirements: string;
  referenceImage: string | null;
  paymentReference: string;
  amountBs: string;
  paymentProof: string | null;
  deliveryMethod: DeliveryMethod;
  deliveryDate: string;
  deliveryTime: string;
  coverageType: CoverageType;
  totalPrice: number;
  customFlavor: string;
  customFilling: string;
}

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, CakeSize, Flavor, Filling, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('cake_app_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.appTheme || !parsed.appTheme.primaryColor) {
        parsed.appTheme = {
          ...parsed.appTheme,
          brandName: parsed.appTheme?.brandName || "Cake Customizer Studio",
          whatsappNumber: parsed.appTheme?.whatsappNumber || "584241546473",
          primaryColor: "#E31C58",
          secondaryColor: "#FFEB3B",
          backgroundColor: "#FFFBF2",
          textColor: "#000000",
          surfaceColor: "#FFFFFF"
        };
      }
      return parsed;
    }
    return {
      sizes: CAKE_SIZES,
      flavors: FLAVORS,
      fillings: FILLINGS,
      colors: CAKE_COLORS,
      decorations: DECORATIONS,
      topperPrices: TOPPER_PRICES,
      spheresPrice: SPHERES_PRICE,
      saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
      coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
      paymentDetails: {
        bankName: "Pastelitos Bank",
        accountHolder: "Cakes Studio S.A.",
        zelleEmail: "pagos@cakesstudio.com",
        taxId: "J-12345678-9",
        exchangeRateNote: "Trabajamos con Tasa Euro (€)"
      },
      appTheme: {
        brandName: "Cake Customizer Studio",
        whatsappNumber: "584241546473",
        primaryColor: "#E31C58",
        secondaryColor: "#FFEB3B",
        backgroundColor: "#FFFBF2",
        textColor: "#000000",
        surfaceColor: "#FFFFFF"
      }
    };
  });

  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('cake_app_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[0],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFlavor: '',
    customFilling: '',
  });

  useEffect(() => {
    localStorage.setItem('cake_app_config', JSON.stringify(config));
  }, [config]);

  useEffect(() => {
    localStorage.setItem('cake_app_orders', JSON.stringify(orders));
  }, [orders]);

  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    const size = partial.selectedSize || state.selectedSize;
    const flavor = partial.selectedFlavor || state.selectedFlavor;
    const filling = partial.selectedFilling || state.selectedFilling;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;
    const currentColors = partial.cakeColors || state.cakeColors;

    // El multiplicador escala los costos extras según el tamaño físico del pastel
    const factor = size?.costMultiplier || 1.0;

    const base = size?.basePrice || 0;
    const fMod = (flavor?.priceModifier || 0) * factor;
    const fillMod = (filling?.priceModifier || 0) * factor;
    const decorMod = (config.decorations[decorId]?.priceModifier || 0) * factor;
    const coverageMod = (config.coverageSurcharges[coverage] || 0) * factor;

    // Toppers se mantienen estáticos usualmente (precio por pieza)
    const topperMod = config.topperPrices[topper] || 0;
    const spheresMod = spheres ? (config.spheresPrice * factor) : 0;

    let colorSurcharge = 0;
    const hasSaturated = currentColors.some(hex => 
        config.colors.find(c => c.hex === hex)?.isSaturated
    );
    if (hasSaturated) colorSurcharge = config.saturatedColorSurcharge * factor;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod + colorSurcharge;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal({}) }));
  }, [config, calculateTotal]);

  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  const handleFinalizeOrder = () => {
    const deposit = state.totalPrice / 2;
    const colorNames = state.cakeColors.map(hex => 
        config.colors.find(c => c.hex === hex)?.name || 'Especial'
    ).join(', ');

    const detailedInfo = `Pastel ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType}). 
      Sabor: ${state.selectedFlavor?.name}. Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}. 
      Estilo: ${config.decorations[state.selectedDecoration].label} (${colorNames}). 
      Extras: ${state.topperType !== 'none' ? 'Topper '+state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}. 
      Evento: ${state.theme} p/ ${state.birthdayName}. 
      Entrega: ${state.deliveryMethod} - ${state.deliveryDate} ${state.deliveryTime}. 
      Pago Ref: ${state.paymentReference}`;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      date: new Date().toLocaleString(),
      customerName: state.birthdayName || 'Cliente Web',
      details: detailedInfo,
      total: state.totalPrice,
      status: 'PENDING'
    };

    const updatedOrders = [newOrder, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem('cake_app_orders', JSON.stringify(updatedOrders));

    const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂 (Ref: ${newOrder.id})

📍 *TAMAÑO Y COBERTURA*
- Diámetro: ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType === 'TALL' ? 'Alto' : 'Bajo'})
- Cobertura: ${state.coverageType.toUpperCase()}
- Capacidad: ${state.selectedSize?.portions}

🍰 *SABORES*
- Bizcocho: ${state.selectedFlavor?.name}
- Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}
- Estilo: ${config.decorations[state.selectedDecoration].label}
- Colores: ${colorNames}

✨ *DECORACIÓN EXTRA*
- Topper: ${state.topperType}
- Esferas: ${state.hasSpheres ? 'Sí' : 'No'}

🎉 *DATOS DEL EVENTO*
- Temática: ${state.theme}
- Para: ${state.birthdayName} (${state.birthdayAge} años)
- Método: ${state.deliveryMethod}
- Fecha: ${state.deliveryDate} @ ${state.deliveryTime}

💰 *PAGO*
- Total: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Referencia: ${state.paymentReference}
- Monto en Bs: ${state.amountBs}`;

    const whatsappNumber = config.appTheme.whatsappNumber;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

    setState(prev => ({
      ...prev,
      step: 'SIZE',
      theme: '',
      birthdayName: '',
      birthdayAge: '',
      paymentReference: '',
      amountBs: '',
      referenceImage: null
    }));
  };

  const goToAdminLogin = () => setState(prev => ({ ...prev, step: 'ADMIN_LOGIN' }));
  const exitAdmin = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden">
        {state.step === 'SIZE' && (
          <SizeStep 
            selectedSize={state.selectedSize} 
            onSelectSize={(s) => setState(prev => ({ ...prev, selectedSize: s, totalPrice: calculateTotal({ selectedSize: s }) }))} 
            onNext={nextStep} 
            onAdminClick={goToAdminLogin}
            config={config}
          />
        )}
        {state.step === 'FLAVOR' && (
          <FlavorStep 
            {...state} 
            onSelectFlavor={(f) => setState(prev => ({ ...prev, selectedFlavor: f, totalPrice: calculateTotal({ selectedFlavor: f }) }))} 
            onSelectFilling={(fill) => setState(prev => ({ ...prev, selectedFilling: fill, totalPrice: calculateTotal({ selectedFilling: fill }) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            onCustomFlavorChange={(v) => setState(s => ({...s, customFlavor: v}))} 
            onCustomFillingChange={(v) => setState(s => ({...s, customFilling: v}))} 
            config={config}
          />
        )}
        {state.step === 'DECORATION' && (
          <DecorationStep 
            {...state} 
            onUpdateDecoration={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            config={config}
          />
        )}
        {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} onNext={nextStep} onBack={prevStep} />}
        {state.step === 'SUMMARY' && <SummaryStep appState={state} onBack={prevStep} onConfirm={nextStep} config={config} />}
        {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={(d) => setState(s => ({...s, ...d}))} onBack={prevStep} onComplete={handleFinalizeOrder} />}

        {state.step === 'ADMIN_LOGIN' && (
          <AdminLogin 
            onLoginSuccess={() => setState(prev => ({ ...prev, step: 'ADMIN_PANEL' }))} 
            onCancel={exitAdmin} 
          />
        )}

        {state.step === 'ADMIN_PANEL' && (
          <AdminPanel 
            config={config} 
            onUpdateConfig={setConfig} 
            orders={orders}
            onClearOrders={() => setOrders([])}
            onExit={exitAdmin} 
          />
        )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, CakeColor, DecorationStyle, TopperType, CoverageType, PaymentDetails, AppTheme } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');

  const handleTextureUpload = (id: string, type: 'flavor' | 'filling', file: File | null) => {
    if (!file) {
      if (type === 'flavor') updateFlavor(id, 'textureUrl', undefined);
      else updateFilling(id, 'textureUrl', undefined);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      if (type === 'flavor') updateFlavor(id, 'textureUrl', reader.result as string);
      else updateFilling(id, 'textureUrl', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const updateSize = (id: string, field: keyof CakeSize, value: any) => {
    const newSizes = config.sizes.map(s => s.id === id ? { ...s, [field]: value } : s);
    onUpdateConfig({ ...config, sizes: newSizes });
  };

  const addSize = () => {
    const newSize: CakeSize = { id: `new_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porciones', basePrice: 20, costMultiplier: 1.0 };
    onUpdateConfig({ ...config, sizes: [...config.sizes, newSize] });
  };

  const removeSize = (id: string) => {
    onUpdateConfig({ ...config, sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, field: keyof Flavor, value: any) => {
    const newFlavors = config.flavors.map(f => f.id === id ? { ...f, [field]: value } : f);
    onUpdateConfig({ ...config, flavors: newFlavors });
  };

  const addFlavor = () => {
    const newFlavor: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo Sabor', color: '#FFFFFF', priceModifier: 0 };
    onUpdateConfig({ ...config, flavors: [...config.flavors, newFlavor] });
  };

  const removeFlavor = (id: string) => {
    onUpdateConfig({ ...config, flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, field: keyof Filling, value: any) => {
    const newFillings = config.fillings.map(f => f.id === id ? { ...f, [field]: value } : f);
    onUpdateConfig({ ...config, fillings: newFillings });
  };

  const addFilling = () => {
    const newFilling: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo Relleno', color: '#FFFFFF', priceModifier: 0 };
    onUpdateConfig({ ...config, fillings: [...config.fillings, newFilling] });
  };

  const removeFilling = (id: string) => {
    onUpdateConfig({ ...config, fillings: config.fillings.filter(f => f.id !== id) });
  };

  const updateColor = (index: number, field: keyof CakeColor, value: any) => {
    const newColors = [...config.colors];
    newColors[index] = { ...newColors[index], [field]: value };
    onUpdateConfig({ ...config, colors: newColors });
  };

  const addColor = () => {
    onUpdateConfig({ ...config, colors: [...config.colors, { name: 'Nuevo', hex: '#000000', isSaturated: false }] });
  };

  const removeColor = (index: number) => {
    const newColors = config.colors.filter((_, i) => i !== index);
    onUpdateConfig({ ...config, colors: newColors });
  }

  const updateDecoration = (styleId: DecorationStyle, field: keyof any, value: any) => {
    const newDecors = { ...config.decorations };
    newDecors[styleId] = { ...newDecors[styleId], [field]: value };
    onUpdateConfig({ ...config, decorations: newDecors });
  };

  const updateNestedPrice = (parent: 'topperPrices' | 'coverageSurcharges', key: string, value: number) => {
    onUpdateConfig({ ...config, [parent]: { ...config[parent], [key]: value } });
  };

  const updatePaymentDetails = (field: keyof PaymentDetails, value: string) => {
    onUpdateConfig({ ...config, paymentDetails: { ...config.paymentDetails, [field]: value } });
  };

  const updateTheme = (field: keyof AppTheme, value: string) => {
    onUpdateConfig({ ...config, appTheme: { ...config.appTheme, [field]: value } });
  };

  return (
    <div className="flex flex-col h-full bg-slate-300 overflow-hidden font-quicksand">
