                             </div>
                          </div>
                       </div>
                       <div className="text-center md:text-right shrink-0 bg-slate-50 p-10 rounded-[3.5rem] w-full border-[6px] border-black shadow-inner flex flex-col md:flex-row items-center justify-between gap-8">
