                      <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Entidad Bancaria</label>
                        <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-800" value={config.paymentDetails.bankName} onChange={(e) => updatePaymentField('bankName', e.target.value)} />
                      </div>
                      <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Titular de Cuenta</label>
                        <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-800" value={config.paymentDetails.accountHolder} onChange={(e) => updatePaymentField('accountHolder', e.target.value)} />
                      </div>
                      <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase ml-1">RIF / ID Fiscal</label>
                        <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-800" value={config.paymentDetails.taxId} onChange={(e) => updatePaymentField('taxId', e.target.value)} />
                      </div>
                    </div>

                    <div className="space-y-6">
                      <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Zelle o Email de Pago</label>
                        <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-primary" value={config.paymentDetails.zelleEmail} onChange={(e) => updatePaymentField('zelleEmail', e.target.value)} />
                      </div>
                      <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Nota de Tasa de Cambio</label>
                        <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-600 h-32 resize-none" value={config.paymentDetails.exchangeRateNote} onChange={(e) => updatePaymentField('exchangeRateNote', e.target.value)} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* TAB: TEMA / CONFIG */}
            {activeTab === 'SETTINGS' && (
              <div className="space-y-10">
                <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm max-w-4xl space-y-10">
                  <section>
                    <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6 border-b border-slate-100 pb-2">Información de Marca</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                       <div className="flex flex-col gap-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Nombre Comercial</label>
                          <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-800" value={config.appTheme.brandName} onChange={(e) => updateThemeField('brandName', e.target.value)} />
                       </div>
                       <div className="flex flex-col gap-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-1">WhatsApp de Recepción</label>
                          <input type="text" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 font-bold text-slate-800" value={config.appTheme.whatsappNumber} onChange={(e) => updateThemeField('whatsappNumber', e.target.value)} />
                       </div>
                    </div>
                  </section>

                  <section>
                    <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6 border-b border-slate-100 pb-2">Colores del Sistema</h4>
                    <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                      {[
                        { id: 'primaryColor', label: 'Primario' },
                        { id: 'secondaryColor', label: 'Secundario' },
                        { id: 'backgroundColor', label: 'Fondo' },
                        { id: 'surfaceColor', label: 'Superficie' },
                        { id: 'textColor', label: 'Texto' },
                      ].map(item => (
                        <div key={item.id} className="flex flex-col items-center gap-3">
                           <div className="w-16 h-16 rounded-2xl border-4 border-white shadow-lg relative overflow-hidden" style={{ backgroundColor: (config.appTheme as any)[item.id] }}>
                              <input type="color" className="absolute inset-0 opacity-0 cursor-pointer" value={(config.appTheme as any)[item.id]} onChange={(e) => updateThemeField(item.id as any, e.target.value)} />
                           </div>
                           <span className="text-[9px] font-black uppercase text-slate-500">{item.label}</span>
                        </div>
                      ))}
                    </div>
                  </section>
                </div>
              </div>
            )}

            {/* Otras pestañas (COLORS, DECORATIONS, PRICES) mantienen lógica similar... */}
            {activeTab === 'COLORS' && (
               <div className="space-y-8">
                  <div className="grid grid-cols-2 md:grid-cols-6 gap-6">
                     {config.colors.map((c, i) => (
                        <div key={i} className="bg-white p-4 rounded-2xl border border-slate-200 flex flex-col items-center gap-4">
                           <div className="w-12 h-12 rounded-full border-2 border-slate-100 shadow-inner" style={{backgroundColor: c.hex}}></div>
                           <input type="text" className="w-full text-center text-[10px] font-black uppercase bg-slate-50 border-none rounded-md" value={c.name} onChange={(e) => {
                              const nc = [...config.colors];
                              nc[i].name = e.target.value;
                              updateConfig({colors: nc});
                           }} />
                        </div>
                     ))}
                  </div>
               </div>
            )}

            {activeTab === 'PRICES' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm space-y-6">
                  <h4 className="font-black text-slate-800 uppercase text-xs mb-4">Toppers</h4>
                  {Object.entries(config.topperPrices).map(([k, v]) => (
                    <div key={k} className="flex justify-between items-center">
                      <span className="text-sm font-bold text-slate-600 uppercase">{k}</span>
                      <input type="number" className="w-20 bg-slate-50 border-none rounded-lg p-2 text-right font-bold text-primary" value={v} onChange={(e) => {
                        updateConfig({ topperPrices: { ...config.topperPrices, [k]: parseFloat(e.target.value) } });
                      }} />
                    </div>
                  ))}
                </div>
              </div>
            )}

          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

{
  "name": "cake-customizer-studio",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.7.2",
    "vite": "^6.0.5"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  build: {
    outDir: 'dist',
  },
  server: {
    port: 3000,
  }
});

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('cake_app_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.appTheme || !parsed.appTheme.primaryColor) {
        parsed.appTheme = {
          ...parsed.appTheme,
          brandName: parsed.appTheme?.brandName || "Cake Customizer Studio",
          whatsappNumber: parsed.appTheme?.whatsappNumber || "584241546473",
          primaryColor: "#E31C58",
          secondaryColor: "#FFEB3B",
          backgroundColor: "#FFFBF2",
          textColor: "#000000",
          surfaceColor: "#FFFFFF"
        };
      }
      return parsed;
    }
    return {
      sizes: CAKE_SIZES,
      flavors: FLAVORS,
      fillings: FILLINGS,
      colors: CAKE_COLORS,
      decorations: DECORATIONS,
      topperPrices: TOPPER_PRICES,
      spheresPrice: SPHERES_PRICE,
      saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
      coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
      paymentDetails: {
        bankName: "Pastelitos Bank",
        accountHolder: "Cakes Studio S.A.",
        zelleEmail: "pagos@cakesstudio.com",
        taxId: "J-12345678-9",
        exchangeRateNote: "Trabajamos con Tasa Euro (€)"
      },
      appTheme: {
        brandName: "Cake Customizer Studio",
        whatsappNumber: "584241546473",
        primaryColor: "#E31C58",
        secondaryColor: "#FFEB3B",
        backgroundColor: "#FFFBF2",
        textColor: "#000000",
        surfaceColor: "#FFFFFF"
      }
    };
  });

  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('cake_app_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[0],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFlavor: '',
    customFilling: '',
  });

  useEffect(() => {
    localStorage.setItem('cake_app_config', JSON.stringify(config));
  }, [config]);

  useEffect(() => {
    localStorage.setItem('cake_app_orders', JSON.stringify(orders));
  }, [orders]);

  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    const size = partial.selectedSize || state.selectedSize;
    const flavor = partial.selectedFlavor || state.selectedFlavor;
    const filling = partial.selectedFilling || state.selectedFilling;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;
    const currentColors = partial.cakeColors || state.cakeColors;

    const factor = size?.costMultiplier || 1.0;

    const base = size?.basePrice || 0;
    const fMod = (flavor?.priceModifier || 0) * factor;
    const fillMod = (filling?.priceModifier || 0) * factor;
    const decorMod = (config.decorations[decorId]?.priceModifier || 0) * factor;
    const coverageMod = (config.coverageSurcharges[coverage] || 0) * factor;

    const topperMod = config.topperPrices[topper] || 0;
    const spheresMod = spheres ? (config.spheresPrice * factor) : 0;

    let colorSurcharge = 0;
    const hasSaturated = currentColors.some(hex => 
        config.colors.find(c => c.hex === hex)?.isSaturated
    );
    if (hasSaturated) colorSurcharge = config.saturatedColorSurcharge * factor;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod + colorSurcharge;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal({}) }));
  }, [config, calculateTotal]);

  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  const handleFinalizeOrder = () => {
    const deposit = state.totalPrice / 2;
    const colorNames = state.cakeColors.map(hex => 
        config.colors.find(c => c.hex === hex)?.name || 'Especial'
    ).join(', ');

    const detailedInfo = `Pastel ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType}). 
      Sabor: ${state.selectedFlavor?.name}. Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}. 
      Estilo: ${config.decorations[state.selectedDecoration].label} (${colorNames}). 
      Extras: ${state.topperType !== 'none' ? 'Topper '+state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}. 
      Evento: ${state.theme} p/ ${state.birthdayName}. 
      Entrega: ${state.deliveryMethod} - ${state.deliveryDate} ${state.deliveryTime}. 
      Pago Ref: ${state.paymentReference}`;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      date: new Date().toLocaleString(),
      customerName: state.birthdayName || 'Cliente Web',
      details: detailedInfo,
      total: state.totalPrice,
      status: 'PENDING'
    };

    const updatedOrders = [newOrder, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem('cake_app_orders', JSON.stringify(updatedOrders));

    const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂 (Ref: ${newOrder.id})

📍 *TAMAÑO Y COBERTURA*
- Diámetro: ${state.selectedSize?.diameter}cm (${state.selectedSize?.heightType === 'TALL' ? 'Alto' : 'Bajo'})
- Cobertura: ${state.coverageType.toUpperCase()}
- Capacidad: ${state.selectedSize?.portions}

🍰 *SABORES*
- Bizcocho: ${state.selectedFlavor?.name}
- Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}
- Estilo: ${config.decorations[state.selectedDecoration].label}
- Colores: ${colorNames}

✨ *DECORACIÓN EXTRA*
- Topper: ${state.topperType}
- Esferas: ${state.hasSpheres ? 'Sí' : 'No'}

🎉 *DATOS DEL EVENTO*
- Temática: ${state.theme}
- Para: ${state.birthdayName} (${state.birthdayAge} años)
- Método: ${state.deliveryMethod}
- Fecha: ${state.deliveryDate} @ ${state.deliveryTime}

💰 *PAGO*
- Total: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Referencia: ${state.paymentReference}
- Monto en Bs: ${state.amountBs}`;

    const whatsappNumber = config.appTheme.whatsappNumber;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

    setState(prev => ({
      ...prev,
      step: 'SIZE',
      theme: '',
      birthdayName: '',
      birthdayAge: '',
      paymentReference: '',
      amountBs: '',
      referenceImage: null
    }));
  };

  const goToAdminLogin = () => setState(prev => ({ ...prev, step: 'ADMIN_LOGIN' }));
  const exitAdmin = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden">
        {state.step === 'SIZE' && (
          <SizeStep 
            selectedSize={state.selectedSize} 
            onSelectSize={(s) => setState(prev => ({ ...prev, selectedSize: s, totalPrice: calculateTotal({ selectedSize: s }) }))} 
            onNext={nextStep} 
            onAdminClick={goToAdminLogin}
            config={config}
          />
        )}
        {state.step === 'FLAVOR' && (
          <FlavorStep 
            {...state} 
            onSelectFlavor={(f) => setState(prev => ({ ...prev, selectedFlavor: f, totalPrice: calculateTotal({ selectedFlavor: f }) }))} 
            onSelectFilling={(fill) => setState(prev => ({ ...prev, selectedFilling: fill, totalPrice: calculateTotal({ selectedFilling: fill }) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            onCustomFlavorChange={(v) => setState(s => ({...s, customFlavor: v}))} 
            onCustomFillingChange={(v) => setState(s => ({...s, customFilling: v}))} 
            config={config}
          />
        )}
        {state.step === 'DECORATION' && (
          <DecorationStep 
            {...state} 
            onUpdateDecoration={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} 
            onNext={nextStep} 
            onBack={prevStep} 
            config={config}
          />
        )}
        {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} onNext={nextStep} onBack={prevStep} />}
        {state.step === 'SUMMARY' && <SummaryStep appState={state} onBack={prevStep} onConfirm={nextStep} config={config} />}
        {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={(d) => setState(s => ({...s, ...d}))} onBack={prevStep} onComplete={handleFinalizeOrder} />}

        {state.step === 'ADMIN_LOGIN' && (
          <AdminLogin 
            onLoginSuccess={() => setState(prev => ({ ...prev, step: 'ADMIN_PANEL' }))} 
            onCancel={exitAdmin} 
          />
        )}

        {state.step === 'ADMIN_PANEL' && (
          <AdminPanel 
            config={config} 
            onUpdateConfig={setConfig} 
            orders={orders}
            onClearOrders={() => setOrders([])}
            onExit={exitAdmin} 
          />
        )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, PaymentDetails, AppTheme } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');

  // Helpers de actualización
  const updateConfig = (newPart: Partial<AppConfig>) => {
    onUpdateConfig({ ...config, ...newPart });
  };

  const updateSize = (id: string, field: keyof CakeSize, value: any) => {
    const newSizes = config.sizes.map(s => s.id === id ? { ...s, [field]: value } : s);
    updateConfig({ sizes: newSizes });
  };

  const addSize = () => {
    const newSize: CakeSize = { id: `new_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porciones', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, newSize] });
  };

  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, field: keyof Flavor, value: any) => {
    const newFlavors = config.flavors.map(f => f.id === id ? { ...f, [field]: value } : f);
    updateConfig({ flavors: newFlavors });
  };

  const addFlavor = () => {
    const newFlavor: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo Bizcocho', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, newFlavor] });
  };

  const removeFlavor = (id: string) => {
    updateConfig({ flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, field: keyof Filling, value: any) => {
    const newFillings = config.fillings.map(f => f.id === id ? { ...f, [field]: value } : f);
    updateConfig({ fillings: newFillings });
  };

  const addFilling = () => {
    const newFilling: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo Relleno', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, newFilling] });
  };

  const removeFilling = (id: string) => {
    updateConfig({ fillings: config.fillings.filter(f => f.id !== id) });
  };

  const updatePaymentField = (field: keyof PaymentDetails, value: string) => {
    updateConfig({ paymentDetails: { ...config.paymentDetails, [field]: value } });
  };

  const updateThemeField = (field: keyof AppTheme, value: string) => {
    updateConfig({ appTheme: { ...config.appTheme, [field]: value } });
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Pedidos / Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes y Tamaños', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores y Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos de Decoración', icon: 'auto_fix_high' },
    { id: 'COLORS', label: 'Paleta de Colores', icon: 'palette' },
    { id: 'PRICES', label: 'Precios Extras', icon: 'payments' },
    { id: 'PAYMENTS', label: 'Datos Bancarios', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca y Tema', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-quicksand">

      {/* SIDEBAR NAVIGATION */}
      <aside className="w-80 bg-slate-900 flex flex-col shrink-0 shadow-2xl z-20">
        <div className="p-8 border-b border-slate-800">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-12 h-12 bg-primary rounded-xl flex items-center justify-center text-white shadow-lg">
              <span className="material-icons-round">dashboard</span>
            </div>
            <h1 className="text-xl font-display text-white tracking-tight uppercase">Admin Panel</h1>
          </div>
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{config.appTheme.brandName}</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all group ${activeTab === item.id ? 'bg-primary text-white shadow-xl scale-[1.02]' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
            >
              <span className="material-icons-round text-2xl">{item.icon}</span>
              <span className="text-sm font-bold uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-800">
          <button 
            onClick={onExit}
            className="w-full bg-slate-800 text-white font-black py-4 rounded-xl hover:bg-red-600 transition-all flex items-center justify-center gap-2 text-xs uppercase tracking-widest"
          >
            <span className="material-icons-round text-sm">logout</span> Salir del Panel
          </button>
        </div>
      </aside>

