                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {config.sizes.map(s => (
                    <div key={s.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 relative group">
