                  )}
                </div>
                <span className="text-[10px] font-black uppercase text-center text-black leading-tight">{filling.name}</span>
              </label>
            ))}
          </div>

          {isFillingOthersSelected && (
            <div className="mt-5 animate-pop">
              <input 
