        </div>
      </main>

      {/* FOOTER */}
      <footer className="bg-surface-light p-6 md:p-10 z-50 shadow-[0_-20px_40px_rgba(0,0,0,0.04)] rounded-t-[3rem] md:rounded-t-[4rem] border-t border-gray-100 shrink-0">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-6 md:gap-10">
          <div className="flex flex-wrap justify-center md:justify-start items-center gap-8 md:gap-12">
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[10px] md:text-[11px] text-gray-400 font-black uppercase tracking-[0.2em] mb-1">Seleccionado</span>
              <div className="flex items-baseline justify-center md:justify-start gap-3">
                <span className="text-3xl md:text-4xl font-display text-black">{currentDiameter}cm</span>
                <span className="text-[10px] md:text-[12px] font-black text-primary uppercase bg-primary/5 px-4 md:px-5 py-1 rounded-xl border border-primary/10">
                  {currentCakeData?.portions || 'N/A'}
                </span>
              </div>
