                    <span className="text-xs md:text-xl font-black text-black uppercase tracking-tight md:tracking-widest leading-none mb-1 md:mb-2">Esferas Decorativas</span>
                    <span className="text-[9px] md:text-sm font-black text-primary uppercase bg-primary/10 px-2 md:px-4 py-0.5 md:py-1 rounded-full border border-primary/10 w-fit">+$8.00</span>
                  </div>
               </div>
               <button 
                  onClick={() => onUpdateDecoration({ hasSpheres: !hasSpheres })}
                  className={`w-14 h-8 md:w-24 md:h-12 rounded-full relative flex items-center px-1 md:px-2 transition-all shadow-inner border border-gray-100 ${hasSpheres ? 'bg-primary' : 'bg-gray-200'}`}
               >
                  <div className={`w-5 h-5 md:w-8 md:h-8 rounded-full bg-white shadow-xl transform transition-transform duration-500 ${hasSpheres ? 'translate-x-6 md:translate-x-10' : 'translate-x-0'}`}></div>
               </button>
            </div>
          </section>
        </div>
      </main>

      {/* FOOTER - Bordes suavizados */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white p-4 md:p-10 z-50 shadow-[0_-15px_40px_rgba(0,0,0,0.06)] border-t border-gray-100 rounded-t-[2.5rem] md:rounded-none">
        <div className="max-w-5xl mx-auto flex items-center justify-between gap-4 md:gap-10">
          <div className="flex flex-col">
            <span className="text-[10px] md:text-[14px] font-black text-gray-400 uppercase tracking-widest">Total Estimado</span>
            <div className="text-2xl md:text-6xl font-display text-black tracking-tighter">${totalPrice.toFixed(2)}</div>
          </div>
          <button 
            onClick={onNext}
            className="flex-1 bg-primary text-white font-black py-4 md:py-7 px-6 md:px-14 rounded-full shadow-xl-primary transition-all text-[10px] md:text-sm uppercase tracking-[0.2em] md:tracking-[0.4em] flex items-center justify-center gap-2 md:gap-8 border-2 border-white/20 active:scale-95"
          >
            Siguiente
            <span className="material-icons-round text-lg md:text-3xl">arrow_forward</span>
          </button>
        </div>
      </footer>
    </div>
  );
};

