        <div className="inline-block bg-primary px-8 py-2 rounded-[2rem] shadow-xl transform -rotate-1 animate-pop border-2 md:border-4 border-white">
          <h1 className="text-xl font-display font-bold text-white tracking-widest uppercase">SABORES</h1>
        </div>
      </header>

      <main className="flex-1 px-6 relative z-10 overflow-y-auto no-scrollbar pb-10">
        <section className="mb-8">
          <h2 className="text-[10px] md:text-xs font-black text-black uppercase tracking-widest mb-4">1. Sabor de Ponqué</h2>
          <div className="grid grid-cols-3 gap-3">
            {config.flavors.map(flavor => (
              <label key={flavor.id} className="cursor-pointer group">
                <input type="radio" className="sr-only" checked={selectedFlavor?.id === flavor.id} onChange={() => onSelectFlavor(flavor)} />
                <div className={`flex flex-col items-center p-3 md:p-4 rounded-[1.5rem] md:rounded-[2rem] shadow-soft border-2 transition-all ${selectedFlavor?.id === flavor.id ? 'border-primary bg-white scale-105' : 'border-gray-200 bg-white/80'}`}>
                  <div className="w-12 h-12 md:w-14 md:h-14 rounded-2xl mb-2 overflow-hidden shadow-inner border border-black/5" style={{ backgroundColor: flavor.textureUrl ? undefined : flavor.color }}>
                    {flavor.textureUrl ? (
                      <img src={flavor.textureUrl} className="w-full h-full object-cover" />
