                      <div className={`w-full h-full ${flavor.pattern || ''}`} />
                    )}
                  </div>
                  <span className="text-[9px] md:text-[11px] font-black uppercase tracking-tight text-center text-black">{flavor.name}</span>
                </div>
              </label>
            ))}
