        </section>

        <section className="mb-8">
          <h2 className="text-[10px] md:text-xs font-black text-black uppercase tracking-widest mb-4">2. Rellenos</h2>
          <div className="grid grid-cols-4 gap-3">
            {config.fillings.map(filling => (
              <label key={filling.id} className="cursor-pointer group flex flex-col items-center gap-1.5">
                <input type="radio" className="sr-only" checked={selectedFilling?.id === filling.id} onChange={() => onSelectFilling(filling)} />
                <div className={`w-12 h-12 md:w-14 md:h-14 rounded-full border-2 md:border-4 shadow-md transition-all overflow-hidden ${selectedFilling?.id === filling.id ? 'border-primary scale-110' : 'border-gray-100 bg-white'}`} style={{ backgroundColor: filling.textureUrl ? undefined : filling.color }}>
                  {filling.textureUrl ? (
                    <img src={filling.textureUrl} className="w-full h-full object-cover" />
