                    <div className={`w-full h-full flex items-center justify-center ${filling.pattern || ''}`}>
                      {filling.id === 'others' && <span className="material-icons-round text-black text-lg">edit_note</span>}
                    </div>
                  )}
                </div>
                <span className="text-[8px] md:text-[10px] font-black uppercase text-center text-black leading-tight">{filling.name}</span>
              </label>
            ))}
          </div>

          {isFillingOthersSelected && (
            <div className="mt-4 animate-pop">
              <input 
                type="text" 
                placeholder="¿Qué relleno deseas?"
                className="w-full bg-white border-2 border-primary/20 rounded-2xl p-3 text-xs md:text-sm font-bold text-black shadow-soft outline-none"
                value={customFilling}
                onChange={(e) => onCustomFillingChange(e.target.value)}
