        <section className="bg-white rounded-[2rem] md:rounded-[3rem] p-6 shadow-xl border border-rose-50 overflow-hidden relative mb-10 text-center">
            <h2 className="text-sm md:text-lg font-display font-bold text-primary uppercase mb-4">Vista de Capas</h2>
