      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter || '?'}cm (${state.selectedSize?.heightType})
🍰 Bizcocho: ${state.selectedFlavor?.name || 'Vainilla'}
🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : (state.selectedFilling?.name || 'Clásico')}
✨ Estilo: ${decorLabel}
🎨 Colores: ${colorNames}
🎯 Cobertura: ${state.coverageType.toUpperCase()}
🚀 Extras: ${state.topperType !== 'none' ? 'Topper '+state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}
🎉 Evento: ${state.theme} p/ ${state.birthdayName} (${state.birthdayAge} años)
📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate} ${state.deliveryTime}
${paymentInfo}`;

      const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();
      const newOrder: Order = {
        id: simpleId,
        date: new Date().toLocaleString(),
        customerName: state.birthdayName || 'Cliente Web',
        details: detailedInfo,
        total: state.totalPrice,
        status: 'PENDING'
      };

      // 2. OPEN WHATSAPP IMMEDIATELY (Before Async Operations)
      // This prevents popup blockers on mobile
      const paymentSummary = state.paymentStrategy === 'FIFTY_PERCENT'
        ? `💰 *RESUMEN DE PAGO*
- Total: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Pendiente: $${deposit.toFixed(2)}`
        : `💰 *RESUMEN DE PAGO*
- Total a pagar al recibir: $${state.totalPrice.toFixed(2)}`;

      const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂 (Ref: ${newOrder.id})

${detailedInfo}

${paymentSummary}`;

      const whatsappNumber = config.appTheme.whatsappNumber;
      // Using window.open allows saving the tab reference, but on mobile sometimes works better as a direct location change if not in an async callback
      // Since we are synchronous here (before any await), window.open should work fine.
      window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

      // 3. UPDATE STATE AND STORAGE
      setOrders(prev => [newOrder, ...prev]);

      // Save locally as backup immediately
      try {
        const currentStored = JSON.parse(localStorage.getItem('cake_app_orders') || '[]');
        localStorage.setItem('cake_app_orders', JSON.stringify([newOrder, ...currentStored]));
      } catch (e) {
        console.error("Local storage save error", e);
      }

      // 4. FIREBASE SAVE (Async - Background)
      if (db) {
        addDoc(collection(db, "orders"), newOrder).catch(e => {
          console.error("Error saving order to cloud", e);
          // Note: We don't alert the user here as they have already been redirected to WhatsApp
          // and the local storage backup exists.
        });
      }

      // 5. NAVIGATE TO SUCCESS
      setState(prev => ({
        ...prev,
        step: 'SUCCESS',
        lastOrderId: newOrder.id,
      }));

    } catch (error) {
      console.error("Critical error in finalize order:", error);
      alert("Hubo un error inesperado creando el pedido. Por favor verifica los datos e intenta de nuevo.");
    }
  };

  const resetToStart = () => setState(prev => ({ ...prev, step: 'SIZE' }));
  const goToAdminLogin = () => setState(prev => ({ ...prev, step: 'ADMIN_LOGIN' }));
  const exitAdmin = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  const showBrandHeader = !['ADMIN_PANEL'].includes(state.step);

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {/* GLOBAL PERSISTENT BRAND HEADER */}
        {showBrandHeader && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
            <div className="max-w-7xl w-full flex items-center justify-center">
               {config.appTheme.logoUrl ? (
                <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" />
              ) : (
                <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">
                  MATH <span className="text-secondary">CAKE</span>
                </h2>
              )}
            </div>
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
          <div className="flex-1 overflow-hidden mx-auto w-full h-full max-w-7xl">
            {state.step === 'SIZE' && (
              <SizeStep 
                selectedSize={state.selectedSize} 
                onSelectSize={(s) => setState(prev => ({ ...prev, selectedSize: s, totalPrice: calculateTotal({ selectedSize: s }) }))} 
                onNext={nextStep} 
                onAdminClick={goToAdminLogin}
                config={config}
              />
            )}
            {state.step === 'FLAVOR' && (
              <FlavorStep 
                {...state} 
                onSelectFlavor={(f) => setState(prev => ({ ...prev, selectedFlavor: f, totalPrice: calculateTotal({ selectedFlavor: f }) }))} 
                onSelectFilling={(fill) => setState(prev => ({ ...prev, selectedFilling: fill, totalPrice: calculateTotal({ selectedFilling: fill }) }))} 
                onNext={nextStep} 
                onBack={prevStep} 
                onCustomFillingChange={(v) => setState(s => ({...s, customFilling: v}))} 
                config={config}
              />
            )}
            {state.step === 'DECORATION' && (
              <DecorationStep 
                {...state} 
                onUpdateDecoration={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} 
                onNext={nextStep} 
                onBack={prevStep} 
                config={config}
              />
            )}
            {state.step === 'PERSONALIZATION' && (
              <PersonalizationStep 
                appState={state} 
                onUpdate={(d) => setState(prev => ({ ...prev, ...d, totalPrice: calculateTotal(d) }))} 
                onNext={nextStep} 
                onBack={prevStep} 
              />
            )}
            {state.step === 'SUMMARY' && (
              <SummaryStep 
                appState={state} 
                onUpdate={(d) => setState(prev => ({ ...prev, ...d }))} 
                onBack={prevStep} 
                onConfirm={nextStep} 
                config={config} 
              />
            )}
            {state.step === 'PAYMENT' && (
              <PaymentStep 
                {...state} 
                config={config} 
                onUpdatePayment={(d) => setState(s => ({...s, ...d}))} 
                onBack={prevStep} 
                onComplete={handleFinalizeOrder} 
              />
            )}

            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={resetToStart} config={config} />}

            {state.step === 'ADMIN_LOGIN' && (
              <AdminLogin 
                onLoginSuccess={() => setState(prev => ({ ...prev, step: 'ADMIN_PANEL' }))} 
                onCancel={exitAdmin} 
              />
            )}
          </div>

          {state.step === 'ADMIN_PANEL' && (
            <div className="fixed inset-0 z-[100]">
              <AdminPanel 
                config={config} 
                onUpdateConfig={handleUpdateConfig} 
                orders={orders}
                onClearOrders={handleClearOrders}
                onExit={exitAdmin} 
              />
            </div>
          )}
        </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import SuccessStep from './components/SuccessStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

// Firebase imports
import { db } from './firebase';
import { collection, onSnapshot, doc, setDoc, addDoc } from 'firebase/firestore';

const DEFAULT_CONFIG: AppConfig = {
  sizes: CAKE_SIZES,
  flavors: FLAVORS,
  fillings: FILLINGS,
  colors: CAKE_COLORS,
  decorations: DECORATIONS,
  topperPrices: TOPPER_PRICES,
  spheresPrice: SPHERES_PRICE,
  saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
  coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
  paymentDetails: {
    bankName: "Pastelitos Bank",
    accountHolder: "Cakes Studio S.A.",
    zelleEmail: "pagos@cakesstudio.com",
    taxId: "J-12345678-9",
    exchangeRateNote: "Trabajamos con Tasa Euro (€)"
  },
  appTheme: {
    brandName: "Cake Customizer Studio",
    whatsappNumber: "584241546473",
    primaryColor: "#E31C58",
    secondaryColor: "#FFEB3B",
    backgroundColor: "#FFFBF2",
    textColor: "#000000",
    surfaceColor: "#FFFFFF"
  }
};

const App: React.FC = () => {
  // --- CONFIGURATION STATE ---
  const [config, setConfig] = useState<AppConfig>(() => {
    const saved = localStorage.getItem('cake_app_config');
    if (saved) {
      return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
    }
    return DEFAULT_CONFIG;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('cake_app_orders');
    return saved ? JSON.parse(saved) : [];
  });

  // --- FIREBASE SYNC ---
  useEffect(() => {
    if (!db) return;

    const unsubscribeConfig = onSnapshot(doc(db, "settings", "appConfig"), (docSnap) => {
      if (docSnap.exists()) {
        const remoteConfig = docSnap.data() as AppConfig;
        const merged = { ...DEFAULT_CONFIG, ...remoteConfig };
        setConfig(merged);
        localStorage.setItem('cake_app_config', JSON.stringify(merged));
      } else {
        setDoc(doc(db, "settings", "appConfig"), config);
      }
    });

    const unsubscribeOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      const remoteOrders: Order[] = [];
      snapshot.forEach((doc) => {
        remoteOrders.push({ ...doc.data(), id: doc.id } as Order);
      });
      remoteOrders.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setOrders(remoteOrders);
      localStorage.setItem('cake_app_orders', JSON.stringify(remoteOrders));
    });

    return () => {
      unsubscribeConfig();
      unsubscribeOrders();
    };
  }, []);

  // --- THEME ---
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  // --- APP STATE ---
  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[1],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFilling: '',
    paymentStrategy: 'FIFTY_PERCENT',
  });

  // --- CALCULAR TOTAL USANDO SIEMPRE LA DATA DE CONFIG (FIREBASE) ---
  const calculateTotal = useCallback((partial: Partial<AppState>) => {
    // Tomar IDs de la selección actual o del cambio parcial
    const sizeId = partial.selectedSize?.id || state.selectedSize?.id;
    const flavorId = partial.selectedFlavor?.id || state.selectedFlavor?.id;
    const fillingId = partial.selectedFilling?.id || state.selectedFilling?.id;
    const decorId = partial.selectedDecoration || state.selectedDecoration;
    const coverage = partial.coverageType || state.coverageType;
    const topper = partial.topperType || state.topperType;
    const spheres = partial.hasSpheres !== undefined ? partial.hasSpheres : state.hasSpheres;
    const currentColors = partial.cakeColors || state.cakeColors;

    // Buscar los objetos frescos en el config actual
    const size = config.sizes.find(s => s.id === sizeId) || config.sizes[0];
    const flavor = config.flavors.find(f => f.id === flavorId) || config.flavors[0];
    const filling = config.fillings.find(f => f.id === fillingId) || config.fillings[0];
    const decor = config.decorations[decorId] || { priceModifier: 0 };

    const factor = size.costMultiplier || 1.0;

    // Sumar componentes
    const base = size.basePrice || 0;
    const fMod = (flavor.priceModifier || 0) * factor;
    const fillMod = (filling.priceModifier || 0) * factor;
    const decorMod = (decor.priceModifier || 0) * factor;
    const coverageMod = (config.coverageSurcharges[coverage] || 0) * factor;
    const topperMod = config.topperPrices[topper] || 0;
    const spheresMod = spheres ? (config.spheresPrice * factor) : 0;

    // Recargo por colores saturados
    let colorSurcharge = 0;
    const hasSaturated = currentColors.some(hex => 
        config.colors.find(c => c.hex === hex)?.isSaturated
    );
    if (hasSaturated) colorSurcharge = (config.saturatedColorSurcharge || 0) * factor;

    return base + fMod + fillMod + decorMod + coverageMod + topperMod + spheresMod + colorSurcharge;
  }, [state.selectedSize, state.selectedFlavor, state.selectedFilling, state.selectedDecoration, state.coverageType, state.topperType, state.hasSpheres, state.cakeColors, config]);

  // Recalcular cada vez que cambie algo relevante o llegue nueva config de Firebase
  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal({}) }));
  }, [config, calculateTotal]);

  const nextStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex < steps.length - 1) return { ...prev, step: steps[currentIndex + 1] };
      return prev;
    });
  };

  const prevStep = () => {
    setState(prev => {
      const steps: Step[] = ['SIZE', 'FLAVOR', 'DECORATION', 'PERSONALIZATION', 'SUMMARY', 'PAYMENT'];
      const currentIndex = steps.indexOf(prev.step);
      if (currentIndex > 0) return { ...prev, step: steps[currentIndex - 1] };
      return prev;
    });
  };

  const handleUpdateConfig = async (newConfig: AppConfig) => {
    setConfig(newConfig);
    localStorage.setItem('cake_app_config', JSON.stringify(newConfig));
    if (db) {
      try {
        await setDoc(doc(db, "settings", "appConfig"), newConfig);
      } catch (e) {
        console.error("Error saving config to Firebase", e);
      }
    }
  };

  const handleClearOrders = async () => {
     if(confirm("¿Estás seguro de borrar el historial?")) {
        setOrders([]);
        localStorage.setItem('cake_app_orders', JSON.stringify([]));
        alert("Pedidos locales borrados. En nube permanecen por seguridad.");
     }
  };

  const handleFinalizeOrder = async () => {
    try {
      const deposit = state.totalPrice / 2;
      const colorNames = state.cakeColors.map(hex => 
          config.colors.find(c => c.hex === hex)?.name || 'Especial'
      ).join(', ');

      const paymentInfo = state.paymentStrategy === 'FIFTY_PERCENT' 
        ? `💳 Pago: Anticipo 50% (Ref ${state.paymentReference} - Bs. ${state.amountBs})`
        : `💵 Pago: 100% Contra Entrega`;

      const decorLabel = config.decorations[state.selectedDecoration]?.label || 'Liso';

      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter || '?'}cm (${state.selectedSize?.heightType})
🍰 Bizcocho: ${state.selectedFlavor?.name || 'Vainilla'}
🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : (state.selectedFilling?.name || 'Clásico')}
✨ Estilo: ${decorLabel}
🎨 Colores: ${colorNames}
🎯 Cobertura: ${state.coverageType.toUpperCase()}
🚀 Extras: ${state.topperType !== 'none' ? 'Topper '+state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}
🎉 Evento: ${state.theme} p/ ${state.birthdayName} (${state.birthdayAge} años)
📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate} ${state.deliveryTime}
${paymentInfo}`;

      const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();
      const newOrder: Order = {
        id: simpleId,
        date: new Date().toLocaleString(),
        customerName: state.birthdayName || 'Cliente Web',
        details: detailedInfo,
        total: state.totalPrice,
        status: 'PENDING'
      };

      const paymentSummary = state.paymentStrategy === 'FIFTY_PERCENT'
        ? `💰 *RESUMEN DE PAGO*
- Total: $${state.totalPrice.toFixed(2)}
- Anticipo (50%): $${deposit.toFixed(2)}
- Pendiente: $${deposit.toFixed(2)}`
        : `💰 *RESUMEN DE PAGO*
- Total a pagar al recibir: $${state.totalPrice.toFixed(2)}`;

      const message = `🎂 *¡NUEVO PEDIDO DE PASTEL!* 🎂 (Ref: ${newOrder.id})

${detailedInfo}

${paymentSummary}`;

      window.open(`https://wa.me/${config.appTheme.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

      setOrders(prev => [newOrder, ...prev]);
      localStorage.setItem('cake_app_orders', JSON.stringify([newOrder, ...orders]));

      if (db) {
        addDoc(collection(db, "orders"), newOrder).catch(console.error);
      }

      setState(prev => ({
        ...prev,
        step: 'SUCCESS',
        lastOrderId: newOrder.id,
      }));

    } catch (error) {
      alert("Error creando pedido.");
    }
  };

  const resetToStart = () => setState(prev => ({ ...prev, step: 'SIZE' }));
  const goToAdminLogin = () => setState(prev => ({ ...prev, step: 'ADMIN_LOGIN' }));
  const exitAdmin = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  const showBrandHeader = !['ADMIN_PANEL'].includes(state.step);

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {showBrandHeader && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
            <div className="max-w-7xl w-full flex items-center justify-center">
               {config.appTheme.logoUrl ? (
                <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" />
              ) : (
                <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">
                  {config.appTheme.brandName}
                </h2>
              )}
            </div>
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
          <div className="flex-1 overflow-hidden mx-auto w-full h-full max-w-7xl">
            {state.step === 'SIZE' && (
              <SizeStep 
                selectedSize={state.selectedSize} 
                onSelectSize={(s) => setState(prev => ({ ...prev, selectedSize: s }))} 
                onNext={nextStep} 
                onAdminClick={goToAdminLogin}
                config={config}
              />
            )}
            {state.step === 'FLAVOR' && (
              <FlavorStep 
                {...state} 
                onSelectFlavor={(f) => setState(prev => ({ ...prev, selectedFlavor: f }))} 
                onSelectFilling={(fill) => setState(prev => ({ ...prev, selectedFilling: fill }))} 
                onNext={nextStep} 
                onBack={prevStep} 
                onCustomFillingChange={(v) => setState(s => ({...s, customFilling: v}))} 
                config={config}
              />
            )}
            {state.step === 'DECORATION' && (
              <DecorationStep 
                {...state} 
                onUpdateDecoration={(d) => setState(prev => ({ ...prev, ...d }))} 
                onNext={nextStep} 
                onBack={prevStep} 
                config={config}
              />
            )}
            {state.step === 'PERSONALIZATION' && (
              <PersonalizationStep 
                appState={state} 
                onUpdate={(d) => setState(prev => ({ ...prev, ...d }))} 
                onNext={nextStep} 
                onBack={prevStep} 
              />
            )}
            {state.step === 'SUMMARY' && (
              <SummaryStep 
                appState={state} 
                onUpdate={(d) => setState(prev => ({ ...prev, ...d }))} 
                onBack={prevStep} 
                onConfirm={nextStep} 
                config={config} 
              />
            )}
            {state.step === 'PAYMENT' && (
              <PaymentStep 
                {...state} 
                config={config} 
                onUpdatePayment={(d) => setState(s => ({...s, ...d}))} 
                onBack={prevStep} 
                onComplete={handleFinalizeOrder} 
              />
            )}

            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={resetToStart} config={config} />}

            {state.step === 'ADMIN_LOGIN' && (
              <AdminLogin 
                onLoginSuccess={() => setState(prev => ({ ...prev, step: 'ADMIN_PANEL' }))} 
                onCancel={exitAdmin} 
              />
            )}
          </div>

          {state.step === 'ADMIN_PANEL' && (
            <div className="fixed inset-0 z-[100]">
              <AdminPanel 
                config={config} 
                onUpdateConfig={handleUpdateConfig} 
                orders={orders}
                onClearOrders={handleClearOrders}
                onExit={exitAdmin} 
              />
            </div>
          )}
        </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, PaymentDetails, AppTheme, DecorationInfo } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    onUpdateConfig({ ...config, ...newPart });
  };

  const updateSize = (id: string, field: keyof CakeSize, value: any) => {
    const newSizes = config.sizes.map(s => s.id === id ? { ...s, [field]: value } : s);
    updateConfig({ sizes: newSizes });
  };

  const addSize = () => {
    const newSize: CakeSize = { id: `new_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porciones', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, newSize] });
  };

  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, field: keyof Flavor, value: any) => {
    const newFlavors = config.flavors.map(f => f.id === id ? { ...f, [field]: value } : f);
    updateConfig({ flavors: newFlavors });
  };

  const addFlavor = () => {
    const newFlavor: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo Bizcocho', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, newFlavor] });
  };

  const removeFlavor = (id: string) => {
    updateConfig({ flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, field: keyof Filling, value: any) => {
    const newFillings = config.fillings.map(f => f.id === id ? { ...f, [field]: value } : f);
    updateConfig({ fillings: newFillings });
  };

  const addFilling = () => {
    const newFilling: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo Relleno', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, newFilling] });
  };

  const removeFilling = (id: string) => {
    updateConfig({ fillings: config.fillings.filter(f => f.id !== id) });
  };

  const updateDecoration = (id: string, field: keyof DecorationInfo, value: any) => {
    const newDecorations = { ...config.decorations };
    newDecorations[id] = { ...newDecorations[id], [field]: value };
    updateConfig({ decorations: newDecorations });
  };

