                   </div>
                   <div className="flex justify-between items-center gap-4">
                      <span className="text-xs font-bold text-slate-600 uppercase">Colores Intensos</span>
                      <input type="number" className="w-20 bg-slate-50 border-none rounded-lg p-2 text-right font-bold text-primary text-sm shadow-inner" value={config.saturatedColorSurcharge || 0} onChange={(e) => updateConfig({ saturatedColorSurcharge: parseFloat(e.target.value) || 0 })} />
                   </div>
                </div>

                {/* COBERTURAS */}
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6 md:col-span-2">
                   <h4 className="font-black text-slate-800 uppercase text-xs mb-4 border-b pb-2">Recargos por Cobertura (Factor Multiplicador)</h4>
                   <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                      {['chantilly', 'chocolate', 'arequipe'].map(cov => (
                        <div key={cov} className="flex flex-col gap-2">
                           <label className="text-[10px] font-black text-slate-400 uppercase">{cov}</label>
                           <div className="flex items-center gap-2">
