                              <input 
                                type="number" 
                                className="w-full bg-slate-50 border-none rounded-lg p-3 font-bold text-primary text-sm shadow-inner" 
                                value={config.coverageSurcharges[cov] || 0} 
                                onChange={(e) => {
                                  const ns = { ...config.coverageSurcharges, [cov]: parseFloat(e.target.value) || 0 };
                                  updateConfig({ coverageSurcharges: ns });
                                }} 
                              />
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              </div>
            )}

            {/* ... Resto de los tabs: SIZES, FLAVORS, DECORATIONS, PAYMENTS, SETTINGS (implementados similarmente con isSaving) ... */}
            {activeTab === 'SIZES' && (
              <div className="space-y-6 md:space-y-8">
