                         <span className="text-[9px] font-black uppercase text-slate-400">{item.label}</span>
                       </div>
                     ))}
                   </div>
                </section>
              </div>
            )}

          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import SuccessStep from './components/SuccessStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

// Firebase imports
import { db } from './firebase';
import { collection, onSnapshot, doc, setDoc, getDoc } from 'firebase/firestore';

const DEFAULT_CONFIG: AppConfig = {
  sizes: CAKE_SIZES,
  flavors: FLAVORS,
  fillings: FILLINGS,
  colors: CAKE_COLORS,
  decorations: DECORATIONS,
  topperPrices: TOPPER_PRICES,
  spheresPrice: SPHERES_PRICE,
  saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
  coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
  paymentDetails: {
    bankName: "Pastelitos Bank",
    accountHolder: "Cakes Studio S.A.",
    zelleEmail: "pagos@cakesstudio.com",
    taxId: "J-12345678-9",
    exchangeRateNote: "Trabajamos con Tasa Euro (€)"
  },
  appTheme: {
    brandName: "Cake Customizer Studio",
    whatsappNumber: "584241546473",
    primaryColor: "#E31C58",
    secondaryColor: "#FFEB3B",
    backgroundColor: "#FFFBF2",
    textColor: "#000000",
    surfaceColor: "#FFFFFF"
  }
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);
  const [orders, setOrders] = useState<Order[]>([]);

  // --- FIREBASE SYNC ---
  useEffect(() => {
    if (!db) return;

    const configDocRef = doc(db, "settings", "appConfig");

    const initConfig = async () => {
      try {
        const docSnap = await getDoc(configDocRef);
        if (docSnap.exists()) {
          setConfig({ ...DEFAULT_CONFIG, ...docSnap.data() } as AppConfig);
        } else {
          await setDoc(configDocRef, DEFAULT_CONFIG);
        }
      } catch (e) {
        console.error("Error cargando configuración inicial:", e);
      }
    };

    initConfig();

    const unsubscribeConfig = onSnapshot(configDocRef, (docSnap) => {
      if (docSnap.exists()) {
        setConfig(prev => ({ ...prev, ...docSnap.data() }));
      }
    });

    const unsubscribeOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      const remoteOrders: Order[] = [];
      snapshot.forEach((doc) => {
        remoteOrders.push({ ...doc.data(), id: doc.id } as Order);
      });
      remoteOrders.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setOrders(remoteOrders);
    });

    return () => {
      unsubscribeConfig();
      unsubscribeOrders();
    };
  }, []);

  // --- THEME ---
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[1],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFilling: '',
    paymentStrategy: 'FIFTY_PERCENT',
  });

  const calculateTotal = useCallback(() => {
    const size = config.sizes.find(s => s.id === state.selectedSize?.id) || config.sizes[0];
    const flavor = config.flavors.find(f => f.id === state.selectedFlavor?.id) || config.flavors[0];
    const filling = config.fillings.find(f => f.id === state.selectedFilling?.id) || config.fillings[0];
    const decor = config.decorations[state.selectedDecoration] || { priceModifier: 0 };
    const factor = size.costMultiplier || 1.0;

    let total = size.basePrice + 
                (flavor.priceModifier * factor) + 
                (filling.priceModifier * factor) + 
                (decor.priceModifier * factor) + 
                (config.coverageSurcharges[state.coverageType] * factor) + 
                (config.topperPrices[state.topperType] || 0);

    if (state.hasSpheres) total += (config.spheresPrice * factor);

    const hasSaturated = state.cakeColors.some(hex => config.colors.find(c => c.hex === hex)?.isSaturated);
    if (hasSaturated) total += (config.saturatedColorSurcharge * factor);

    return total;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal() }));
  }, [state.selectedSize, state.selectedFlavor, state.selectedFilling, state.selectedDecoration, state.coverageType, state.topperType, state.hasSpheres, state.cakeColors, config]);

  const handleUpdateConfig = async (newConfig: AppConfig) => {
    setConfig(newConfig);
    if (db) {
      try {
        await setDoc(doc(db, "settings", "appConfig"), newConfig);
      } catch (e) {
        console.error("Error guardando config:", e);
      }
    }
  };

  const handleFinalizeOrder = async () => {
    try {
      const decorLabel = config.decorations[state.selectedDecoration]?.label || 'Liso';
      const colorNames = state.cakeColors.map(hex => config.colors.find(c => c.hex === hex)?.name || 'Personalizado').join(', ');

      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter}cm
🍰 Bizcocho: ${state.selectedFlavor?.name}
🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}
✨ Estilo: ${decorLabel}
🎨 Colores: ${colorNames}
🎯 Cobertura: ${state.coverageType.toUpperCase()}
🚀 Extras: ${state.topperType !== 'none' ? 'Topper ' + state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}
🎉 Temática: ${state.theme}
📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate}`;

      const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();
      const newOrder: Order = {
        id: simpleId,
        date: new Date().toLocaleString(),
        customerName: state.birthdayName || 'Cliente Web',
        details: detailedInfo,
        total: state.totalPrice,
        status: 'PENDING'
      };

      // 1. Guardar en Firebase (Usando setDoc para asegurar el ID)
      if (db) {
        console.log("💾 Guardando pedido en Firebase...");
        await setDoc(doc(db, "orders", simpleId), newOrder);
        console.log("✅ Pedido guardado exitosamente");
      }

      // 2. Abrir WhatsApp
      const message = `🎂 *NUEVO PEDIDO* (Ref: ${simpleId})\n\n${detailedInfo}\n\n💰 Total: $${state.totalPrice.toFixed(2)}`;
      window.open(`https://wa.me/${config.appTheme.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

      setState(prev => ({ ...prev, step: 'SUCCESS', lastOrderId: simpleId }));

    } catch (error) {
      console.error("Error en Firebase:", error);
      alert("Error al guardar el pedido en la base de datos. Verifica tu conexión.");
    }
  };

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {!['ADMIN_PANEL'].includes(state.step) && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
             {config.appTheme.logoUrl ? (
                <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" />
              ) : (
                <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">{config.appTheme.brandName}</h2>
              )}
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
            {state.step === 'SIZE' && <SizeStep selectedSize={state.selectedSize} onSelectSize={(s) => setState(p => ({...p, selectedSize: s}))} onNext={() => setState(p => ({...p, step: 'FLAVOR'}))} onAdminClick={() => setState(p => ({...p, step: 'ADMIN_LOGIN'}))} config={config} />}
            {state.step === 'FLAVOR' && <FlavorStep {...state} onSelectFlavor={(f) => setState(p => ({...p, selectedFlavor: f}))} onSelectFilling={(fill) => setState(p => ({...p, selectedFilling: fill}))} onNext={() => setState(p => ({...p, step: 'DECORATION'}))} onBack={() => setState(p => ({...p, step: 'SIZE'}))} onCustomFillingChange={(v) => setState(p => ({...p, customFilling: v}))} config={config} />}
            {state.step === 'DECORATION' && <DecorationStep {...state} onUpdateDecoration={(d) => setState(p => ({...p, ...d}))} onNext={() => setState(p => ({...p, step: 'PERSONALIZATION'}))} onBack={() => setState(p => ({...p, step: 'FLAVOR'}))} config={config} />}
            {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={(d) => setState(p => ({...p, ...d}))} onNext={() => setState(p => ({...p, step: 'SUMMARY'}))} onBack={() => setState(p => ({...p, step: 'DECORATION'}))} />}
            {state.step === 'SUMMARY' && <SummaryStep appState={state} onUpdate={(d) => setState(p => ({...p, ...d}))} onBack={() => setState(p => ({...p, step: 'PERSONALIZATION'}))} onConfirm={() => setState(p => ({...p, step: 'PAYMENT'}))} config={config} />}
            {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={(d) => setState(p => ({...p, ...d}))} onBack={() => setState(p => ({...p, step: 'SUMMARY'}))} onComplete={handleFinalizeOrder} />}
            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={() => setState(p => ({...p, step: 'SIZE'}))} config={config} />}
            {state.step === 'ADMIN_LOGIN' && <AdminLogin onLoginSuccess={() => setState(p => ({...p, step: 'ADMIN_PANEL'}))} onCancel={() => setState(p => ({...p, step: 'SIZE'}))} />}
            {state.step === 'ADMIN_PANEL' && <div className="fixed inset-0 z-[100]"><AdminPanel config={config} onUpdateConfig={handleUpdateConfig} orders={orders} onClearOrders={() => setOrders([])} onExit={() => setState(p => ({...p, step: 'SIZE'}))} /></div>}
        </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, DecorationInfo, CakeColor } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isSaving) {
      const timer = setTimeout(() => setIsSaving(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isSaving]);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    setIsSaving(true);
    onUpdateConfig({ ...config, ...newPart });
  };

  // HANDLERS
  const updateSize = (id: string, f: keyof CakeSize, v: any) => {
    updateConfig({ sizes: config.sizes.map(s => s.id === id ? { ...s, [f]: v } : s) });
  };
  const addSize = () => {
    const n: CakeSize = { id: `sz_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porc', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, n] });
  };

  const updateFlavor = (id: string, f: keyof Flavor, v: any) => {
    updateConfig({ flavors: config.flavors.map(fl => fl.id === id ? { ...fl, [f]: v } : fl) });
  };
  const addFlavor = () => {
    const n: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, n] });
  };

  const updateFilling = (id: string, f: keyof Filling, v: any) => {
    updateConfig({ fillings: config.fillings.map(fill => fill.id === id ? { ...fill, [f]: v } : fill) });
  };
  const addFilling = () => {
    const n: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, n] });
  };

  const updateDecoration = (id: string, f: keyof DecorationInfo, v: any) => {
    const next = { ...config.decorations };
    next[id] = { ...next[id], [f]: v };
    updateConfig({ decorations: next });
  };
  const addDecoration = () => {
    const id = `dec_${Date.now()}`;
    const next = { ...config.decorations };
    next[id] = { id, label: 'Nuevo Estilo', priceModifier: 10 };
    updateConfig({ decorations: next });
  };

  const updateColor = (i: number, f: keyof CakeColor, v: any) => {
    const next = [...config.colors];
    next[i] = { ...next[i], [f]: v };
    updateConfig({ colors: next });
  };

  const handleImageUpload = (id: string, type: 'flavor' | 'filling' | 'decoration', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onloadend = () => {
        const b64 = r.result as string;
        if (type === 'flavor') updateFlavor(id, 'textureUrl', b64);
        else if (type === 'filling') updateFilling(id, 'textureUrl', b64);
        else if (type === 'decoration') updateDecoration(id, 'textureUrl', b64);
      };
      r.readAsDataURL(file);
    }
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos', icon: 'auto_fix_high' },
    { id: 'COLORS', label: 'Colores', icon: 'palette' },
    { id: 'PRICES', label: 'Extras', icon: 'payments' },
    { id: 'PAYMENTS', label: 'Banco', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-quicksand">
      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 z-50 transition-transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static flex flex-col`}>
        <div className="p-8 border-b border-slate-800 text-white font-display uppercase tracking-widest">Admin Panel</div>
        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {menuItems.map(item => (
            <button key={item.id} onClick={() => { setActiveTab(item.id as any); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all ${activeTab === item.id ? 'bg-primary text-white shadow-xl' : 'text-slate-400 hover:bg-slate-800'}`}>
              <span className="material-icons-round">{item.icon}</span>
              <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800"><button onClick={onExit} className="w-full bg-slate-800 text-white py-4 rounded-xl font-black uppercase text-xs">Salir</button></div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-200 px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-600"><span className="material-icons-round">menu</span></button>
             <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">{menuItems.find(i => i.id === activeTab)?.label}</h2>
          </div>
          {isSaving && <div className="text-primary font-black uppercase text-[10px] animate-pulse">Guardando en Firebase...</div>}
        </header>

        <div className="flex-1 overflow-y-auto p-10 no-scrollbar">
          <div className="max-w-6xl mx-auto space-y-10 pb-10">

            {activeTab === 'ORDERS' && (
              <div className="space-y-4">
                {orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6">
                    <div className="w-16 h-16 bg-slate-50 rounded-xl flex items-center justify-center font-display text-primary border">{o.id.slice(-4)}</div>
                    <div className="flex-1"><h4 className="font-black text-slate-800 uppercase">{o.customerName}</h4><p className="text-xs text-slate-500 mt-1 whitespace-pre-line">{o.details}</p></div>
                    <div className="text-right"><p className="text-2xl font-display text-primary">${o.total.toFixed(2)}</p></div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'SIZES' && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <button onClick={addSize} className="bg-primary/5 border-2 border-dashed border-primary/20 p-6 rounded-2xl flex flex-col items-center justify-center gap-2 hover:bg-primary/10 transition-colors">
                  <span className="material-icons-round text-primary text-4xl">add_circle</span>
                  <span className="text-[10px] font-black uppercase text-primary">Añadir Molde</span>
                </button>
                {config.sizes.map(s => (
                  <div key={s.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                       <input type="number" className="w-full bg-slate-50 rounded p-2 font-bold" value={s.diameter} onChange={(e) => updateSize(s.id, 'diameter', parseInt(e.target.value))} />
                       <select className="w-full bg-slate-50 rounded p-2 text-xs font-bold" value={s.heightType} onChange={(e) => updateSize(s.id, 'heightType', e.target.value)}>
                          <option value="SHORT">BAJO</option><option value="TALL">ALTO</option>
                       </select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                       <input type="number" className="w-full bg-slate-900 text-white rounded p-2 font-bold" value={s.basePrice} onChange={(e) => updateSize(s.id, 'basePrice', parseFloat(e.target.value))} />
                       <input type="number" step="0.1" className="w-full bg-slate-50 rounded p-2 font-bold" value={s.costMultiplier} onChange={(e) => updateSize(s.id, 'costMultiplier', parseFloat(e.target.value))} />
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'FLAVORS' && (
              <div className="space-y-12">
