                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     {config.flavors.map(f => (
                       <div key={f.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex items-center gap-4">
                         <div className="w-12 h-12 bg-slate-50 rounded-xl relative overflow-hidden flex items-center justify-center border">
                           {f.textureUrl ? <img src={f.textureUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full" style={{backgroundColor: f.color}}></div>}
                           <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => handleImageUpload(f.id, 'flavor', e)} />
                         </div>
                         <input type="text" className="flex-1 bg-transparent border-none font-black text-xs uppercase" value={f.name} onChange={(e) => updateFlavor(f.id, 'name', e.target.value)} />
