                        {d.textureUrl ? <img src={d.textureUrl} className="w-full h-full object-cover" /> : <span className="material-icons-round text-4xl text-slate-200">photo</span>}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => handleImageUpload(id, 'decoration', e)} />
                      </div>
                      <div className="flex-1 space-y-4">
