                        <div className="flex items-center gap-2"><span className="text-xs font-bold text-slate-400">Recargo Base $</span><input type="number" className="w-20 bg-slate-900 text-white rounded p-2 font-bold" value={d.priceModifier} onChange={(e) => updateDecoration(id, 'priceModifier', parseFloat(e.target.value))} /></div>
                      </div>
