                  <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Titular</label><input type="text" className="w-full bg-slate-50 rounded-xl p-4 font-black" value={config.paymentDetails.accountHolder} onChange={(e) => updateConfig({ paymentDetails: { ...config.paymentDetails, accountHolder: e.target.value } })} /></div>
                  <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">RIF / ID</label><input type="text" className="w-full bg-slate-50 rounded-xl p-4 font-black" value={config.paymentDetails.taxId} onChange={(e) => updateConfig({ paymentDetails: { ...config.paymentDetails, taxId: e.target.value } })} /></div>
                  <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Zelle / Email</label><input type="text" className="w-full bg-slate-50 rounded-xl p-4 font-black text-primary" value={config.paymentDetails.zelleEmail} onChange={(e) => updateConfig({ paymentDetails: { ...config.paymentDetails, zelleEmail: e.target.value } })} /></div>
                  <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Tasa de Cambio</label><textarea className="w-full bg-slate-50 rounded-xl p-4 font-black h-24" value={config.paymentDetails.exchangeRateNote} onChange={(e) => updateConfig({ paymentDetails: { ...config.paymentDetails, exchangeRateNote: e.target.value } })} /></div>
               </div>
            )}

            {activeTab === 'COLORS' && (
               <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                 {config.colors.map((c, i) => (
                   <div key={i} className="bg-white p-4 rounded-2xl border border-slate-200 text-center space-y-3">
                     <div className="w-full h-12 rounded-lg relative overflow-hidden shadow-inner border" style={{backgroundColor: c.hex}}><input type="color" className="absolute inset-0 opacity-0 cursor-pointer" value={c.hex} onChange={(e) => updateColor(i, 'hex', e.target.value)} /></div>
                     <input type="text" className="w-full bg-slate-50 rounded p-1 text-[10px] font-black uppercase text-center" value={c.name} onChange={(e) => updateColor(i, 'name', e.target.value)} />
                     <button onClick={() => updateColor(i, 'isSaturated', !c.isSaturated)} className={`w-full py-1 rounded text-[8px] font-black uppercase border ${c.isSaturated ? 'bg-primary text-white border-primary' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>{c.isSaturated ? 'Saturado' : 'Estándar'}</button>
                   </div>
                 ))}
               </div>
            )}

            {activeTab === 'PRICES' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-3xl border border-slate-200 space-y-4">
                  <h4 className="font-black uppercase text-xs border-b pb-2">Toppers</h4>
                  {Object.entries(config.topperPrices).map(([k, v]) => (
                    <div key={k} className="flex justify-between items-center"><span className="text-[10px] font-black uppercase text-slate-400">{k}</span><input type="number" className="w-16 bg-slate-50 p-2 text-right font-bold text-primary" value={v} onChange={(e) => { const next = { ...config.topperPrices, [k]: parseFloat(e.target.value) }; updateConfig({ topperPrices: next }); }} /></div>
                  ))}
                </div>
                <div className="bg-white p-8 rounded-3xl border border-slate-200 space-y-4">
                  <h4 className="font-black uppercase text-xs border-b pb-2">Coberturas (Factor)</h4>
                  {Object.entries(config.coverageSurcharges).map(([k, v]) => (
                    <div key={k} className="flex justify-between items-center"><span className="text-[10px] font-black uppercase text-slate-400">{k}</span><input type="number" className="w-16 bg-slate-50 p-2 text-right font-bold text-primary" value={v} onChange={(e) => { const next = { ...config.coverageSurcharges, [k]: parseFloat(e.target.value) }; updateConfig({ coverageSurcharges: next }); }} /></div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'SETTINGS' && (
               <div className="bg-white p-12 rounded-[2.5rem] border border-slate-200 space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Nombre de Marca</label><input type="text" className="w-full bg-slate-50 rounded-xl p-4 font-black" value={config.appTheme.brandName} onChange={(e) => updateConfig({ appTheme: { ...config.appTheme, brandName: e.target.value } })} /></div>
                     <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">WhatsApp</label><input type="text" className="w-full bg-slate-50 rounded-xl p-4 font-black" value={config.appTheme.whatsappNumber} onChange={(e) => updateConfig({ appTheme: { ...config.appTheme, whatsappNumber: e.target.value } })} /></div>
                  </div>
                  <div className="flex flex-col items-center gap-4 bg-slate-50 p-8 rounded-3xl border-2 border-dashed">
                     <div className="w-32 h-32 bg-white rounded-2xl flex items-center justify-center overflow-hidden border">
                        {config.appTheme.logoUrl ? <img src={config.appTheme.logoUrl} className="w-full h-full object-contain" /> : <span className="material-icons-round text-slate-200 text-4xl">photo</span>}
                     </div>
                     <input type="file" className="text-xs" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) { const r = new FileReader(); r.onloadend = () => updateConfig({ appTheme: { ...config.appTheme, logoUrl: r.result as string } }); r.readAsDataURL(f); }
                     }} />
                  </div>
               </div>
            )}

          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

