import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import SuccessStep from './components/SuccessStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

// Firebase imports
import { db } from './firebase';
import { collection, onSnapshot, doc, setDoc, getDoc } from 'firebase/firestore';

const DEFAULT_CONFIG: AppConfig = {
  sizes: CAKE_SIZES,
  flavors: FLAVORS,
  fillings: FILLINGS,
  colors: CAKE_COLORS,
  decorations: DECORATIONS,
  topperPrices: TOPPER_PRICES,
  spheresPrice: SPHERES_PRICE,
  saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
  coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
  paymentDetails: {
    bankName: "Banco de Venezuela",
    accountHolder: "Tu Nombre Aquí",
    zelleEmail: "tu@correo.com",
    taxId: "V-00000000",
    exchangeRateNote: "Tasa BCV del día"
  },
  appTheme: {
    brandName: "MathiCake Studio",
    whatsappNumber: "584240000000",
    primaryColor: "#E31C58",
    secondaryColor: "#FFEB3B",
    backgroundColor: "#FFFBF2",
    textColor: "#000000",
    surfaceColor: "#FFFFFF"
  }
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);
  const [orders, setOrders] = useState<Order[]>([]);
  const [firebaseError, setFirebaseError] = useState<string | null>(null);

  // --- FIREBASE SYNC ---
  useEffect(() => {
    if (!db) return;

    const configDocRef = doc(db, "settings", "appConfig");

    const initConfig = async () => {
      try {
        const docSnap = await getDoc(configDocRef);
        if (docSnap.exists()) {
          setConfig({ ...DEFAULT_CONFIG, ...docSnap.data() } as AppConfig);
        } else {
          await setDoc(configDocRef, DEFAULT_CONFIG);
        }
        setFirebaseError(null);
      } catch (e: any) {
        if (e.code === 'permission-denied') {
          setFirebaseError("Firestore Bloqueado: Revisa las 'Rules' en tu consola de Firebase.");
        }
        console.error("Error Firebase Init:", e);
      }
    };

    initConfig();

    const unsubscribeConfig = onSnapshot(configDocRef, (docSnap) => {
      if (docSnap.exists()) {
        setConfig(prev => ({ ...prev, ...docSnap.data() }));
      }
    }, (err) => {
      if (err.code === 'permission-denied') {
        setFirebaseError("Error de Permisos: La base de datos no permite lectura.");
      }
    });

    const unsubscribeOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      const remoteOrders: Order[] = [];
      snapshot.forEach((doc) => {
        remoteOrders.push({ ...doc.data(), id: doc.id } as Order);
      });
      remoteOrders.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setOrders(remoteOrders);
    }, (err) => {
      console.error("Error en escucha de pedidos:", err);
    });

    return () => {
      unsubscribeConfig();
      unsubscribeOrders();
    };
  }, []);

  // --- THEME ---
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[1],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFilling: '',
    paymentStrategy: 'FIFTY_PERCENT',
  });

  const calculateTotal = useCallback(() => {
    const size = config.sizes.find(s => s.id === state.selectedSize?.id) || config.sizes[0];
    const flavor = config.flavors.find(f => f.id === state.selectedFlavor?.id) || config.flavors[0];
    const filling = config.fillings.find(f => f.id === state.selectedFilling?.id) || config.fillings[0];
    const decor = config.decorations[state.selectedDecoration] || { priceModifier: 0 };
    const factor = size.costMultiplier || 1.0;

    let total = size.basePrice + 
                (flavor.priceModifier * factor) + 
                (filling.priceModifier * factor) + 
                (decor.priceModifier * factor) + 
                (config.coverageSurcharges[state.coverageType] * factor) + 
                (config.topperPrices[state.topperType] || 0);

    if (state.hasSpheres) total += (config.spheresPrice * factor);

    const hasSaturated = state.cakeColors.some(hex => config.colors.find(c => c.hex === hex)?.isSaturated);
    if (hasSaturated) total += (config.saturatedColorSurcharge * factor);

    return total;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal() }));
  }, [state.selectedSize, state.selectedFlavor, state.selectedFilling, state.selectedDecoration, state.coverageType, state.topperType, state.hasSpheres, state.cakeColors, config]);

  const handleUpdateConfig = async (newConfig: AppConfig) => {
    setConfig(newConfig);
    if (db) {
      try {
        await setDoc(doc(db, "settings", "appConfig"), newConfig);
      } catch (e: any) {
        if (e.code === 'permission-denied') {
          alert("Error: No tienes permiso para editar. Revisa las 'Rules' de Firestore.");
        } else {
          alert("Error al guardar: " + e.message);
        }
      }
    }
  };

  const handleFinalizeOrder = async () => {
    const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();

    try {
      const decorLabel = config.decorations[state.selectedDecoration]?.label || 'Liso';
      const colorNames = state.cakeColors.map(hex => config.colors.find(c => c.hex === hex)?.name || 'Personalizado').join(', ');

      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter}cm
🍰 Bizcocho: ${state.selectedFlavor?.name}
🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}
✨ Estilo: ${decorLabel}
🎨 Colores: ${colorNames}
🎯 Cobertura: ${state.coverageType.toUpperCase()}
🚀 Extras: ${state.topperType !== 'none' ? 'Topper ' + state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}
🎉 Temática: ${state.theme}
📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate}`;

      const newOrder: Order = {
        id: simpleId,
        date: new Date().toLocaleString(),
        customerName: state.birthdayName || 'Cliente Web',
        details: detailedInfo,
        total: state.totalPrice,
        status: 'PENDING'
      };

      // Intentar guardar en Firebase pero no bloquear si falla por permisos
      if (db) {
        try {
          await setDoc(doc(db, "orders", simpleId), newOrder);
        } catch (fbErr: any) {
          console.warn("No se pudo guardar en Firebase, continuando a WhatsApp:", fbErr);
          if (fbErr.code === 'permission-denied') {
            alert("⚠️ El pedido no se sincronizó con el panel administrativo por falta de permisos en Firebase, pero continuaremos con WhatsApp.");
          }
        }
      }

      const message = `🎂 *NUEVO PEDIDO* (Ref: ${simpleId})\n\n${detailedInfo}\n\n💰 Total: $${state.totalPrice.toFixed(2)}`;
      window.open(`https://wa.me/${config.appTheme.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');

      setState(prev => ({ ...prev, step: 'SUCCESS', lastOrderId: simpleId }));

    } catch (error: any) {
      console.error("Error crítico al procesar pedido:", error);
      alert("Error al procesar el pedido. Por favor intenta de nuevo.");
    }
  };

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {firebaseError && (
          <div className="bg-red-600 text-white text-[10px] md:text-xs py-2 px-4 text-center font-black uppercase tracking-widest z-[200] flex items-center justify-center gap-2">
            <span className="material-icons-round text-sm">warning</span>
            {firebaseError}
            <span className="hidden md:inline-block opacity-70">| Revisa la pestaña 'Rules' en Firestore</span>
          </div>
        )}

        {!['ADMIN_PANEL'].includes(state.step) && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
             {config.appTheme.logoUrl ? (
                <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" />
              ) : (
                <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">{config.appTheme.brandName}</h2>
              )}
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
            {state.step === 'SIZE' && <SizeStep selectedSize={state.selectedSize} onSelectSize={(s) => setState(p => ({...p, selectedSize: s}))} onNext={() => setState(p => ({...p, step: 'FLAVOR'}))} onAdminClick={() => setState(p => ({...p, step: 'ADMIN_LOGIN'}))} config={config} />}
            {state.step === 'FLAVOR' && <FlavorStep {...state} onSelectFlavor={(f) => setState(p => ({...p, selectedFlavor: f}))} onSelectFilling={(fill) => setState(p => ({...p, selectedFilling: fill}))} onNext={() => setState(p => ({...p, step: 'DECORATION'}))} onBack={() => setState(p => ({...p, step: 'SIZE'}))} onCustomFillingChange={(v) => setState(p => ({...p, customFilling: v}))} config={config} />}
            {state.step === 'DECORATION' && <DecorationStep {...state} onUpdateDecoration={(d) => setState(p => ({...p, ...d}))} onNext={() => setState(p => ({...p, step: 'PERSONALIZATION'}))} onBack={() => setState(p => ({...p, step: 'FLAVOR'}))} config={config} />}
            {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={(d) => setState(p => ({...p, ...d}))} onNext={() => setState(p => ({...p, step: 'SUMMARY'}))} onBack={() => setState(p => ({...p, step: 'DECORATION'}))} />}
            {state.step === 'SUMMARY' && <SummaryStep appState={state} onUpdate={(d) => setState(p => ({...p, ...d}))} onBack={() => setState(p => ({...p, step: 'PERSONALIZATION'}))} onConfirm={() => setState(p => ({...p, step: 'PAYMENT'}))} config={config} />}
            {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={(d) => setState(p => ({...p, ...d}))} onBack={() => setState(p => ({...p, step: 'SUMMARY'}))} onComplete={handleFinalizeOrder} />}
            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={() => setState(p => ({...p, step: 'SIZE'}))} config={config} />}
            {state.step === 'ADMIN_LOGIN' && <AdminLogin onLoginSuccess={() => setState(p => ({...p, step: 'ADMIN_PANEL'}))} onCancel={() => setState(p => ({...p, step: 'SIZE'}))} />}
            {state.step === 'ADMIN_PANEL' && <div className="fixed inset-0 z-[100]"><AdminPanel config={config} onUpdateConfig={handleUpdateConfig} orders={orders} onClearOrders={() => setOrders([])} onExit={() => setState(p => ({...p, step: 'SIZE'}))} /></div>}
        </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, DecorationInfo, CakeColor } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isSaving) {
      const timer = setTimeout(() => setIsSaving(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isSaving]);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    setIsSaving(true);
    onUpdateConfig({ ...config, ...newPart });
  };

  // HANDLERS DE EDICIÓN
  const updateSize = (id: string, f: keyof CakeSize, v: any) => {
    updateConfig({ sizes: config.sizes.map(s => s.id === id ? { ...s, [f]: v } : s) });
  };
  const addSize = () => {
    const n: CakeSize = { id: `sz_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porc', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, n] });
  };
  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, f: keyof Flavor, v: any) => {
    updateConfig({ flavors: config.flavors.map(fl => fl.id === id ? { ...fl, [f]: v } : fl) });
  };
  const addFlavor = () => {
    const n: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo Ponqué', color: '#F3E5AB', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, n] });
  };
  const removeFlavor = (id: string) => {
    updateConfig({ flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, f: keyof Filling, v: any) => {
    updateConfig({ fillings: config.fillings.map(fill => fill.id === id ? { ...fill, [f]: v } : fill) });
  };
  const addFilling = () => {
    const n: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo Relleno', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, n] });
  };
  const removeFilling = (id: string) => {
    updateConfig({ fillings: config.fillings.filter(f => f.id !== id) });
  };

  const updateDecoration = (id: string, f: keyof DecorationInfo, v: any) => {
    const next = { ...config.decorations };
    next[id] = { ...next[id], [f]: v };
    updateConfig({ decorations: next });
  };
  const addDecoration = () => {
    const id = `dec_${Date.now()}`;
    const next = { ...config.decorations };
    next[id] = { id, label: 'Nuevo Estilo', priceModifier: 10 };
    updateConfig({ decorations: next });
  };
  const removeDecoration = (id: string) => {
    const next = { ...config.decorations };
    delete next[id];
    updateConfig({ decorations: next });
  };

  const updateColor = (i: number, f: keyof CakeColor, v: any) => {
    const next = [...config.colors];
    next[i] = { ...next[i], [f]: v };
    updateConfig({ colors: next });
  };

  const handleImageUpload = (id: string, type: 'flavor' | 'filling' | 'decoration', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onloadend = () => {
        const b64 = r.result as string;
        if (type === 'flavor') updateFlavor(id, 'textureUrl', b64);
        else if (type === 'filling') updateFilling(id, 'textureUrl', b64);
        else if (type === 'decoration') updateDecoration(id, 'textureUrl', b64);
      };
      r.readAsDataURL(file);
    }
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos', icon: 'auto_fix_high' },
    { id: 'COLORS', label: 'Colores', icon: 'palette' },
    { id: 'PRICES', label: 'Extras', icon: 'payments' },
    { id: 'PAYMENTS', label: 'Banco', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-quicksand overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 z-[110] transition-transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-slate-800 text-white font-display uppercase tracking-widest flex items-center gap-3">
          <span className="material-icons-round text-primary">admin_panel_settings</span>
          Admin Panel
        </div>
        <nav className="flex-1 p-4 space-y-2 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button key={item.id} onClick={() => { setActiveTab(item.id as any); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all ${activeTab === item.id ? 'bg-primary text-white shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-800'}`}>
              <span className="material-icons-round">{item.icon}</span>
              <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800">
          <button onClick={onExit} className="w-full bg-slate-800 hover:bg-red-600 text-white py-4 rounded-xl font-black uppercase text-xs transition-colors">Salir</button>
        </div>
      </aside>

      {/* Main Area */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 px-6 md:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-600"><span className="material-icons-round">menu</span></button>
             <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">{menuItems.find(i => i.id === activeTab)?.label}</h2>
          </div>
          {isSaving && (
            <div className="flex items-center gap-2 text-primary font-black uppercase text-[10px] animate-pulse">
              <span className="material-icons-round text-sm">sync</span>
              Sincronizando...
            </div>
          )}
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 no-scrollbar bg-slate-50/50">
          <div className="max-w-6xl mx-auto space-y-10 pb-20">

            {/* ORDERS TAB */}
            {activeTab === 'ORDERS' && (
              <div className="space-y-4">
                {orders.length === 0 ? (
                  <div className="bg-white p-20 rounded-3xl border-2 border-dashed border-slate-200 text-center">
                    <p className="text-slate-400 font-black uppercase text-xs">Sin pedidos registrados</p>
                  </div>
                ) : (
                  orders.map(o => (
                    <div key={o.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
                      <div className="w-16 h-16 bg-slate-50 rounded-xl flex items-center justify-center font-display text-primary border text-xl">{o.id.slice(-4)}</div>
                      <div className="flex-1">
                        <h4 className="font-black text-slate-800 uppercase">{o.customerName}</h4>
                        <p className="text-[10px] text-slate-400 font-bold mb-2">{o.date}</p>
                        <p className="text-xs text-slate-600 whitespace-pre-line leading-relaxed">{o.details}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-3xl font-display text-primary">${o.total.toFixed(2)}</p>
                        <span className="text-[9px] font-black uppercase px-3 py-1 bg-green-50 text-green-600 rounded-full border border-green-100">Confirmado</span>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* FLAVORS & FILLINGS TAB */}
            {activeTab === 'FLAVORS' && (
              <div className="space-y-12">
                 <section className="space-y-6">
                   <div className="flex justify-between items-center">
                     <h3 className="font-black uppercase text-xs border-l-4 border-primary pl-4">SABORES DE BIZCOCHO</h3>
                     <button onClick={addFlavor} className="bg-primary text-white px-4 py-2 rounded-lg font-black uppercase text-[10px]">Nuevo Sabor</button>
                   </div>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     {config.flavors.map(f => (
                       <div key={f.id} className="bg-white p-6 rounded-2xl border border-slate-200 flex items-center gap-6 group relative">
                         <div className="w-16 h-16 bg-slate-100 rounded-2xl relative overflow-hidden flex items-center justify-center border shadow-inner">
                           {f.textureUrl ? <img src={f.textureUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full" style={{backgroundColor: f.color}}></div>}
                           <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => handleImageUpload(f.id, 'flavor', e)} />
                         </div>
                         <div className="flex-1 space-y-2">
                           <input type="text" className="w-full bg-transparent border-none font-black text-sm uppercase p-0" value={f.name} onChange={(e) => updateFlavor(f.id, 'name', e.target.value)} />
                           <div className="flex items-center gap-4">
                             <input type="color" className="w-8 h-8 p-0 border-none bg-transparent cursor-pointer" value={f.color} onChange={(e) => updateFlavor(f.id, 'color', e.target.value)} />
                             <div className="flex items-center gap-1 font-bold text-primary text-xs">
                                <span>+$</span>
                                <input type="number" className="w-16 bg-slate-50 rounded p-1 font-bold border-none" value={f.priceModifier} onChange={(e) => updateFlavor(f.id, 'priceModifier', parseFloat(e.target.value))} />
                             </div>
                           </div>
                         </div>
                         <button onClick={() => removeFlavor(f.id)} className="text-slate-200 hover:text-red-500 transition-colors"><span className="material-icons-round text-sm">delete</span></button>
                       </div>
                     ))}
                   </div>
                 </section>

                 <section className="space-y-6">
                   <div className="flex justify-between items-center">
                     <h3 className="font-black uppercase text-xs border-l-4 border-slate-400 pl-4">RELLENOS DISPONIBLES</h3>
                     <button onClick={addFilling} className="bg-slate-500 text-white px-4 py-2 rounded-lg font-black uppercase text-[10px]">Nuevo Relleno</button>
                   </div>
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                     {config.fillings.map(f => (
                       <div key={f.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex flex-col items-center text-center gap-4 relative">
                          <button onClick={() => removeFilling(f.id)} className="absolute top-2 right-2 text-slate-200 hover:text-red-500"><span className="material-icons-round text-xs">delete</span></button>
                          <div className="w-12 h-12 rounded-full relative overflow-hidden border shadow-soft bg-slate-50 flex items-center justify-center">
                            {f.textureUrl ? <img src={f.textureUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full" style={{backgroundColor: f.color}}></div>}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => handleImageUpload(f.id, 'filling', e)} />
                          </div>
                          <input type="text" className="w-full bg-transparent border-none font-bold text-[10px] uppercase text-center p-0" value={f.name} onChange={(e) => updateFilling(f.id, 'name', e.target.value)} />
                          <div className="flex items-center gap-1 font-bold text-primary text-[10px]">
                            <span>+$</span>
                            <input type="number" className="w-10 text-center bg-slate-50 rounded p-1 border-none font-bold" value={f.priceModifier} onChange={(e) => updateFilling(f.id, 'priceModifier', parseFloat(e.target.value))} />
                          </div>
                       </div>
                     ))}
                   </div>
                 </section>
              </div>
            )}

            {/* DECORATIONS TAB */}
            {activeTab === 'DECORATIONS' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <button onClick={addDecoration} className="bg-white border-4 border-dashed border-slate-100 p-16 rounded-[2.5rem] flex flex-col items-center gap-4 text-slate-300 hover:text-primary hover:border-primary/20 transition-all group">
                  <span className="material-icons-round text-7xl group-hover:scale-110 transition-transform">auto_fix_high</span>
                  <span className="font-black uppercase text-xs tracking-widest">Crear Estilo de Decoración</span>
                </button>
                {Object.keys(config.decorations).map(id => {
                  const d = config.decorations[id];
                  return (
                    <div key={id} className="bg-white p-8 rounded-[2.5rem] border border-slate-200 flex gap-8 shadow-sm relative group">
                      <button onClick={() => removeDecoration(id)} className="absolute top-4 right-4 text-slate-200 hover:text-red-500"><span className="material-icons-round text-sm">delete</span></button>
                      <div className="w-32 h-32 bg-slate-100 rounded-3xl relative overflow-hidden flex items-center justify-center border shadow-inner shrink-0">
                        {d.textureUrl ? <img src={d.textureUrl} className="w-full h-full object-cover" /> : <span className="material-icons-round text-5xl text-slate-200">photo</span>}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => handleImageUpload(id, 'decoration', e)} />
                      </div>
                      <div className="flex-1 space-y-6">
                        <div>
                          <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Nombre del Estilo</label>
                          <input type="text" className="w-full bg-slate-50 rounded-xl p-3 font-black uppercase text-xs border-none" value={d.label} onChange={(e) => updateDecoration(id, 'label', e.target.value)} />
                        </div>
                        <div>
                          <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Recargo Base $</label>
