                            <input type="number" className="w-8 text-center bg-transparent border-none p-0 font-bold text-primary" value={f.priceModifier} onChange={(e) => updateFilling(f.id, 'priceModifier', parseFloat(e.target.value))} />
                          </div>
                       </div>
                     ))}
