                    <div className="flex flex-col items-end">
                      {price > 0 ? (
                        <div className={`px-3 py-1.5 rounded-full font-black text-[10px] md:text-xs tracking-tighter ${isSelected ? 'bg-primary text-white' : 'bg-slate-100 text-primary'}`}>
