};

export default DecorationStep;

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order, CakeSize, Flavor, Filling } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import SuccessStep from './components/SuccessStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

// Firebase imports
import { db } from './firebase';
import { collection, onSnapshot, doc, setDoc, getDoc, deleteDoc, updateDoc } from 'firebase/firestore';

const DEFAULT_CONFIG: AppConfig = {
  sizes: CAKE_SIZES,
  flavors: FLAVORS,
  fillings: FILLINGS,
  colors: CAKE_COLORS,
  decorations: DECORATIONS,
  topperPrices: TOPPER_PRICES,
  spheresPrice: SPHERES_PRICE,
  saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
  coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
  paymentDetails: {
    bankName: "Banco de Venezuela",
    accountHolder: "Tu Nombre Aquí",
    zelleEmail: "tu@correo.com",
    taxId: "V-00000000",
    exchangeRateNote: "Tasa BCV del día"
  },
  appTheme: {
    brandName: "MathiCake Studio",
    whatsappNumber: "584240000000",
    primaryColor: "#E31C58",
    secondaryColor: "#FFEB3B",
    backgroundColor: "#FFFBF2",
    textColor: "#000000",
    surfaceColor: "#FFFFFF"
  }
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);
  const [orders, setOrders] = useState<Order[]>([]);
  const [firebaseError, setFirebaseError] = useState<string | null>(null);

  // --- NAVEGACIÓN Y ESTADO ---
  const navigateTo = (step: Step) => setState(prev => ({ ...prev, step }));
  const updateAppState = (updates: Partial<AppState>) => setState(prev => ({ ...prev, ...updates }));
  const resetApp = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  const handleSelectSize = (s: CakeSize) => updateAppState({ selectedSize: s });
  const handleGoToFlavor = () => navigateTo('FLAVOR');
  const handleGoToAdminLogin = () => navigateTo('ADMIN_LOGIN');
  const handleSelectFlavor = (f: Flavor) => updateAppState({ selectedFlavor: f });
  const handleSelectFilling = (fill: Filling) => updateAppState({ selectedFilling: fill });
  const handleGoToDecoration = () => navigateTo('DECORATION');
  const handleGoToSize = () => navigateTo('SIZE');
  const handleCustomFillingChange = (v: string) => updateAppState({ customFilling: v });
  const handleUpdateDecoration = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToPersonalization = () => navigateTo('PERSONALIZATION');
  const handleUpdatePersonalization = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToSummary = () => navigateTo('SUMMARY');
  const handleUpdateSummary = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToPayment = () => navigateTo('PAYMENT');
  const handleUpdatePayment = (d: any) => updateAppState(d);
  const handleLoginSuccess = () => navigateTo('ADMIN_PANEL');

  // --- GESTIÓN DE PEDIDOS ---
  const handleDeleteOrder = async (orderId: string) => {
    if (!db) return;

    // Alerta de confirmación inmediata
    if (window.confirm(`¿Seguro que deseas ELIMINAR permanentemente la orden ${orderId}?`)) {
      try {
        console.log(`Borrando orden de la base de datos: ${orderId}`);

        // 1. ELIMINACIÓN OPTIMISTA (Desaparece de inmediato de la UI local)
        // Guardamos una referencia para no volver a cargarla si el onSnapshot dispara antes del borrado real
        setOrders(prev => prev.filter(o => o.id !== orderId));

        // 2. ELIMINACIÓN REAL EN FIRESTORE
        const orderRef = doc(db, "orders", orderId);
        await deleteDoc(orderRef);
        console.log("Orden eliminada correctamente del servidor.");
      } catch (e: any) {
        console.error("Error crítico al eliminar pedido:", e);
        alert(`Fallo al borrar de la nube: ${e.message}`);
        // Si falla, el onSnapshot la restaurará automáticamente en la siguiente ráfaga
      }
    }
  };

  const handleUpdateOrderStatus = async (orderId: string, status: 'PENDING' | 'COMPLETED') => {
    if (!db) return;
    try {
      const orderRef = doc(db, "orders", orderId);
      await updateDoc(orderRef, { status });
    } catch (e: any) {
      console.error("Error al actualizar estado:", e);
      alert(`Error: ${e.message}`);
    }
  };

  // --- FIREBASE SYNC ---
  useEffect(() => {
    if (!db) return;
    const configDocRef = doc(db, "settings", "appConfig");

    const initConfig = async () => {
      try {
        const docSnap = await getDoc(configDocRef);
        if (docSnap.exists()) {
          setConfig({ ...DEFAULT_CONFIG, ...docSnap.data() } as AppConfig);
        } else {
          await setDoc(configDocRef, DEFAULT_CONFIG);
        }
      } catch (e: any) {
        if (e.code === 'permission-denied') setFirebaseError("Acceso denegado a Firestore");
      }
    };
    initConfig();

    const unsubscribeConfig = onSnapshot(configDocRef, (docSnap) => {
      if (docSnap.exists()) setConfig(prev => ({ ...prev, ...docSnap.data() }));
    });

    const unsubscribeOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      const remoteOrders: Order[] = [];
      snapshot.forEach((doc) => { remoteOrders.push({ ...doc.data(), id: doc.id } as Order); });
      // Ordenar por fecha descendente
      remoteOrders.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setOrders(remoteOrders);
    });

    return () => { unsubscribeConfig(); unsubscribeOrders(); };
  }, []);

  // --- THEME ---
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[1],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFilling: '',
    paymentStrategy: 'FIFTY_PERCENT',
  });

  const calculateTotal = useCallback(() => {
    const size = config.sizes.find(s => s.id === state.selectedSize?.id) || config.sizes[0];
    const flavor = config.flavors.find(f => f.id === state.selectedFlavor?.id) || config.flavors[0];
    const filling = config.fillings.find(f => f.id === state.selectedFilling?.id) || config.fillings[0];
    const decor = config.decorations[state.selectedDecoration] || { priceModifier: 0 };
    const factor = size.costMultiplier || 1.0;
    let total = size.basePrice + (flavor.priceModifier * factor) + (filling.priceModifier * factor) + (decor.priceModifier * factor) + (config.coverageSurcharges[state.coverageType] * factor) + (config.topperPrices[state.topperType] || 0);
    if (state.hasSpheres) total += (config.spheresPrice * factor);
    const hasSaturated = state.cakeColors.some(hex => config.colors.find(c => c.hex === hex)?.isSaturated);
    if (hasSaturated) total += (config.saturatedColorSurcharge * factor);
    return total;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal() }));
  }, [state.selectedSize, state.selectedFlavor, state.selectedFilling, state.selectedDecoration, state.coverageType, state.topperType, state.hasSpheres, state.cakeColors, config, calculateTotal]);

  const handleUpdateConfig = async (newConfig: AppConfig) => {
    setConfig(newConfig);
    if (db) await setDoc(doc(db, "settings", "appConfig"), newConfig);
  };

  const handleFinalizeOrder = async () => {
    const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();
    try {
      const decorLabel = config.decorations[state.selectedDecoration]?.label || 'Liso';
      const colorNames = state.cakeColors.map(hex => config.colors.find(c => c.hex === hex)?.name || 'Personalizado').join(', ');
      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter}cm\n🍰 Bizcocho: ${state.selectedFlavor?.name}\n🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}\n✨ Estilo: ${decorLabel}\n🎨 Colores: ${colorNames}\n🎯 Cobertura: ${state.coverageType.toUpperCase()}\n🚀 Extras: ${state.topperType !== 'none' ? 'Topper ' + state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}\n🎉 Temática: ${state.theme}\n📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate}`;
      const newOrder: Order = { id: simpleId, date: new Date().toLocaleString(), customerName: state.birthdayName || 'Cliente Web', details: detailedInfo, total: state.totalPrice, status: 'PENDING' };
      if (db) await setDoc(doc(db, "orders", simpleId), newOrder);
      window.open(`https://wa.me/${config.appTheme.whatsappNumber}?text=${encodeURIComponent(`🎂 *NUEVO PEDIDO* (Ref: ${simpleId})\n\n${detailedInfo}\n\n💰 Total: $${state.totalPrice.toFixed(2)}`)}`, '_blank');
      setState(prev => ({ ...prev, step: 'SUCCESS', lastOrderId: simpleId }));
    } catch (error) { console.error("Error crítico:", error); }
  };

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {firebaseError && (
          <div className="bg-red-600 text-white text-[10px] md:text-xs py-2 px-4 text-center font-black uppercase tracking-widest z-[200] flex flex-col items-center justify-center gap-1 shadow-2xl border-b-2 border-red-800">
            <div className="flex items-center gap-2"><span className="material-icons-round text-sm animate-pulse">error_outline</span>{firebaseError}</div>
          </div>
        )}

        {!['ADMIN_PANEL'].includes(state.step) && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
             {config.appTheme.logoUrl ? <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" /> : <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">{config.appTheme.brandName}</h2>}
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
            {state.step === 'SIZE' && <SizeStep selectedSize={state.selectedSize} onSelectSize={handleSelectSize} onNext={handleGoToFlavor} onAdminClick={handleGoToAdminLogin} config={config} />}
            {state.step === 'FLAVOR' && <FlavorStep {...state} onSelectFlavor={handleSelectFlavor} onSelectFilling={handleSelectFilling} onNext={handleGoToDecoration} onBack={handleGoToSize} onCustomFillingChange={handleCustomFillingChange} config={config} />}
            {state.step === 'DECORATION' && <DecorationStep {...state} onUpdateDecoration={handleUpdateDecoration} onNext={handleGoToPersonalization} onBack={handleGoToFlavor} config={config} />}
            {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={handleUpdatePersonalization} onNext={handleGoToSummary} onBack={handleGoToDecoration} />}
            {state.step === 'SUMMARY' && <SummaryStep appState={state} onUpdate={handleUpdateSummary} onBack={handleGoToPersonalization} onConfirm={handleGoToPayment} config={config} />}
            {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={handleUpdatePayment} onBack={handleGoToSummary} onComplete={handleFinalizeOrder} />}
            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={resetApp} config={config} />}
            {state.step === 'ADMIN_LOGIN' && <AdminLogin onLoginSuccess={handleLoginSuccess} onCancel={resetApp} />}
            {state.step === 'ADMIN_PANEL' && (
              <div className="fixed inset-0 z-[100]">
                <AdminPanel 
                  config={config} 
                  onUpdateConfig={handleUpdateConfig} 
                  orders={orders} 
                  onDeleteOrder={handleDeleteOrder}
                  onUpdateOrderStatus={handleUpdateOrderStatus}
                  onClearOrders={() => {}} 
                  onExit={resetApp} 
                />
              </div>
            )}
        </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, DecorationInfo } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onDeleteOrder: (id: string) => void;
  onUpdateOrderStatus: (id: string, status: 'PENDING' | 'COMPLETED') => void;
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onDeleteOrder, onUpdateOrderStatus, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isSaving) {
      const timer = setTimeout(() => setIsSaving(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [isSaving]);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    setIsSaving(true);
    onUpdateConfig({ ...config, ...newPart });
  };

  const updateSize = (id: string, f: keyof CakeSize, v: any) => {
    updateConfig({ sizes: config.sizes.map(s => s.id === id ? { ...s, [f]: v } : s) });
  };
  const addSize = () => {
    const n: CakeSize = { id: `sz_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porc', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, n] });
  };
  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, f: keyof Flavor, v: any) => {
    updateConfig({ flavors: config.flavors.map(fl => fl.id === id ? { ...fl, [f]: v } : fl) });
  };
  const addFlavor = () => {
    const n: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, n] });
  };

  const updateFilling = (id: string, f: keyof Filling, v: any) => {
    updateConfig({ fillings: config.fillings.map(fill => fill.id === id ? { ...fill, [f]: v } : fill) });
  };
  const addFilling = () => {
    const n: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, n] });
  };

  const updateDecoration = (id: string, f: keyof DecorationInfo, v: any) => {
    const next = { ...config.decorations };
    next[id] = { ...next[id], [f]: v };
    updateConfig({ decorations: next });
  };
  const addDecoration = () => {
    const id = `dec_${Date.now()}`;
    const next = { ...config.decorations };
    next[id] = { id, label: 'Nuevo Estilo', priceModifier: 10 };
    updateConfig({ decorations: next });
  };

  const handleImageUpload = (id: string, type: 'flavor' | 'filling' | 'decoration', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onloadend = () => {
        const b64 = r.result as string;
        if (type === 'flavor') updateFlavor(id, 'textureUrl', b64);
        else if (type === 'filling') updateFilling(id, 'textureUrl', b64);
        else if (type === 'decoration') updateDecoration(id, 'textureUrl', b64);
      };
      r.readAsDataURL(file);
    }
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos', icon: 'auto_fix_high' },
    { id: 'PRICES', label: 'Precios Extras', icon: 'sell' },
    { id: 'PAYMENTS', label: 'Banco/Pagos', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca/Logo', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-quicksand overflow-hidden">
      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 z-[120] transition-transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-slate-800 text-white font-display uppercase tracking-widest flex items-center gap-3">
          <span className="material-icons-round text-primary">cake</span>
          Admin Mathi
        </div>
        <nav className="flex-1 p-4 space-y-1 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button key={item.id} onClick={() => { setActiveTab(item.id as any); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all ${activeTab === item.id ? 'bg-primary text-white shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-800'}`}>
              <span className="material-icons-round text-xl">{item.icon}</span>
              <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800">
          <button onClick={onExit} className="w-full bg-slate-800 hover:bg-red-600 text-white py-4 rounded-xl font-black uppercase text-xs transition-colors">Cerrar Sesión</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-200 px-6 md:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-600"><span className="material-icons-round">menu</span></button>
             <h2 className="text-lg font-black text-slate-800 uppercase tracking-tighter">{menuItems.find(i => i.id === activeTab)?.label}</h2>
          </div>
          {isSaving && (
            <div className="flex items-center gap-2 text-primary font-black uppercase text-[10px] animate-pulse">
              <span className="material-icons-round text-sm">sync</span>
              Sincronizando...
            </div>
          )}
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 no-scrollbar bg-slate-50/30">
          <div className="max-w-6xl mx-auto space-y-10 pb-20">

            {activeTab === 'ORDERS' && (
              <div className="space-y-4">
                {orders.length === 0 ? (
                  <div className="bg-white p-20 rounded-3xl border-2 border-dashed border-slate-200 text-center">
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Aún no hay pedidos registrados</p>
                  </div>
                ) : (
                  orders.map(o => (
                    <div key={o.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
                      <div className="w-16 h-16 bg-slate-50 rounded-xl flex items-center justify-center font-display text-primary border text-xl shrink-0">{o.id.slice(-4)}</div>
                      <div className="flex-1">
                        <h4 className="font-black text-slate-800 uppercase text-sm">{o.customerName}</h4>
                        <p className="text-[9px] text-slate-400 font-bold mb-2">{o.date}</p>
                        <p className="text-[11px] text-slate-600 whitespace-pre-line leading-relaxed">{o.details}</p>
                      </div>
                      <div className="text-right flex flex-col items-end gap-3 shrink-0">
                        <div className="flex flex-col items-end">
                            <p className="text-3xl font-display text-primary">${o.total.toFixed(2)}</p>
                            <span className={`text-[8px] font-black uppercase px-3 py-1 rounded-full border ${o.status === 'COMPLETED' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                                {o.status === 'COMPLETED' ? 'Entregado' : 'Pendiente'}
                            </span>
                        </div>
                        <div className="flex flex-col gap-2 w-full md:w-32">
                           {o.status === 'PENDING' && (
                             <button 
                                onClick={() => onUpdateOrderStatus(o.id, 'COMPLETED')}
                                className="flex items-center justify-center gap-2 bg-green-500 hover:bg-green-600 text-white py-2 rounded-xl text-[9px] font-black uppercase transition-all shadow-md active:scale-95"
                             >
                                <span className="material-icons-round text-xs">check_circle</span>
                                ENTREGADO
                             </button>
                           )}
                           <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               onDeleteOrder(o.id);
                             }}
                             className="flex items-center justify-center gap-2 bg-red-50 hover:bg-red-600 text-red-500 hover:text-white py-2.5 rounded-xl text-[9px] font-black uppercase transition-all active:scale-95 shadow-sm border border-red-100"
                           >
                             <span className="material-icons-round text-sm">delete_forever</span>
                             ELIMINAR
                           </button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Resto de pestañas... */}
            {activeTab === 'SIZES' && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <button onClick={addSize} className="bg-primary/5 border-2 border-dashed border-primary/20 p-10 rounded-3xl flex flex-col items-center justify-center gap-2 hover:bg-primary/10 transition-all">
                  <span className="material-icons-round text-primary text-5xl">add_circle</span>
                  <span className="text-[10px] font-black uppercase text-primary">Nuevo Molde</span>
                </button>
                {config.sizes.map(s => (
                  <div key={s.id} className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6 relative group">
                    <button onClick={() => removeSize(s.id)} className="absolute top-4 right-4 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><span className="material-icons-round text-sm">delete</span></button>
                    <div className="grid grid-cols-2 gap-4">
                       <div>
                         <label className="text-[8px] font-black uppercase text-slate-400">Diámetro (cm)</label>
                         <input type="number" className="w-full bg-slate-50 rounded-xl p-3 font-bold border-none text-sm" value={s.diameter} onChange={(e) => updateSize(s.id, 'diameter', parseInt(e.target.value))} />
                       </div>
                       <div>
                         <label className="text-[8px] font-black uppercase text-slate-400">Altura</label>
                         <select className="w-full bg-slate-50 rounded-xl p-3 text-[10px] font-bold border-none" value={s.heightType} onChange={(e) => updateSize(s.id, 'heightType', e.target.value)}>
                            <option value="SHORT">BAJO</option><option value="TALL">ALTO</option>
                         </select>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Las demás secciones permanecen igual por brevedad */}
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useCallback, useEffect } from 'react';
import { Step, AppState, AppConfig, Order, CakeSize, Flavor, Filling } from './types';
import { CAKE_SIZES, FLAVORS, FILLINGS, DECORATIONS, TOPPER_PRICES, SPHERES_PRICE, CAKE_COLORS, SATURATED_COLOR_SURCHARGE } from './constants';
import SizeStep from './components/SizeStep';
import FlavorStep from './components/FlavorStep';
import DecorationStep from './components/DecorationStep';
import PersonalizationStep from './components/PersonalizationStep';
import SummaryStep from './components/SummaryStep';
import PaymentStep from './components/PaymentStep';
import SuccessStep from './components/SuccessStep';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';

// Firebase imports
import { db } from './firebase';
import { collection, onSnapshot, doc, setDoc, getDoc, deleteDoc, updateDoc } from 'firebase/firestore';

const DEFAULT_CONFIG: AppConfig = {
  sizes: CAKE_SIZES,
  flavors: FLAVORS,
  fillings: FILLINGS,
  colors: CAKE_COLORS,
  decorations: DECORATIONS,
  topperPrices: TOPPER_PRICES,
  spheresPrice: SPHERES_PRICE,
  saturatedColorSurcharge: SATURATED_COLOR_SURCHARGE,
  coverageSurcharges: { chantilly: 0, chocolate: 5, arequipe: 4 },
  paymentDetails: {
    bankName: "Banco de Venezuela",
    accountHolder: "Tu Nombre Aquí",
    zelleEmail: "tu@correo.com",
    taxId: "V-00000000",
    exchangeRateNote: "Tasa BCV del día"
  },
  appTheme: {
    brandName: "MathiCake Studio",
    whatsappNumber: "584240000000",
    primaryColor: "#E31C58",
    secondaryColor: "#FFEB3B",
    backgroundColor: "#FFFBF2",
    textColor: "#000000",
    surfaceColor: "#FFFFFF"
  }
};

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);
  const [orders, setOrders] = useState<Order[]>([]);
  const [firebaseError, setFirebaseError] = useState<string | null>(null);

  // --- NAVEGACIÓN Y ESTADO ---
  const navigateTo = (step: Step) => setState(prev => ({ ...prev, step }));
  const updateAppState = (updates: Partial<AppState>) => setState(prev => ({ ...prev, ...updates }));
  const resetApp = () => setState(prev => ({ ...prev, step: 'SIZE' }));

  const handleSelectSize = (s: CakeSize) => updateAppState({ selectedSize: s });
  const handleGoToFlavor = () => navigateTo('FLAVOR');
  const handleGoToAdminLogin = () => navigateTo('ADMIN_LOGIN');
  const handleSelectFlavor = (f: Flavor) => updateAppState({ selectedFlavor: f });
  const handleSelectFilling = (fill: Filling) => updateAppState({ selectedFilling: fill });
  const handleGoToDecoration = () => navigateTo('DECORATION');
  const handleGoToSize = () => navigateTo('SIZE');
  const handleCustomFillingChange = (v: string) => updateAppState({ customFilling: v });
  const handleUpdateDecoration = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToPersonalization = () => navigateTo('PERSONALIZATION');
  const handleUpdatePersonalization = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToSummary = () => navigateTo('SUMMARY');
  const handleUpdateSummary = (d: Partial<AppState>) => updateAppState(d);
  const handleGoToPayment = () => navigateTo('PAYMENT');
  const handleUpdatePayment = (d: any) => updateAppState(d);
  const handleLoginSuccess = () => navigateTo('ADMIN_PANEL');

  // --- GESTIÓN DE PEDIDOS ---
  const handleDeleteOrder = async (orderId: string) => {
    if (!db) return;

    // Alerta de confirmación inmediata
    if (window.confirm(`¿Seguro que deseas ELIMINAR permanentemente la orden ${orderId}?`)) {
      try {
        console.log(`Intentando eliminar orden: ${orderId}`);

        // 1. ELIMINACIÓN OPTIMISTA (Desaparece de inmediato de la UI local)
        // Guardamos los pedidos actuales por si necesitamos revertir
        const previousOrders = [...orders];
        setOrders(prev => prev.filter(o => o.id !== orderId));

        // 2. ELIMINACIÓN REAL EN FIRESTORE
        const orderRef = doc(db, "orders", orderId);
        await deleteDoc(orderRef);
        console.log("Orden eliminada exitosamente en Firestore");
      } catch (e: any) {
        console.error("Error crítico al eliminar pedido:", e);
        alert(`No se pudo eliminar el pedido de la base de datos: ${e.message}`);
        // El snapshot de Firestore restaurará la lista automáticamente si falló el borrado remoto
      }
    }
  };

  const handleUpdateOrderStatus = async (orderId: string, status: 'PENDING' | 'COMPLETED') => {
    if (!db) return;
    try {
      const orderRef = doc(db, "orders", orderId);
      await updateDoc(orderRef, { status });
    } catch (e: any) {
      console.error("Error al actualizar estado:", e);
      alert(`Error: ${e.message}`);
    }
  };

  // --- FIREBASE SYNC ---
  useEffect(() => {
    if (!db) return;
    const configDocRef = doc(db, "settings", "appConfig");

    const initConfig = async () => {
      try {
        const docSnap = await getDoc(configDocRef);
        if (docSnap.exists()) {
          setConfig({ ...DEFAULT_CONFIG, ...docSnap.data() } as AppConfig);
        } else {
          await setDoc(configDocRef, DEFAULT_CONFIG);
        }
      } catch (e: any) {
        if (e.code === 'permission-denied') setFirebaseError("Acceso denegado a Firestore");
      }
    };
    initConfig();

    const unsubscribeConfig = onSnapshot(configDocRef, (docSnap) => {
      if (docSnap.exists()) setConfig(prev => ({ ...prev, ...docSnap.data() }));
    });

    const unsubscribeOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      const remoteOrders: Order[] = [];
      snapshot.forEach((doc) => { remoteOrders.push({ ...doc.data(), id: doc.id } as Order); });
      // Ordenar por fecha descendente
      remoteOrders.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setOrders(remoteOrders);
    });

    return () => { unsubscribeConfig(); unsubscribeOrders(); };
  }, []);

  // --- THEME ---
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--primary-color', config.appTheme.primaryColor);
    root.style.setProperty('--secondary-color', config.appTheme.secondaryColor);
    root.style.setProperty('--bg-color', config.appTheme.backgroundColor);
    root.style.setProperty('--text-color', config.appTheme.textColor);
    root.style.setProperty('--surface-color', config.appTheme.surfaceColor);
  }, [config.appTheme]);

  const [state, setState] = useState<AppState>({
    step: 'SIZE',
    selectedSize: config.sizes[1],
    selectedFlavor: config.flavors[0],
    selectedFilling: config.fillings[1],
    selectedDecoration: 'liso',
    cakeColors: ['#FFFFFF'],
    topperType: 'none',
    hasSpheres: false,
    theme: '',
    birthdayName: '',
    birthdayAge: '',
    specialRequirements: '',
    referenceImage: null,
    paymentProof: null,
    paymentReference: '',
    amountBs: '',
    deliveryMethod: 'PICKUP',
    deliveryDate: '',
    deliveryTime: '',
    coverageType: 'chantilly',
    totalPrice: 45,
    customFilling: '',
    paymentStrategy: 'FIFTY_PERCENT',
  });

  const calculateTotal = useCallback(() => {
    const size = config.sizes.find(s => s.id === state.selectedSize?.id) || config.sizes[0];
    const flavor = config.flavors.find(f => f.id === state.selectedFlavor?.id) || config.flavors[0];
    const filling = config.fillings.find(f => f.id === state.selectedFilling?.id) || config.fillings[0];
    const decor = config.decorations[state.selectedDecoration] || { priceModifier: 0 };
    const factor = size.costMultiplier || 1.0;
    let total = size.basePrice + (flavor.priceModifier * factor) + (filling.priceModifier * factor) + (decor.priceModifier * factor) + (config.coverageSurcharges[state.coverageType] * factor) + (config.topperPrices[state.topperType] || 0);
    if (state.hasSpheres) total += (config.spheresPrice * factor);
    const hasSaturated = state.cakeColors.some(hex => config.colors.find(c => c.hex === hex)?.isSaturated);
    if (hasSaturated) total += (config.saturatedColorSurcharge * factor);
    return total;
  }, [state, config]);

  useEffect(() => {
    setState(prev => ({ ...prev, totalPrice: calculateTotal() }));
  }, [state.selectedSize, state.selectedFlavor, state.selectedFilling, state.selectedDecoration, state.coverageType, state.topperType, state.hasSpheres, state.cakeColors, config, calculateTotal]);

  const handleUpdateConfig = async (newConfig: AppConfig) => {
    setConfig(newConfig);
    if (db) await setDoc(doc(db, "settings", "appConfig"), newConfig);
  };

  const handleFinalizeOrder = async () => {
    const simpleId = Math.random().toString(36).substr(2, 6).toUpperCase();
    try {
      const decorLabel = config.decorations[state.selectedDecoration]?.label || 'Liso';
      const colorNames = state.cakeColors.map(hex => config.colors.find(c => c.hex === hex)?.name || 'Personalizado').join(', ');
      const detailedInfo = `🎂 PASTEL ${state.selectedSize?.diameter}cm\n🍰 Bizcocho: ${state.selectedFlavor?.name}\n🍦 Relleno: ${state.selectedFilling?.id === 'others' ? state.customFilling : state.selectedFilling?.name}\n✨ Estilo: ${decorLabel}\n🎨 Colores: ${colorNames}\n🎯 Cobertura: ${state.coverageType.toUpperCase()}\n🚀 Extras: ${state.topperType !== 'none' ? 'Topper ' + state.topperType : 'Sin Topper'}${state.hasSpheres ? ', con Esferas' : ''}\n🎉 Temática: ${state.theme}\n📍 Entrega: ${state.deliveryMethod} - ${state.deliveryDate}`;
      const newOrder: Order = { id: simpleId, date: new Date().toLocaleString(), customerName: state.birthdayName || 'Cliente Web', details: detailedInfo, total: state.totalPrice, status: 'PENDING' };
      if (db) await setDoc(doc(db, "orders", simpleId), newOrder);
      window.open(`https://wa.me/${config.appTheme.whatsappNumber}?text=${encodeURIComponent(`🎂 *NUEVO PEDIDO* (Ref: ${simpleId})\n\n${detailedInfo}\n\n💰 Total: $${state.totalPrice.toFixed(2)}`)}`, '_blank');
      setState(prev => ({ ...prev, step: 'SUCCESS', lastOrderId: simpleId }));
    } catch (error) { console.error("Error crítico:", error); }
  };

  return (
    <div className="w-full h-full flex flex-col font-quicksand overflow-hidden bg-background-light">
        {firebaseError && (
          <div className="bg-red-600 text-white text-[10px] md:text-xs py-2 px-4 text-center font-black uppercase tracking-widest z-[200] flex flex-col items-center justify-center gap-1 shadow-2xl border-b-2 border-red-800">
            <div className="flex items-center gap-2"><span className="material-icons-round text-sm animate-pulse">error_outline</span>{firebaseError}</div>
          </div>
        )}

        {!['ADMIN_PANEL'].includes(state.step) && (
          <div className="w-full bg-primary h-16 md:h-20 flex items-center justify-center relative shrink-0 z-[60] shadow-md px-4">
             {config.appTheme.logoUrl ? <img src={config.appTheme.logoUrl} className="h-10 md:h-14 object-contain" alt="Logo" /> : <h2 className="font-display text-xl md:text-2xl text-white tracking-widest uppercase italic">{config.appTheme.brandName}</h2>}
          </div>
        )}

        <div className="flex-1 overflow-hidden flex flex-col relative">
            {state.step === 'SIZE' && <SizeStep selectedSize={state.selectedSize} onSelectSize={handleSelectSize} onNext={handleGoToFlavor} onAdminClick={handleGoToAdminLogin} config={config} />}
            {state.step === 'FLAVOR' && <FlavorStep {...state} onSelectFlavor={handleSelectFlavor} onSelectFilling={handleSelectFilling} onNext={handleGoToDecoration} onBack={handleGoToSize} onCustomFillingChange={handleCustomFillingChange} config={config} />}
            {state.step === 'DECORATION' && <DecorationStep {...state} onUpdateDecoration={handleUpdateDecoration} onNext={handleGoToPersonalization} onBack={handleGoToFlavor} config={config} />}
            {state.step === 'PERSONALIZATION' && <PersonalizationStep appState={state} onUpdate={handleUpdatePersonalization} onNext={handleGoToSummary} onBack={handleGoToDecoration} />}
            {state.step === 'SUMMARY' && <SummaryStep appState={state} onUpdate={handleUpdateSummary} onBack={handleGoToPersonalization} onConfirm={handleGoToPayment} config={config} />}
            {state.step === 'PAYMENT' && <PaymentStep {...state} config={config} onUpdatePayment={handleUpdatePayment} onBack={handleGoToSummary} onComplete={handleFinalizeOrder} />}
            {state.step === 'SUCCESS' && <SuccessStep orderId={state.lastOrderId || ''} onReset={resetApp} config={config} />}
            {state.step === 'ADMIN_LOGIN' && <AdminLogin onLoginSuccess={handleLoginSuccess} onCancel={resetApp} />}
            {state.step === 'ADMIN_PANEL' && (
              <div className="fixed inset-0 z-[100]">
                <AdminPanel 
                  config={config} 
                  onUpdateConfig={handleUpdateConfig} 
                  orders={orders} 
                  onDeleteOrder={handleDeleteOrder}
                  onUpdateOrderStatus={handleUpdateOrderStatus}
                  onClearOrders={() => {}} 
                  onExit={resetApp} 
                />
              </div>
            )}
        </div>
    </div>
  );
};

export default App;

import React from 'react';
import { DecorationStyle, TopperType, AppState, AppConfig, CakeSize } from '../types';

interface DecorationStepProps {
  selectedSize: CakeSize | null;
  selectedDecoration: DecorationStyle;
  cakeColors: string[];
  topperType: TopperType;
  hasSpheres: boolean;
  onUpdateDecoration: (data: Partial<AppState>) => void;
  onNext: () => void;
  onBack: () => void;
  totalPrice: number;
  config: AppConfig;
}

const DecorationStep: React.FC<DecorationStepProps> = ({ 
  selectedSize,
  selectedDecoration, 
  cakeColors,
  topperType,
  hasSpheres,
  onUpdateDecoration, 
  onNext, 
  onBack,
  totalPrice,
  config
}) => {
  const styles = {
    liso: { label: "Liso", icon: "crop_square" },
    vintage: { label: "Vintage", icon: "auto_awesome" },
    textura: { label: "Textura", icon: "reorder" },
    degradado: { label: "Degradado", icon: "opacity" }
  };

  const topperOptions: { id: TopperType; label: string; icon: string; desc: string }[] = [
    { id: 'none', label: 'Sin Topper', icon: 'block', desc: 'Sencillo y elegante' },
    { id: 'generic', label: 'Genérico', icon: 'celebration', desc: 'Letreros estándar' },
    { id: 'personalized', label: 'Personalizado', icon: 'edit_note', desc: 'Nombre y edad' },
    { id: 'plus_pieces', label: 'Topper+Piezas', icon: 'auto_fix_high', desc: 'Set decorativo 3D' },
  ];

  const handleColorClick = (hex: string) => {
    if (selectedDecoration !== 'degradado') {
      onUpdateDecoration({ cakeColors: [hex] });
    } else {
      if (cakeColors.includes(hex)) {
        if (cakeColors.length > 1) {
          onUpdateDecoration({ cakeColors: cakeColors.filter(c => c !== hex) });
        }
      } else {
        if (cakeColors.length < 3) {
          onUpdateDecoration({ cakeColors: [...cakeColors, hex] });
        }
      }
    }
  };

  const renderCakeBody = () => {
    const customDecor = config.decorations[selectedDecoration];
    const primaryColor = cakeColors[0] || '#FFFFFF';

    if (customDecor?.textureUrl) {
      return (
        <g>
          <defs>
            <pattern id="decorPattern" patternUnits="userSpaceOnUse" width="110" height="170">
              <image href={customDecor.textureUrl} x="0" y="0" width="110" height="170" preserveAspectRatio="xMidYMid slice" />
            </pattern>
          </defs>
          <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill="url(#decorPattern)" stroke="rgba(0,0,0,0.1)" strokeWidth="1"></path>
          {cakeColors.length > 0 && <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill={primaryColor} fillOpacity="0.2" />}
        </g>
      );
    }

    if (selectedDecoration === 'degradado') {
      const stops = cakeColors.length === 1 
        ? [{ offset: '0%', color: '#FFFFFF' }, { offset: '100%', color: cakeColors[0] }]
        : cakeColors.map((color, i) => ({ offset: `${(i / (cakeColors.length - 1)) * 100}%`, color }));

      return (
        <g>
          <defs>
            <linearGradient id="cakeGrad" x1="0%" y1="0%" x2="0%" y2="100%">
              {stops.map((stop, i) => <stop key={i} offset={stop.offset} stopColor={stop.color} />)}
            </linearGradient>
          </defs>
          <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill="url(#cakeGrad)" stroke="rgba(0,0,0,0.1)" strokeWidth="1"></path>
        </g>
      );
    }

    return (
      <g>
        <path d="M45 100 L45 270 Q100 290 155 270 L155 100" fill={primaryColor} stroke="rgba(0,0,0,0.1)" strokeWidth="1"></path>
        {selectedDecoration === 'textura' && (
          <g opacity="0.9">
            <line x1="45" y1="130" x2="155" y2="130" stroke="rgba(0,0,0,0.15)" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="160" x2="155" y2="160" stroke="rgba(0,0,0,0.15)" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="190" x2="155" y2="190" stroke="rgba(0,0,0,0.15)" strokeWidth="2" strokeDasharray="1 3" />
            <line x1="45" y1="220" x2="155" y2="220" stroke="rgba(0,0,0,0.15)" strokeWidth="2" strokeDasharray="1 3" />
          </g>
        )}
        {selectedDecoration === 'vintage' && (
          <g>
            <path d="M45 100 Q60 80 75 100 Q90 80 105 100 Q120 80 135 100 Q150 80 155 100" fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="4" />
            <path d="M45 190 Q60 170 75 190 Q90 170 105 190 Q120 170 135 190 Q150 170 155 190" fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="4" />
          </g>
        )}
      </g>
    );
  };

  return (
    <div className="flex flex-col h-full bg-background-light relative animate-fadeIn overflow-hidden">
      <header className="pt-6 pb-3 px-4 md:pt-8 md:pb-4 md:px-8 flex items-center justify-between z-20 bg-white shadow-soft border-b border-gray-100 shrink-0">
        <div className="flex items-center gap-3 md:gap-6">
          <button onClick={onBack} className="w-10 h-10 md:w-14 md:h-14 rounded-full bg-white flex items-center justify-center text-primary transition-all active:scale-90 border border-gray-100 shadow-soft">
            <span className="material-icons-round text-lg md:text-2xl font-bold">arrow_back</span>
          </button>
          <div className="flex flex-col">
            <span className="text-[9px] md:text-[12px] font-black text-primary/60 uppercase tracking-[0.2em]">Paso 3: Diseño</span>
            <h1 className="text-lg md:text-3xl font-display text-black uppercase leading-none">Personalización</h1>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row w-full z-10 overflow-hidden">
        {/* VISTA PREVIA DEL PASTEL */}
        <div className="w-full md:w-[40%] bg-slate-50 flex flex-col items-center justify-center p-4 md:p-10 border-b md:border-b-0 md:border-r border-gray-100 shrink-0 md:shrink overflow-hidden">
          <div className="relative w-full max-w-[200px] md:max-w-[320px] filter drop-shadow-[0_25px_45px_rgba(0,0,0,0.1)] transform transition-transform duration-700 hover:scale-105">
            <svg className="w-full h-full" viewBox="0 0 200 300" preserveAspectRatio="xMidYMid meet">
              <ellipse cx="100" cy="285" fill="rgba(0,0,0,0.1)" rx="85" ry="12"></ellipse>
              {renderCakeBody()}
              <ellipse cx="100" cy="100" fill="#FFFFFF" rx="55" ry="15" stroke="rgba(0,0,0,0.05)" strokeWidth="1"></ellipse>
              {topperType !== 'none' && (
                <g className="animate-pop">
                   <line x1="100" y1="40" x2="100" y2="90" stroke="rgba(0,0,0,0.2)" strokeWidth="2" />
                   <rect x="70" y="5" width="60" height="45" rx="10" fill="var(--primary-color)" />
                   <text x="100" y="32" textAnchor="middle" fill="white" fontSize="10" fontWeight="900" style={{fontFamily: 'Fredoka One'}}>TOPPER</text>
                </g>
              )}
              {hasSpheres && (
                <g className="animate-pop">
                  <circle cx={155} cy={130} r={16} fill="var(--primary-color)" fillOpacity="0.8" />
                  <circle cx={172} cy={165} r={12} fill="var(--secondary-color)" fillOpacity="0.8" />
                </g>
              )}
            </svg>
          </div>
        </div>

        {/* OPCIONES DE DISEÑO */}
        <div className="flex-1 overflow-y-auto no-scrollbar p-5 md:p-10 space-y-10 md:space-y-16 pb-20 bg-white">
          <section>
            <h3 className="text-[13px] md:text-[16px] font-black text-black uppercase tracking-[0.2em] mb-6 flex items-center gap-3 border-l-4 border-primary pl-4">
               1. Estilo de Cobertura
            </h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {Object.keys(config.decorations).map(key => {
                const decor = config.decorations[key];
                const isSelected = selectedDecoration === key;
                const standardIcon = (styles as any)[key]?.icon || 'auto_fix_normal';

                return (
                  <button 
                    key={key}
                    onClick={() => onUpdateDecoration({ selectedDecoration: key })}
                    className={`flex flex-col items-center gap-4 p-5 md:p-8 rounded-[2rem] border-2 transition-all shadow-soft overflow-hidden relative ${isSelected ? 'border-primary bg-primary/5 scale-105' : 'border-gray-50 bg-white hover:border-gray-200'}`}
                  >
                    {decor.textureUrl ? (
                      <img src={decor.textureUrl} className="w-16 h-16 md:w-24 md:h-24 rounded-2xl object-cover mb-2 border border-gray-100" />
                    ) : (
                      <span className={`material-icons-round text-4xl md:text-6xl ${isSelected ? 'text-primary' : 'text-gray-300'}`}>{standardIcon}</span>
                    )}
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-widest text-center text-black leading-tight">{decor.label}</span>
                  </button>
                );
              })}
            </div>
          </section>

          <section>
            <h3 className="text-[13px] md:text-[16px] font-black text-black uppercase tracking-[0.2em] mb-6 flex items-center gap-3 border-l-4 border-primary pl-4">
               2. Paleta de Colores
            </h3>
            <div className="flex flex-wrap gap-3 md:gap-5">
              {config.colors.map((color) => {
                const isSelected = cakeColors.includes(color.hex);
                return (
                  <button
                    key={color.name}
                    onClick={() => handleColorClick(color.hex)}
                    className={`w-10 h-10 md:w-14 md:h-14 rounded-full border-2 shadow-soft transition-all transform active:scale-90 relative flex items-center justify-center ${isSelected ? 'border-primary scale-110 ring-4 ring-primary/10' : 'border-gray-100 hover:scale-105'}`}
                    style={{ backgroundColor: color.hex }}
                  >
                    {isSelected && <span className={`material-icons-round ${color.hex === '#FFFFFF' ? 'text-primary' : 'text-white'} text-xl md:text-3xl font-black drop-shadow-lg`}>check</span>}
                  </button>
                );
              })}
            </div>
          </section>

          <section>
            <h3 className="text-[13px] md:text-[16px] font-black text-black uppercase tracking-[0.2em] mb-8 flex items-center gap-3 border-l-4 border-primary pl-4">
               3. Toppers Sugeridos
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-8">
              {topperOptions.map(t => {
                const isSelected = topperType === t.id;
                const price = config.topperPrices[t.id] || 0;
                return (
                  <button 
                    key={t.id}
                    onClick={() => onUpdateDecoration({ topperType: t.id })}
                    className={`flex items-center gap-5 p-5 md:p-6 rounded-[2.5rem] border-2 transition-all relative group shadow-soft ${isSelected ? 'border-primary bg-primary/5 scale-[1.03] ring-4 ring-primary/5' : 'border-gray-50 bg-white hover:border-gray-200'}`}
                  >
                    <div className={`w-14 h-14 md:w-20 md:h-20 rounded-[1.8rem] flex items-center justify-center transition-all ${isSelected ? 'bg-primary text-white' : 'bg-slate-50 text-gray-400 group-hover:bg-slate-100'}`}>
                      <span className="material-icons-round text-2xl md:text-4xl">{t.icon}</span>
                    </div>
                    <div className="flex-1 text-left">
                      <span className="text-[11px] md:text-sm font-black uppercase tracking-tight text-black block mb-0.5">{t.label}</span>
                      <span className="text-[9px] md:text-[11px] text-slate-400 font-bold uppercase block leading-tight">{t.desc}</span>
                    </div>
                    <div className="flex flex-col items-end">
                      {price > 0 ? (
                        <div className={`px-3 py-1.5 rounded-full font-black text-[10px] md:text-xs tracking-tighter shadow-sm ${isSelected ? 'bg-primary text-white' : 'bg-primary/10 text-primary'}`}>
                          +${price.toFixed(2)}
                        </div>
                      ) : (
                        <div className="text-[10px] text-slate-300 font-black uppercase tracking-widest px-2">Incluido</div>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>

            {/* ESFERAS DECORATIVAS */}
            <div className={`p-6 md:p-8 rounded-[3rem] transition-all border-2 flex items-center justify-between group cursor-pointer ${hasSpheres ? 'bg-primary shadow-xl-primary border-primary scale-[1.02]' : 'bg-white shadow-soft border-gray-100 hover:border-gray-300'}`}
                 onClick={() => onUpdateDecoration({ hasSpheres: !hasSpheres })}
            >
               <div className="flex items-center gap-5 md:gap-8">
                  <div className={`w-14 h-14 md:w-20 md:h-20 rounded-full flex items-center justify-center transition-all shadow-inner ${hasSpheres ? 'bg-white text-primary' : 'bg-slate-50 text-gray-300'}`}>
                     <span className="material-icons-round text-3xl md:text-5xl">lens</span>
                  </div>
                  <div className="flex flex-col">
                    <span className={`text-sm md:text-xl font-black uppercase tracking-widest leading-none mb-1 md:mb-2 ${hasSpheres ? 'text-white' : 'text-black'}`}>Esferas Decorativas</span>
                    <div className="flex items-center gap-2">
                      <span className={`text-[10px] md:text-xs font-black uppercase bg-white/20 px-3 py-1 rounded-full border border-white/20 ${hasSpheres ? 'text-white' : 'text-primary bg-primary/5 border-primary/10'}`}>
                        +${config.spheresPrice.toFixed(2)}
                      </span>
                    </div>
                  </div>
               </div>
               <div className={`w-16 h-10 md:w-24 md:h-12 rounded-full relative flex items-center px-2 transition-all ${hasSpheres ? 'bg-white/20' : 'bg-gray-100'}`}>
                  <div className={`w-6 h-6 md:w-8 md:h-8 rounded-full shadow-lg transform transition-transform duration-500 ${hasSpheres ? 'translate-x-6 md:translate-x-12 bg-white' : 'translate-x-0 bg-gray-300'}`}></div>
               </div>
            </div>
          </section>
        </div>
      </main>

      <footer className="bg-surface-light p-5 md:p-8 z-50 shadow-[0_-15px_35px_rgba(0,0,0,0.03)] rounded-t-[2.5rem] md:rounded-t-[3.5rem] border-t border-gray-100 shrink-0">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-5 md:gap-8">
          <div className="flex flex-wrap justify-center md:justify-start items-center gap-6 md:gap-10">
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[9px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mb-0.5">Seleccionado</span>
              <div className="flex items-baseline justify-center md:justify-start gap-2.5">
                <span className="text-2xl md:text-4xl font-display text-black">{selectedSize?.diameter}cm</span>
                <span className="text-[9px] md:text-[11px] font-black text-primary uppercase bg-primary/5 px-3 md:px-4 py-0.5 rounded-lg border border-primary/10">
                  {selectedSize?.portions || 'N/A'}
                </span>
              </div>
            </div>
            <div className="w-px h-10 bg-gray-100 hidden md:block"></div>
            <div className="flex flex-col text-center md:text-left">
              <span className="text-[9px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mb-0.5">Total Estimado</span>
              <span className="text-2xl md:text-4xl font-display text-primary tracking-tighter">${totalPrice.toFixed(2)}</span>
            </div>
          </div>
          <button 
            onClick={onNext}
            className="w-full md:w-auto bg-primary hover:bg-rose-600 text-white font-black py-4 md:py-5 px-10 md:px-14 rounded-[1.8rem] md:rounded-[2.5rem] shadow-xl-primary transition-all active:scale-[0.98] flex items-center justify-center gap-3 md:gap-5 group text-xs md:text-sm border-2 md:border-4 border-white/10 uppercase tracking-[0.2em]"
          >
            Siguiente
            <span className="material-icons-round text-lg md:text-2xl group-hover:translate-x-1.5 transition-transform">arrow_forward</span>
          </button>
        </div>
      </footer>
    </div>
  );
};

export default DecorationStep;

import React, { useState, useEffect } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, DecorationInfo } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onDeleteOrder: (id: string) => void;
  onUpdateOrderStatus: (id: string, status: 'PENDING' | 'COMPLETED') => void;
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onDeleteOrder, onUpdateOrderStatus, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isSaving) {
      const timer = setTimeout(() => setIsSaving(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [isSaving]);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    setIsSaving(true);
    onUpdateConfig({ ...config, ...newPart });
  };

  const updateSize = (id: string, f: keyof CakeSize, v: any) => {
    updateConfig({ sizes: config.sizes.map(s => s.id === id ? { ...s, [f]: v } : s) });
  };
  const addSize = () => {
    const n: CakeSize = { id: `sz_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porc', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, n] });
  };
  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  const updateFlavor = (id: string, f: keyof Flavor, v: any) => {
    updateConfig({ flavors: config.flavors.map(fl => fl.id === id ? { ...fl, [f]: v } : fl) });
  };
  const addFlavor = () => {
    const n: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, n] });
  };

  const updateFilling = (id: string, f: keyof Filling, v: any) => {
    updateConfig({ fillings: config.fillings.map(fill => fill.id === id ? { ...fill, [f]: v } : fill) });
  };
  const addFilling = () => {
    const n: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, n] });
  };

  const updateDecoration = (id: string, f: keyof DecorationInfo, v: any) => {
    const next = { ...config.decorations };
    next[id] = { ...next[id], [f]: v };
    updateConfig({ decorations: next });
  };
  const addDecoration = () => {
    const id = `dec_${Date.now()}`;
    const next = { ...config.decorations };
    next[id] = { id, label: 'Nuevo Estilo', priceModifier: 10 };
    updateConfig({ decorations: next });
  };

  const handleImageUpload = (id: string, type: 'flavor' | 'filling' | 'decoration', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onloadend = () => {
        const b64 = r.result as string;
        if (type === 'flavor') updateFlavor(id, 'textureUrl', b64);
        else if (type === 'filling') updateFilling(id, 'textureUrl', b64);
        else if (type === 'decoration') updateDecoration(id, 'textureUrl', b64);
      };
      r.readAsDataURL(file);
    }
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos', icon: 'auto_fix_high' },
    { id: 'PRICES', label: 'Precios Extras', icon: 'sell' },
    { id: 'PAYMENTS', label: 'Banco/Pagos', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca/Logo', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-quicksand overflow-hidden">
      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 z-[120] transition-transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-slate-800 text-white font-display uppercase tracking-widest flex items-center gap-3">
          <span className="material-icons-round text-primary">cake</span>
          Admin Mathi
        </div>
        <nav className="flex-1 p-4 space-y-1 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button key={item.id} onClick={() => { setActiveTab(item.id as any); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all ${activeTab === item.id ? 'bg-primary text-white shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-800'}`}>
              <span className="material-icons-round text-xl">{item.icon}</span>
              <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800">
          <button onClick={onExit} className="w-full bg-slate-800 hover:bg-red-600 text-white py-4 rounded-xl font-black uppercase text-xs transition-colors">Cerrar Sesión</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-200 px-6 md:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-600"><span className="material-icons-round">menu</span></button>
             <h2 className="text-lg font-black text-slate-800 uppercase tracking-tighter">{menuItems.find(i => i.id === activeTab)?.label}</h2>
          </div>
          {isSaving && (
            <div className="flex items-center gap-2 text-primary font-black uppercase text-[10px] animate-pulse">
              <span className="material-icons-round text-sm">sync</span>
              Sincronizando...
            </div>
          )}
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 no-scrollbar bg-slate-50/30">
          <div className="max-w-6xl mx-auto space-y-10 pb-20">

            {activeTab === 'ORDERS' && (
              <div className="space-y-4">
                {orders.length === 0 ? (
                  <div className="bg-white p-20 rounded-3xl border-2 border-dashed border-slate-200 text-center">
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Aún no hay pedidos registrados</p>
                  </div>
                ) : (
                  orders.map(o => (
                    <div key={o.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
                      <div className="w-16 h-16 bg-slate-50 rounded-xl flex items-center justify-center font-display text-primary border text-xl shrink-0">{o.id.slice(-4)}</div>
                      <div className="flex-1">
                        <h4 className="font-black text-slate-800 uppercase text-sm">{o.customerName}</h4>
                        <p className="text-[9px] text-slate-400 font-bold mb-2">{o.date}</p>
                        <p className="text-[11px] text-slate-600 whitespace-pre-line leading-relaxed">{o.details}</p>
                      </div>
                      <div className="text-right flex flex-col items-end gap-3 shrink-0">
                        <div className="flex flex-col items-end">
                            <p className="text-3xl font-display text-primary">${o.total.toFixed(2)}</p>
                            <span className={`text-[8px] font-black uppercase px-3 py-1 rounded-full border ${o.status === 'COMPLETED' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                                {o.status === 'COMPLETED' ? 'Entregado' : 'Pendiente'}
                            </span>
                        </div>
                        <div className="flex flex-col gap-2 w-full md:w-32">
                           {o.status === 'PENDING' && (
                             <button 
                                onClick={() => onUpdateOrderStatus(o.id, 'COMPLETED')}
                                className="flex items-center justify-center gap-2 bg-green-500 hover:bg-green-600 text-white py-2 rounded-xl text-[9px] font-black uppercase transition-all shadow-md active:scale-95"
                             >
                                <span className="material-icons-round text-xs">check_circle</span>
                                ENTREGADO
                             </button>
                           )}
                           <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               onDeleteOrder(o.id);
                             }}
                             className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-red-600 text-slate-400 hover:text-white py-2.5 rounded-xl text-[9px] font-black uppercase transition-all active:scale-95 shadow-sm border border-slate-200"
                           >
                             <span className="material-icons-round text-sm">delete_forever</span>
                             ELIMINAR
                           </button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Resto de pestañas simplificadas para este bloque de cambios */}
            {activeTab === 'SIZES' && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <button onClick={addSize} className="bg-primary/5 border-2 border-dashed border-primary/20 p-10 rounded-3xl flex flex-col items-center justify-center gap-2 hover:bg-primary/10 transition-all">
                  <span className="material-icons-round text-primary text-5xl">add_circle</span>
                  <span className="text-[10px] font-black uppercase text-primary">Nuevo Molde</span>
                </button>
                {config.sizes.map(s => (
                  <div key={s.id} className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6 relative group">
                    <button onClick={() => removeSize(s.id)} className="absolute top-4 right-4 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><span className="material-icons-round text-sm">delete</span></button>
                    <div className="grid grid-cols-2 gap-4">
                       <div>
                         <label className="text-[8px] font-black uppercase text-slate-400">Diámetro (cm)</label>
                         <input type="number" className="w-full bg-slate-50 rounded-xl p-3 font-bold border-none text-sm" value={s.diameter} onChange={(e) => updateSize(s.id, 'diameter', parseInt(e.target.value))} />
                       </div>
                       <div>
                         <label className="text-[8px] font-black uppercase text-slate-400">Altura</label>
                         <select className="w-full bg-slate-50 rounded-xl p-3 text-[10px] font-bold border-none" value={s.heightType} onChange={(e) => updateSize(s.id, 'heightType', e.target.value)}>
                            <option value="SHORT">BAJO</option><option value="TALL">ALTO</option>
                         </select>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { AppConfig, Order, CakeSize, Flavor, Filling, DecorationInfo } from '../types';

interface AdminPanelProps {
  config: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  orders: Order[];
  onDeleteOrder: (id: string) => void;
  onUpdateOrderStatus: (id: string, status: 'PENDING' | 'COMPLETED') => void;
  onClearOrders: () => void;
  onExit: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ config, onUpdateConfig, orders, onDeleteOrder, onUpdateOrderStatus, onClearOrders, onExit }) => {
  const [activeTab, setActiveTab] = useState<'ORDERS' | 'SIZES' | 'FLAVORS' | 'DECORATIONS' | 'COLORS' | 'PRICES' | 'PAYMENTS' | 'SETTINGS'>('ORDERS');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isSaving) {
      const timer = setTimeout(() => setIsSaving(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [isSaving]);

  const updateConfig = (newPart: Partial<AppConfig>) => {
    setIsSaving(true);
    onUpdateConfig({ ...config, ...newPart });
  };

  // --- MOLDES ---
  const updateSize = (id: string, f: keyof CakeSize, v: any) => {
    updateConfig({ sizes: config.sizes.map(s => s.id === id ? { ...s, [f]: v } : s) });
  };
  const addSize = () => {
    const n: CakeSize = { id: `sz_${Date.now()}`, diameter: 14, heightType: 'SHORT', portions: '8 Porc', basePrice: 20, costMultiplier: 1.0 };
    updateConfig({ sizes: [...config.sizes, n] });
  };
  const removeSize = (id: string) => {
    updateConfig({ sizes: config.sizes.filter(s => s.id !== id) });
  };

  // --- SABORES Y RELLENOS ---
  const updateFlavor = (id: string, f: keyof Flavor, v: any) => {
    updateConfig({ flavors: config.flavors.map(fl => fl.id === id ? { ...fl, [f]: v } : fl) });
  };
  const addFlavor = () => {
    const n: Flavor = { id: `fl_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ flavors: [...config.flavors, n] });
  };
  const removeFlavor = (id: string) => {
    updateConfig({ flavors: config.flavors.filter(f => f.id !== id) });
  };

  const updateFilling = (id: string, f: keyof Filling, v: any) => {
    updateConfig({ fillings: config.fillings.map(fill => fill.id === id ? { ...fill, [f]: v } : fill) });
  };
  const addFilling = () => {
    const n: Filling = { id: `fill_${Date.now()}`, name: 'Nuevo', color: '#FFFFFF', priceModifier: 0 };
    updateConfig({ fillings: [...config.fillings, n] });
  };
  const removeFilling = (id: string) => {
    updateConfig({ fillings: config.fillings.filter(f => f.id !== id) });
  };

  // --- DECORACIONES ---
  const updateDecoration = (id: string, f: keyof DecorationInfo, v: any) => {
    const next = { ...config.decorations };
    next[id] = { ...next[id], [f]: v };
    updateConfig({ decorations: next });
  };

  const handleImageUpload = (id: string, type: 'flavor' | 'filling' | 'decoration', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onloadend = () => {
        const b64 = r.result as string;
        if (type === 'flavor') updateFlavor(id, 'textureUrl', b64);
        else if (type === 'filling') updateFilling(id, 'textureUrl', b64);
        else if (type === 'decoration') updateDecoration(id, 'textureUrl', b64);
      };
      r.readAsDataURL(file);
    }
  };

  const menuItems = [
    { id: 'ORDERS', label: 'Ventas', icon: 'analytics' },
    { id: 'SIZES', label: 'Moldes', icon: 'straighten' },
    { id: 'FLAVORS', label: 'Sabores/Rellenos', icon: 'restaurant_menu' },
    { id: 'DECORATIONS', label: 'Estilos', icon: 'auto_fix_high' },
    { id: 'COLORS', label: 'Colores', icon: 'palette' },
    { id: 'PRICES', label: 'Precios Extras', icon: 'sell' },
    { id: 'PAYMENTS', label: 'Banco/Pagos', icon: 'account_balance' },
    { id: 'SETTINGS', label: 'Marca/Logo', icon: 'settings' },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-quicksand overflow-hidden">
      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 z-[120] transition-transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-slate-800 text-white font-display uppercase tracking-widest flex items-center gap-3">
          <span className="material-icons-round text-primary">cake</span>
          Admin Mathi
        </div>
        <nav className="flex-1 p-4 space-y-1 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button key={item.id} onClick={() => { setActiveTab(item.id as any); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all ${activeTab === item.id ? 'bg-primary text-white shadow-xl scale-105' : 'text-slate-400 hover:bg-slate-800'}`}>
              <span className="material-icons-round text-xl">{item.icon}</span>
              <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800">
          <button onClick={onExit} className="w-full bg-slate-800 hover:bg-red-600 text-white py-4 rounded-xl font-black uppercase text-xs transition-colors">Cerrar Sesión</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-200 px-6 md:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-600"><span className="material-icons-round">menu</span></button>
             <h2 className="text-lg font-black text-slate-800 uppercase tracking-tighter">{menuItems.find(i => i.id === activeTab)?.label}</h2>
          </div>
          {isSaving && (
            <div className="flex items-center gap-2 text-primary font-black uppercase text-[10px] animate-pulse">
              <span className="material-icons-round text-sm">sync</span>
              Sincronizando...
            </div>
          )}
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 no-scrollbar bg-slate-50/30">
          <div className="max-w-6xl mx-auto space-y-10 pb-20">

            {activeTab === 'ORDERS' && (
              <div className="space-y-4">
                {orders.length === 0 ? (
                  <div className="bg-white p-20 rounded-3xl border-2 border-dashed border-slate-200 text-center">
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Aún no hay pedidos registrados</p>
                  </div>
                ) : (
                  orders.map(o => (
                    <div key={o.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
                      <div className="w-16 h-16 bg-slate-50 rounded-xl flex items-center justify-center font-display text-primary border text-xl shrink-0">{o.id.slice(-4)}</div>
                      <div className="flex-1">
                        <h4 className="font-black text-slate-800 uppercase text-sm">{o.customerName}</h4>
                        <p className="text-[9px] text-slate-400 font-bold mb-2">{o.date}</p>
